def test_windows_daemon_cleanup_bounds_child_writable_state(tmp_path: Path) -> None:
    from usd_server.app import MAX_SERVER_STATE_BYTES

    state_dir = tmp_path / ".usd-cli"
    state_dir.mkdir()
    state_path = state_dir / "server.json"
    oversized = json.dumps(
        {
            "pid": 123,
            "process_start_token": "token",
            "instance_id": "instance",
            "padding": "x" * MAX_SERVER_STATE_BYTES,
        }
    ).encode()
    state_path.write_bytes(oversized)

    windows_usd_cli_daemon._remove_server_state_if_owned(
        SimpleNamespace(state_dir=state_dir),
        daemon_pid=123,
        process_start_token="token",
        instance_id="instance",
    )

    assert state_path.read_bytes() == oversized


@pytest.fixture(autouse=True)
def _skip_when_windows_symlink_privilege_is_unavailable(
    monkeypatch: pytest.MonkeyPatch,
    request: pytest.FixtureRequest,
) -> Iterator[None]:
    # Provider unit tests stub the host prerequisite; the dedicated tests below
    # exercise the supported-host preflight and its fail-closed diagnostics.
    if request.node.name != "test_windows_claude_preflight_reports_unsupported_host":
        monkeypatch.setattr(
            runner,
            "preflight_claude_windows_sandbox",
            lambda _working_directory, *, platform_name=os.name: None,
        )
    if os.name != "nt":
        yield
        return

    real_symlink_to = Path.symlink_to

    def symlink_to(
        path: Path,
        target: str | os.PathLike[str],
        target_is_directory: bool = False,
    ) -> None:
        try:
            real_symlink_to(
                path,
                target,
                target_is_directory=target_is_directory,
            )
        except OSError as exc:
            # pytest's numbered temp-directory factory probes its own
            # ``*-current`` convenience links and already tolerates an
            # unavailable symlink privilege. Only skip when the test itself
            # needs to create a link fixture.
            if getattr(exc, "winerror", None) == 1314 and not path.name.endswith(
                "current"
            ):
                pytest.skip(f"Windows symlink creation is unavailable: {exc}")
            raise

    monkeypatch.setattr(Path, "symlink_to", symlink_to)
    yield


@pytest.mark.skipif(os.name != "nt", reason="Windows PowerShell write guidance")
def test_windows_controlled_json_write_is_atomic_and_non_clobbering() -> None:
    assert "content-workflow-cli artifact write-json" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "canonical forward-slash path" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "rejects an existing destination" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "Get-Content -LiteralPath <relative/path.json> -Raw" in (
        CONTROLLED_JSON_ARTIFACT_WRITE
    )
    assert "python '<absolute-helper.py>'" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert r"{\"note\":\"two\u0020words\"}" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "PowerShell 5.1" in CONTROLLED_JSON_ARTIFACT_WRITE
    assert (
        "do not retry an equivalent shell" in CONTROLLED_JSON_ARTIFACT_WRITE.casefold()
    )
    assert "ConvertFrom-Json" not in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "WriteAllText" not in CONTROLLED_JSON_ARTIFACT_WRITE
    assert "-Force" not in CONTROLLED_JSON_ARTIFACT_WRITE


def _append_observable_command_status(
    path: Path,
    *,
    command: str,
    status: str,
) -> None:
    with path.open("a", encoding="utf-8", newline="\n") as stream:
        stream.write(
            json.dumps(
                {
                    "schema_version": "content-agents.observable-insight.v1",
                    "id": f"{command}:{status}",
                    "phase": "reasoning",
                    "source": "codex_sdk",
                    "status": "error" if status == "declined" else "success",
                    "kind": "action",
                    "title": "Agent action finished",
                    "summary": command,
                    "next_action": f"Command status: {status}.",
                }
            )
            + "\n"
        )


def _write_trusted_material_skill_catalog(repo_root: Path) -> None:
    for skill_name in ("usd-cli", "content-workflow-material"):
        skill_dir = repo_root / "agentic" / ".agents" / "skills" / skill_name
        skill_dir.mkdir(parents=True)
        (skill_dir / "SKILL.md").write_text("trusted\n", encoding="utf-8")


@pytest.mark.skipif(os.name != "nt", reason="Windows command-policy watchdog")
def test_windows_child_watchdog_fails_repeated_identical_policy_denial(
    tmp_path: Path,
) -> None:
    events = tmp_path / "events.jsonl"
    watchdog = runner._make_windows_child_command_watchdog(events)
    assert watchdog is not None

    _append_observable_command_status(
        events, command="blocked-command", status="declined"
    )
    assert watchdog() is None
    _append_observable_command_status(
        events, command="blocked-command", status="declined"
    )
    failure = watchdog()

    assert failure is not None
    assert failure.fatal is True
    assert "same command 2 times" in failure.reason


@pytest.mark.skipif(os.name != "nt", reason="Windows command-policy watchdog")
def test_windows_child_watchdog_resets_denials_after_command_progress(
    tmp_path: Path,
) -> None:
    events = tmp_path / "events.jsonl"
    watchdog = runner._make_windows_child_command_watchdog(events)
    assert watchdog is not None

    for index in range(3):
        _append_observable_command_status(
            events,
            command=f"blocked-command-{index}",
            status="declined",
        )
    assert watchdog() is None
    _append_observable_command_status(
        events, command="allowed-command", status="completed"
    )
    assert watchdog() is None
    for index in range(3, 6):
        _append_observable_command_status(
            events,
            command=f"blocked-command-{index}",
            status="declined",
        )
    assert watchdog() is None


@pytest.mark.skipif(os.name != "nt", reason="Windows command-policy watchdog")
def test_windows_child_watchdog_fails_four_consecutive_policy_denials(
    tmp_path: Path,
) -> None:
    events = tmp_path / "events.jsonl"
    watchdog = runner._make_windows_child_command_watchdog(events)
    assert watchdog is not None

    for index in range(4):
        _append_observable_command_status(
            events,
            command=f"blocked-command-{index}",
            status="declined",
        )
    failure = watchdog()

    assert failure is not None
    assert failure.fatal is True
    assert "4 consecutive commands" in failure.reason


@pytest.mark.skipif(os.name != "nt", reason="Windows command-policy watchdog")
def test_windows_child_watchdog_advances_by_bytes_read_after_stale_stat(
    tmp_path: Path,
) -> None:
    events = tmp_path / "events.jsonl"
    _append_observable_command_status(
        events,
        command="blocked-command-one",
        status="declined",
    )
    stale_size = events.stat().st_size
    _append_observable_command_status(
        events,
        command="blocked-command-two",
        status="declined",
    )
    current_size = events.stat().st_size
    observed_sizes = iter((stale_size, current_size))

    class GrowingEventPath:
        def stat(self) -> SimpleNamespace:
            return SimpleNamespace(st_size=next(observed_sizes))

        def open(self, mode: str):  # noqa: ANN202 - Path-like test double
            return events.open(mode)

    watchdog = runner._make_windows_child_command_watchdog(GrowingEventPath())  # type: ignore[arg-type]
    assert watchdog is not None

    assert watchdog() is None
    # A stale-stat offset would replay the second denial here and incorrectly
    # classify it as the same command being denied twice.
    assert watchdog() is None


def _allow_test_physics_runtime_preflight(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Keep lifecycle tests independent of host solver availability."""

    from content_agent_workflows import physics as physics_workflows
    from usd_core import physics_runtime

