def test_wrapper_expands_structured_material_intent_to_exact_paths(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    source = tmp_path / "asset.usda"
    library = tmp_path / "materials.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    library.write_text("#usda 1.0\n", encoding="utf-8")
    candidates = {
        "candidate_visible_prim_count": 2,
        "candidates": [
            {
                "runtime_path": "/Optimized/A",
                "runtime_paths": ["/Optimized/A"],
                "source_path": "/Asset/A",
                "source_paths": ["/Asset/A"],
            },
            {
                "runtime_path": "/Optimized/B",
                "runtime_paths": ["/Optimized/B"],
                "source_path": "/Asset/B",
                "source_paths": ["/Asset/B"],
            },
        ],
    }
    candidates_path = raw_dir / "visible_candidate_prims.json"
    candidates_path.write_text(json.dumps(candidates), encoding="utf-8")
    intent = {
        "schema_version": "content-agents.material-decision-intent.v1",
        "material_assignments": [
            {
                "material_name": "Paint",
                "candidate_ids": [1, 0],
                "rationale": "Both visible panels share the painted finish.",
            }
        ],
        "reviewed_no_override_candidate_ids": [],
        "decision_notes": "Covered the exact clean-slate universe.",
    }
    child_final = run_dir / "child-final.md"
    child_final.write_text(json.dumps(intent), encoding="utf-8")
    preflight = {
        "visible_candidates_sha256": runner._file_digest(
            candidates_path, within=run_dir
        ),
        "decision_catalog": [{"candidate_id": 0}, {"candidate_id": 1}],
        "decision_palette": [
            {
                "name": "Paint",
                "material_path": "/World/Looks/Paint",
            }
        ],
    }
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=source,
        reference_images=[],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=library,
        output_dir=run_dir,
        optimize=True,
    )

    patch_path = runner._write_material_decision_patch_from_intent(
        config=config,
        run_dir=run_dir,
        preflight_packet=preflight,
        child_final_path=child_final,
    )

    patch = json.loads(patch_path.read_text())
    assert patch["candidate_count"] == 2
    assert patch["material_assignments"] == [
        {
            "material_name": "Paint",
            "material_path": "/World/Looks/Paint",
            "runtime_prim_paths": ["/Optimized/B", "/Optimized/A"],
            "source_prim_paths": ["/Asset/B", "/Asset/A"],
            "prim_paths": ["/Asset/B", "/Asset/A"],
            "rationale": "Both visible panels share the painted finish.",
        }
    ]
    assert json.loads((raw_dir / "material_decision_intent.json").read_text()) == intent

    expected_patch = patch_path.read_bytes()
    candidates["candidates"].reverse()
    candidates_path.write_text(json.dumps(candidates), encoding="utf-8")
    with pytest.raises(UnsafeRunArtifactError, match="preflight digest was pinned"):
        runner._write_material_decision_patch_from_intent(
            config=config,
            run_dir=run_dir,
            preflight_packet=preflight,
            child_final_path=child_final,
        )
    assert patch_path.read_bytes() == expected_patch


