def test_post_tuning_evidence_replaces_canonical_review_and_archives_baseline(
    tmp_path: Path,
) -> None:
    from content_agent_workflows.common import physics_validation_evidence
    from content_agent_workflows.physics import PhysicsBehaviorAssessment

    from content_workflow_cli.tuning_broker import sha256_file

    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    promoted = run_dir / "physics.usdc"
    promoted.write_text("#usda 1.0\n# tuned\n", encoding="utf-8")
    runtime_report = run_dir / "tuning" / "final_visual" / "runtime.json"
    runtime_report.parent.mkdir(parents=True)
    runtime_report.write_text('{"status":"pass"}\n', encoding="utf-8")
    frame = run_dir / "runtime" / "final.png"
    frame.parent.mkdir()
    frame.write_bytes(b"png")
    receipt = raw_dir / "physics_render_frame_receipt_3.json"
    receipt.write_text('{"schema_version":"test"}\n', encoding="utf-8")

    baseline_assessment = run_dir / "physics_behavior_assessment.json"
    baseline_assessment.write_text(
        PhysicsBehaviorAssessment(
            status="pass",
            assessment_notes="pre-tuning baseline only",
        ).model_dump_json(),
        encoding="utf-8",
    )
    baseline_evidence = physics_validation_evidence(
        asset=str(run_dir / "pretune.usdc"),
        target_runtime="ovphysx",
        physics_properties_status="pass",
        runtime_loadability_status="pass",
        no_explosions_status="pass",
    )
    (run_dir / "validation_evidence.json").write_text(
        baseline_evidence.model_dump_json(),
        encoding="utf-8",
    )
    final_runtime_evidence = physics_validation_evidence(
        asset=str(promoted),
        target_runtime="ovphysx",
        physics_properties_status="pass",
        runtime_loadability_status="pass",
        no_explosions_status="pass",
    )
    revalidation_evidence = runtime_report.parent / "validation_evidence.json"
    revalidation_evidence.write_text(
        final_runtime_evidence.model_dump_json(),
        encoding="utf-8",
    )
    assessment_source = raw_dir / "physics_post_tuning_behavior_assessment.json"
    assessment = PhysicsBehaviorAssessment(
        status="pass",
        checked_views=[str(frame)],
        runtime_report=str(runtime_report),
        rendered_frames=[str(frame)],
        assessment_notes="Tuned behavior matches the goal.",
    )
    assessment_source.write_text(assessment.model_dump_json(), encoding="utf-8")
    scenario = run_dir / "tuning" / "final_visual" / "scenario.yaml"
    scenario.write_text("name: freeform\n", encoding="utf-8")
    recording = run_dir / "tuning" / "final_visual" / "recording.usd"
    recording.write_text("#usda 1.0\n", encoding="utf-8")
    selected_replay = {
        "sweep_id": "sweep-001",
        "trial_index": 2,
        "trial_seed": 44,
        "scenario_path": str(scenario),
        "scenario_sha256": sha256_file(scenario),
        "recording_usda": str(recording),
        "report_path": str(runtime_report),
    }

    result = runner._publish_physics_post_tuning_evidence(
        run_dir=run_dir,
        promoted_usd=promoted,
        promoted_usd_sha256=sha256_file(promoted),
        assessment=assessment,
        assessment_source_path=assessment_source,
        revalidation_evidence_path=revalidation_evidence,
        runtime_report_path=runtime_report,
        rendered_frames=[str(frame)],
        render_receipt_path=receipt,
        selected_replay=selected_replay,
    )

    canonical = json.loads(
        (run_dir / "validation_evidence.json").read_text(encoding="utf-8")
    )
    assert canonical["asset"] == str(promoted.resolve())
    assert any(
        check["name"] == "simulation_visual_review" and check["status"] == "pass"
        for check in canonical["checks"]
    )
    assert "baseline" in Path(result["baseline_assessment_path"]).name
    assert "pre-tuning baseline only" in Path(
        result["baseline_assessment_path"]
    ).read_text(encoding="utf-8")
    assert result["assessment_path"] == str(
        run_dir / "physics_behavior_assessment.json"
    )
    assert canonical["metadata"]["tuning_final_visual_review"][
        "accepted_scenario_sha256"
    ] == sha256_file(scenario)


def test_selected_candidate_replay_uses_accepted_scenario_without_reapplying_params(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    import physics_agent.tuning.backend as backend_module
    import physics_agent.tuning.scenario_resolution as resolution_module

    from content_workflow_cli.tuning_broker import sha256_file

    run_dir = tmp_path / "run"
    review_dir = run_dir / "tuning" / "final_visual"
    review_dir.mkdir(parents=True)
    review_usd = review_dir / "promoted_candidate.usd"
    review_usd.write_text("#usda 1.0\n", encoding="utf-8")
    accepted_scenario = review_dir / "accepted_scenario.yaml"
    accepted_scenario.write_text(
        "\n".join(
            [
                "name: freeform",
                "metric: judge_score",
                "target:",
                "  duration_s: 2.0",
                "  initial_velocity: [1.25, 0.0, 0.0]",
                "  observations: [slides and comes to rest]",
                "parameters:",
                "  - name: dynamic_friction",
                "    min: 0.05",
                "    max: 1.0",
                "",
            ]
        ),
        encoding="utf-8",
    )
    sanitized_scenario = review_dir / "accepted_scenario_sanitized.yaml"
    sanitized_scenario.write_bytes(accepted_scenario.read_bytes())
    captured: dict[str, Any] = {}

    class _Backend:
        def warmup(self) -> None:
            captured["warmed"] = True

        def evaluate(self, **kwargs: Any) -> dict[str, Any]:
            captured.update(kwargs)
            trial_dir = review_dir / ".tune_scenes" / "trial_seed_44"
            trial_dir.mkdir(parents=True)
            artifacts = {
                "recording_usd": trial_dir / "recording.usd",
                "scene_usd": trial_dir / "scene.usd",
                "patched_usd": trial_dir / "patched_physics.usd",
            }
            for path in artifacts.values():
                path.write_text("#usda 1.0\n", encoding="utf-8")
            return {
                **{key: str(path) for key, path in artifacts.items()},
                "score": 0.1,
                "objective_value": 0.9,
                "metric": "judge_score",
                "trajectory_summary": {"distance": 1.0},
            }

        def shutdown(self) -> None:
            captured["shutdown"] = True

    monkeypatch.setattr(backend_module, "get_backend", lambda _engine: _Backend())
    monkeypatch.setattr(
        resolution_module,
        "resolve_scenario_bindings",
        lambda scenario, **_kwargs: scenario,
    )
    replay_context = {
        "sweep_id": "sweep-001",
        "trial_index": 2,
        "trial_seed": 44,
        "params": {"dynamic_friction": 0.35},
        "score": 0.1,
        "scenario_path": str(accepted_scenario),
        "scenario_sha256": sha256_file(accepted_scenario),
        "sanitized_scenario_path": str(sanitized_scenario),
        "sanitized_scenario_sha256": sha256_file(sanitized_scenario),
    }

    result = runner._replay_selected_physics_candidate(
        config=_tuning_config(tmp_path, run_dir),
        run_dir=run_dir,
        review_usd=review_usd,
        promoted_usd_sha256=sha256_file(review_usd),
        replay_context=replay_context,
        trace_writer=TraceWriter(run_dir),
    )

    assert captured["params"] == {}
    assert captured["seed"] == 44
    assert captured["physics_usd"] == review_usd
    assert captured["scenario"].target["initial_velocity"] == [1.25, 0.0, 0.0]
    assert captured["shutdown"] is True
    assert result["parameter_overrides_applied_during_replay"] == {}
    assert Path(result["recording_usda"]).is_file()


