def test_stage_promoted_physics_usd_streams_without_buffering(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    from content_workflow_cli.tuning_broker import sha256_file

    run_dir = tmp_path / "run"
    run_dir.mkdir()
    # A valid (inspectable) usda: staging enumerates the dependency closure
    # before copying and fails closed on uninspectable roots.
    promoted = tmp_path / "promoted.usda"
    promoted.write_text("#usda 1.0\n" + "# promoted-physics\n" * 1024, encoding="utf-8")
    expected_sha256 = sha256_file(promoted)
    original_read_bytes = Path.read_bytes

    def reject_promoted_read_bytes(path: Path) -> bytes:
        if path == promoted:
            pytest.fail("final-review staging must stream the promoted USD")
        return original_read_bytes(path)

    monkeypatch.setattr(Path, "read_bytes", reject_promoted_read_bytes)

    staged = runner._stage_promoted_physics_usd_for_final_review(
        run_dir=run_dir,
        promoted_usd=promoted,
        expected_sha256=expected_sha256,
    )

    assert (
        staged
        == (run_dir / "tuning" / "final_visual" / "promoted_candidate.usda").resolve()
    )
    assert sha256_file(staged) == expected_sha256


