def test_tuning_phase_rolls_vomp_publication_back_to_pre_child_baseline(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    from content_agent_workflows.physics import PhysicsVompMassConfig

    import content_workflow_cli.tuning_broker as tuning_broker_module
    from content_workflow_cli.tuning_broker import sha256_file

    run_dir = tmp_path / "run"
    physics_usd = _finalized_usd(run_dir)
    baseline_usd_bytes = physics_usd.read_bytes()
    canonical_result = run_dir / "raw" / "physics_vomp_result.json"
    canonical_result.parent.mkdir(parents=True, exist_ok=True)
    baseline_result_bytes = b'{"baseline":true}\n'
    canonical_result.write_bytes(baseline_result_bytes)
    _write_finalize_record(run_dir, physics_usd)
    for name in (
        "physics_behavior_assessment.json",
        "validation_evidence.json",
        "physics_assignments.json",
    ):
        (run_dir / name).write_text("{}\n", encoding="utf-8")
    baseline = SimpleNamespace(canonical_result_path=canonical_result)

    class _Broker:
        url = "http://127.0.0.1:1"

        def __init__(self, **_kwargs: Any) -> None:
            pass

        def start(self) -> None:
            pass

        def publish_artifacts(self) -> None:
            pass

        def close(self) -> None:
            pass

    def mutate_baseline(**_kwargs: Any) -> int:
        physics_usd.write_bytes(b"child-modified-usd")
        canonical_result.write_bytes(b"child-modified-result")
        return 0

    def fake_conclude(**kwargs: Any) -> dict[str, Any]:
        assert kwargs["vomp_baseline"] is baseline
        assert physics_usd.read_bytes() == b"child-modified-usd"
        assert canonical_result.read_bytes() == b"child-modified-result"
        # Match the real conclusion path: restore the trusted VoMP baseline,
        # then provisionally publish the accepted tuned candidate.
        physics_usd.write_bytes(baseline_usd_bytes)
        canonical_result.write_bytes(baseline_result_bytes)
        physics_usd.write_bytes(b"provisionally-promoted-usd")
        canonical_result.write_bytes(b"provisionally-promoted-result")
        return {
            "status": "accepted",
            "success": True,
            "promoted": True,
            "promoted_usd_path": str(physics_usd),
            "promoted_usd_sha256": sha256_file(physics_usd),
            "tuned_usd_sha256": sha256_file(physics_usd),
            "selected": {"sweep_id": "sweep-001", "trial_index": 0},
            "result_path": str(run_dir / "raw" / "physics_tuning_result.json"),
            "decision_paths": [],
            "vomp_result_path": str(canonical_result),
        }

    monkeypatch.setattr(
        runner,
        "_capture_physics_vomp_tuning_baseline",
        lambda **_kwargs: baseline,
    )
    monkeypatch.setattr(tuning_broker_module, "PhysicsTuningBroker", _Broker)
    monkeypatch.setattr(runner, "_run_child_agent", mutate_baseline)
    monkeypatch.setattr(runner, "_conclude_physics_tuning", fake_conclude)
    monkeypatch.setattr(
        runner,
        "_run_physics_post_tuning_visual_assessment",
        lambda **_kwargs: {
            "status": "unresolved",
            "success": False,
            "error": "Final behavior did not pass.",
        },
    )
    config = replace(
        _tuning_config(tmp_path, run_dir),
        vomp_mass=PhysicsVompMassConfig(runtime_root=tmp_path / "VoMP"),
    )

    returncode = runner._run_physics_agentic_tuning_phase(
        config=config,
        run_dir=run_dir,
        session_id="session-1",
        trace_writer=TraceWriter(run_dir),
        usd_cli_session=object(),  # type: ignore[arg-type]
    )

    assert returncode == 1
    assert physics_usd.read_bytes() == baseline_usd_bytes
    assert canonical_result.read_bytes() == baseline_result_bytes


