def test_physics_publication_state_uses_disk_backed_streaming_snapshots(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    from content_workflow_cli.tuning_broker import sha256_file

    target = tmp_path / "canonical.usdc"
    target.write_bytes(b"original" * 1024)
    original_sha256 = sha256_file(target)
    original_read_bytes = Path.read_bytes

    def reject_target_read_bytes(path: Path) -> bytes:
        if path == target:
            pytest.fail("publication snapshots must not load canonical USDs into RAM")
        return original_read_bytes(path)

    monkeypatch.setattr(Path, "read_bytes", reject_target_read_bytes)
    state = runner._capture_physics_publication_state((target,))
    snapshot_dir = state.snapshot_dir
    try:
        file_state = state.files[0]
        assert file_state.snapshot_path is not None
        assert file_state.snapshot_path.is_file()
        assert file_state.sha256 == original_sha256
        assert not hasattr(file_state, "artifact_bytes")

        target.write_bytes(b"promoted")
        runner._restore_physics_publication_state(state)
        assert sha256_file(target) == original_sha256
    finally:
        runner._cleanup_physics_publication_state(state)
    assert not snapshot_dir.exists()


