def test_tuning_phase_concludes_when_artifact_publish_fails(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    """A child can pre-create a publish destination and force a BrokerError.
    Publishing is evidence, not a promotion gate, so the phase must still write
    the documented honest artifact instead of aborting with a bare trace."""

    import content_workflow_cli.tuning_broker as tuning_broker_module

    run_dir = tmp_path / "run"
    physics_usd = run_dir / "physics.usdc"
    physics_usd.parent.mkdir(parents=True, exist_ok=True)
    physics_usd.write_text("#usda 1.0\n# finalized\n", encoding="utf-8")
    _write_finalize_record(run_dir, physics_usd)

    class _PublishFailingBroker:
        url = "http://127.0.0.1:1"

        def __init__(self, **_kwargs: Any) -> None:
            pass

        def start(self) -> None:
            pass

        def publish_artifacts(self) -> None:
            raise tuning_broker_module.BrokerError(409, "destination already exists")

        def close(self) -> None:
            pass

    monkeypatch.setattr(
        tuning_broker_module, "PhysicsTuningBroker", _PublishFailingBroker
    )
    monkeypatch.setattr(runner, "_run_child_agent", lambda **_kwargs: 0)
    monkeypatch.setattr(
        runner,
        "_conclude_physics_tuning",
        lambda **_kwargs: {"status": "stopped", "success": False, "promoted": False},
    )

    returncode = runner._run_physics_agentic_tuning_phase(
        config=_tuning_config(tmp_path, run_dir),
        run_dir=run_dir,
        session_id="session-1",
        trace_writer=TraceWriter(run_dir),
    )

    summary = json.loads(
        (run_dir / "raw" / "physics_agentic_tuning_result.json").read_text(
            encoding="utf-8"
        )
    )
    assert summary["status"] == "stopped"
    assert "destination already exists" in summary["artifact_publish_error"]
    assert returncode != 0


