class _FakeTuningBroker:
    """Duck-typed broker for _conclude_physics_tuning unit tests."""

    def __init__(
        self,
        *,
        usd_path: Path | None = None,
        verify_ok: bool = True,
        materialize_error: str | None = None,
        ledger_records: dict[str, Any] | None = None,
    ) -> None:
        self.usd_path = usd_path
        self.verify_ok = verify_ok
        self.materialize_error = materialize_error
        self.ledger_records = ledger_records or {}
        self.verified_claims: list[dict[str, Any]] = []

    def ledger(self) -> dict[str, Any]:
        return dict(self.ledger_records)

    def verify_claim(self, claim: dict[str, Any]) -> tuple[bool, str]:
        self.verified_claims.append(dict(claim))
        if self.verify_ok:
            return True, "ok"
        return False, f"sweep_id {claim.get('sweep_id')!r} has no broker record"

    def materialize(self, _sweep_id: str, _trial_index: int) -> dict[str, Any]:
        if self.materialize_error:
            raise RuntimeError(self.materialize_error)
        assert self.usd_path is not None
        from content_workflow_cli.tuning_broker import sha256_file

        return {
            "usd_path": str(self.usd_path),
            "usd_sha256": sha256_file(self.usd_path),
        }


def _finalized_usd(run_dir: Path, *, suffix: str = ".usdc") -> Path:
    """Simulated finalize output; .usdc to match the workflow's default.

    Tests whose flow reaches promotion pass ``suffix=".usda"`` so the
    text-authored double survives the fail-closed dependency-closure
    inspection (text bytes in a .usdc container cannot be inspected)."""

    path = run_dir / f"physics{suffix}"
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("#usda 1.0\n# pretune\n", encoding="utf-8")
    return path


def _tuning_config(
    tmp_path: Path,
    run_dir: Path,
    *,
    output_usd_path: Path | None = None,
) -> PhysicsApplyConfig:
    usd = tmp_path / "asset.usda"
    if not usd.exists():
        usd.write_text("#usda 1.0\n", encoding="utf-8")
    return PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=usd,
        output_dir=run_dir,
        output_usd_path=output_usd_path,
        simulation_engine="fake",
        tune=True,
        behavior_prompt="settle",
    )


def _write_accept_chain(
    run_dir: Path,
    *,
    sweep_id: str = "sweep-001-abcd",
    usd_path: Path,
    result_selected: dict[str, Any] | None = None,
    trailing_stop: bool = False,
) -> tuple[Path, Path]:
    from content_workflow_cli.tuning_broker import sha256_file

    (run_dir / "raw").mkdir(parents=True, exist_ok=True)
    decision_path = run_dir / "raw" / "physics_tuning_decision_1.json"
    selected = {
        "sweep_id": sweep_id,
        "trial_index": 0,
        "usd_path": str(usd_path),
        "usd_sha256": sha256_file(usd_path),
    }
    decision_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.physics-tuning-decision.v1",
                "iteration": 1,
                "decision": "accept",
                "sweep_id": sweep_id,
                "scenario_sha256": "a" * 64,
                "evidence_sha256": "b" * 64,
                "selected": selected,
                "prior_decision_sha256": None,
                "rationale": "accept",
            }
        ),
        encoding="utf-8",
    )
    decision_paths = [decision_path]
    if trailing_stop:
        stop_path = run_dir / "raw" / "physics_tuning_decision_2.json"
        stop_path.write_text(
            json.dumps(
                {
                    "schema_version": "content-agents.physics-tuning-decision.v1",
                    "iteration": 2,
                    "decision": "stop",
                    "prior_decision_sha256": sha256_file(decision_path),
                    "rationale": "changed my mind: behavior goal unreachable",
                }
            ),
            encoding="utf-8",
        )
        decision_paths.append(stop_path)
    result_path = run_dir / "raw" / "physics_tuning_result.json"
    result_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.physics-tuning-result.v1",
                "status": "accepted",
                "selected": result_selected or selected,
                "decision_paths": [str(path) for path in decision_paths],
                "final_decision_sha256": sha256_file(decision_paths[-1]),
                "rationale": "accept",
            }
        ),
        encoding="utf-8",
    )
    return decision_path, result_path


