def test_conclude_physics_tuning_promotes_digest_verified_candidate(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    run_dir = tmp_path / "run"
    # Candidates are materialized in the promotion target's format (the
    # broker's candidate_suffix), so the accepted candidate shares the
    # finalized output's extension (.usda here, so the text double survives
    # the fail-closed dependency-closure inspection).
    tuned = tmp_path / "sweep_work" / "candidates" / "candidate.usda"
    tuned.parent.mkdir(parents=True, exist_ok=True)
    tuned.write_text("#usda 1.0\n# tuned\n", encoding="utf-8")
    _write_accept_chain(run_dir, usd_path=tuned)
    monkeypatch.setattr(
        runner,
        "_revalidate_tuned_physics_usd",
        lambda **_kwargs: {
            "report_path": None,
            "failures": [],
            "warnings": [],
            "error": None,
        },
    )
    payload = runner._conclude_physics_tuning(
        config=_tuning_config(tmp_path, run_dir),
        run_dir=run_dir,
        finalized_physics_usd=_finalized_usd(run_dir, suffix=".usda"),
        broker=_FakeTuningBroker(usd_path=tuned),
        agent_returncode=0,
        trace_writer=TraceWriter(run_dir),
    )
    assert payload["status"] == "accepted"
    assert payload["promoted"] is True
    assert payload["success"] is True
    # Promotion replaces the run's actual finalized output in place — the
    # requested path and format are preserved, byte-identically.
    promoted = run_dir / "physics.usda"
    assert payload["promoted_usd_path"] == str(promoted)
    assert promoted.read_text(encoding="utf-8") == tuned.read_text(encoding="utf-8")
    # The pre-tuning finalized output is preserved under tuning/pretune_*.
    pretune = next((run_dir / "tuning").glob("pretune_*physics.usda"))
    assert "# pretune" in pretune.read_text(encoding="utf-8")


def test_conclude_physics_tuning_keeps_promotion_transaction_live_for_review(
    tmp_path: Path,
    monkeypatch: Any,
) -> None:
    """With a transaction sink (the final-review flow), _conclude returns the
    FINAL promoted-root digest in the payload and leaves the sidecar
    transaction live so a final-review rejection can restore the sidecar."""

    from world_understanding.functions.graphics.so_export import (
        PORTABLE_SIDECAR_MARKER_BYTES,
        PORTABLE_SIDECAR_MARKER_NAME,
    )

    from content_workflow_cli.tuning_broker import sha256_file

    run_dir = tmp_path / "run"
    candidates = tmp_path / "sweep_work" / "candidates"
    candidate_sidecar = candidates / "candidate.usda_assets"
    candidate_sidecar.mkdir(parents=True)
    (candidate_sidecar / "albedo.png").write_bytes(b"fresh-bytes")
    tuned = candidates / "candidate.usda"
    tuned.write_text(
        "#usda 1.0\n"
        'def Material "M" {\n'
        "    asset inputs:file = @./candidate.usda_assets/albedo.png@\n"
        "}\n",
        encoding="utf-8",
    )
    _write_accept_chain(run_dir, usd_path=tuned)
    finalized = _finalized_usd(run_dir, suffix=".usda")
    target_sidecar = run_dir / "physics.usda_assets"
    target_sidecar.mkdir(parents=True)
    (target_sidecar / PORTABLE_SIDECAR_MARKER_NAME).write_bytes(
        PORTABLE_SIDECAR_MARKER_BYTES
    )
    stale = target_sidecar / "albedo.png"
    stale.write_bytes(b"stale-bytes")
    monkeypatch.setattr(
        runner,
        "_revalidate_tuned_physics_usd",
        lambda **_kwargs: {
            "report_path": None,
            "failures": [],
            "warnings": [],
            "error": None,
        },
    )
    transactions: list[Any] = []
    payload = runner._conclude_physics_tuning(
        config=_tuning_config(tmp_path, run_dir),
        run_dir=run_dir,
        finalized_physics_usd=finalized,
        broker=_FakeTuningBroker(usd_path=tuned),
        agent_returncode=0,
        trace_writer=TraceWriter(run_dir),
        promotion_transaction_sink=transactions,
    )
    assert payload["status"] == "accepted"
    assert payload["promoted"] is True
    promoted = Path(str(payload["promoted_usd_path"]))
    # FINAL on-disk digest (post sidecar-reference rewrite), distinct from
    # the selected candidate's materialized digest.
    assert payload["promoted_usd_sha256"] == sha256_file(promoted)
    assert payload["promoted_usd_sha256"] != payload["tuned_usd_sha256"]
    # The transaction is live; publication replaced the stale member.
    assert len(transactions) == 1
    assert stale.read_bytes() == b"fresh-bytes"
    # Simulated final-review rejection restores the sidecar exactly.
    transactions.pop().rollback()
    assert stale.read_bytes() == b"stale-bytes"


