def test_promote_tuned_physics_usd_backs_up_same_named_originals(
    tmp_path: Path,
) -> None:
    """An input and a distinct --output-usd can share a basename; both
    originals must survive under tuning/pretune_*."""

    run_dir = tmp_path / "run"
    finalized = run_dir / "physics.usda"
    finalized.parent.mkdir(parents=True, exist_ok=True)
    finalized.write_text("#usda 1.0\n# finalized\n", encoding="utf-8")
    out_dir = tmp_path / "out"
    out_dir.mkdir(parents=True, exist_ok=True)
    requested = out_dir / "physics.usda"
    requested.write_text("#usda 1.0\n# previous run\n", encoding="utf-8")
    # The candidate lives in a sweep-work candidates directory so the
    # inspected closure resolves outside the (doomed) broker work root.
    tuned = tmp_path / "sweep_work" / "candidates" / "candidate.usda"
    tuned.parent.mkdir(parents=True, exist_ok=True)
    tuned.write_text("#usda 1.0\n# tuned\n", encoding="utf-8")

    from content_workflow_cli.tuning_broker import sha256_file

    config = _tuning_config(tmp_path, run_dir, output_usd_path=requested)

    promotion = runner._promote_tuned_physics_usd(
        config=config,
        run_dir=run_dir,
        finalized_physics_usd=finalized,
        tuned_usd=tuned,
        usd_sha256=sha256_file(tuned),
    )
    promotion.commit()

    assert promotion.target == requested
    assert requested.read_text(encoding="utf-8") == "#usda 1.0\n# tuned\n"
    backups = sorted(
        path.read_text(encoding="utf-8")
        for path in (run_dir / "tuning").glob("pretune_*")
    )
    # Both same-named originals are preserved, not collapsed into one backup.
    assert backups == ["#usda 1.0\n# finalized\n", "#usda 1.0\n# previous run\n"]


@pytest.mark.parametrize(
    "artifact_kind",
    ["validation", "runtime_report", "receipt", "frame", "camera", "render_input"],
)
def test_physics_visual_evidence_attestation_rejects_post_child_mutation(
    tmp_path: Path,
    artifact_kind: str,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    runtime_dir = run_dir / "runtime"
    raw_dir.mkdir(parents=True)
    runtime_dir.mkdir()
    validation_path = run_dir / "validation_evidence.json"
    validation_path.write_text('{"sim_ready_status":"pass"}\n', encoding="utf-8")
    runtime_report_path = runtime_dir / "runtime_validation_report.json"
    runtime_report_path.write_text('{"engine":"fake"}\n', encoding="utf-8")
    frame_path = runtime_dir / "frame_0000.png"
    receipt_path = _write_test_physics_render_receipt(
        run_dir=run_dir,
        runtime_report_path=runtime_report_path,
        frame_path=frame_path,
        iteration=1,
    )
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    targets = {
        "validation": validation_path,
        "runtime_report": runtime_report_path,
        "receipt": receipt_path,
        "frame": frame_path,
        "camera": Path(receipt["frames"][0]["local_camera_path"]),
        "render_input": Path(receipt["render_input_bundle"]["files"][0]["path"]),
    }
    attestation = runner._capture_physics_visual_evidence_attestation(
        run_dir=run_dir,
        validation_path=validation_path,
        runtime_report_path=runtime_report_path,
        rendered_frames=[str(frame_path.resolve())],
        render_receipt_path=receipt_path,
    )

    target = targets[artifact_kind]
    target.write_bytes(target.read_bytes() + b"child mutation")

    with pytest.raises(RuntimeError, match="digest does not match"):
        runner._verify_physics_visual_evidence_attestation(
            run_dir=run_dir,
            attestation=attestation,
        )


