def test_stage_agent_skills_fails_closed_without_trusted_fallback(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    child_skills = run_dir / ".agents" / "skills" / "child-edited"
    child_skills.mkdir(parents=True)
