@pytest.mark.skipif(os.name != "posix", reason="Claude /dev/null sandbox masks")
@pytest.mark.parametrize("identity_field", ["st_rdev", "st_dev", "st_ino"])
def test_reject_unsafe_run_links_rejects_spoofed_claude_sandbox_mask(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    identity_field: str,
) -> None:
    run_dir = tmp_path / "run"
    masked_path = run_dir / ".claude" / "workflows"
    masked_path.parent.mkdir(parents=True)
    masked_path.write_text("placeholder\n", encoding="utf-8")
    dev_null_metadata = Path(os.devnull).lstat()
    spoofed_metadata = SimpleNamespace(
        st_mode=dev_null_metadata.st_mode,
        st_nlink=dev_null_metadata.st_nlink,
        st_rdev=dev_null_metadata.st_rdev,
        st_dev=dev_null_metadata.st_dev,
        st_ino=dev_null_metadata.st_ino,
    )
    if identity_field == "st_rdev":
        spoofed_metadata.st_rdev = os.makedev(
            os.major(dev_null_metadata.st_rdev),
            os.minor(dev_null_metadata.st_rdev) + 1,
        )
    else:
        setattr(
            spoofed_metadata,
            identity_field,
            getattr(spoofed_metadata, identity_field) + 1,
        )
    real_lstat = Path.lstat

    def spoofed_mask_lstat(path: Path) -> os.stat_result:
        if path == masked_path:
            return spoofed_metadata  # type: ignore[return-value]
        return real_lstat(path)

    monkeypatch.setattr(Path, "lstat", spoofed_mask_lstat)

    with pytest.raises(UnsafeRunArtifactError, match="special files are not allowed"):
        runner._reject_unsafe_run_links(run_dir)


