def test_export_validated_usdc_fsyncs_file_and_parent_directory(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    source = run_dir / "physics.usda"
    source.write_text(
        '#usda 1.0\ndef Xform "Physics" {}\n',
        encoding="utf-8",
    )
    destination = tmp_path / "published" / "physics.usdc"
    destination.parent.mkdir()
    observed_modes: list[int] = []
    observed_directories: list[Path] = []
    real_fsync = os.fsync
    real_fsync_directory = runner.fsync_directory

    def observe_fsync(descriptor: int) -> None:
        observed_modes.append(os.fstat(descriptor).st_mode)
        real_fsync(descriptor)

    def observe_fsync_directory(path: Path) -> None:
        observed_directories.append(path)
        real_fsync_directory(path)

    monkeypatch.setattr(runner.os, "fsync", observe_fsync)
    monkeypatch.setattr(runner, "fsync_directory", observe_fsync_directory)

    runner._export_validated_usdc(
        run_dir=run_dir,
        source=source,
        destination=destination,
    )

    assert destination.is_file()
    assert any(stat.S_ISREG(mode) for mode in observed_modes)
    if os.name == "nt":
        assert not any(stat.S_ISDIR(mode) for mode in observed_modes)
        assert observed_directories == [destination.parent]
    else:
        assert any(stat.S_ISDIR(mode) for mode in observed_modes)
        assert observed_directories == []
    assert not list(destination.parent.glob(".*.tmp.usdc"))


def test_reject_unsafe_run_links_tolerates_entry_vanishing_mid_walk(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A listed entry removed before its lstat is skipped, not fatal.

    A concurrent trusted launcher produces exactly this window when its
    atomic write renames a temp file away (for example
    trace/.run_retrospective.json.<digest>.tmp) between the directory
    listing and the per-entry inspection.
    """

    run_dir = tmp_path / "run"
    vanishing = run_dir / "trace" / ".run_retrospective.json.0123abcd.tmp"
    vanishing.parent.mkdir(parents=True)
    vanishing.write_text("{}", encoding="utf-8")
    surviving = run_dir / "trace" / "trace.json"
    surviving.write_text("{}", encoding="utf-8")
    real_lstat = Path.lstat

    def vanishing_lstat(path: Path) -> os.stat_result:
        if path == vanishing:
            vanishing.unlink(missing_ok=True)
            raise FileNotFoundError(errno.ENOENT, "vanished mid-walk", os.fspath(path))
        return real_lstat(path)

    monkeypatch.setattr(Path, "lstat", vanishing_lstat)

    runner._reject_unsafe_run_links(run_dir)


