def test_claude_bridge_defers_child_final_until_structured_output_succeeds(
    tmp_path: Path,
) -> None:
    bridge_uri = Path(runner.__file__).with_name("claude_bridge.mjs").resolve().as_uri()
    child_final = tmp_path / "child-final.json"
    items = tmp_path / "items.json"
    result_path = tmp_path / "result.json"
    request = {
        "run_dir": str(tmp_path),
        "child_final_path": str(child_final),
        "items_path": str(items),
        "result_path": str(result_path),
    }
    script = f"""
        import fs from "node:fs";
        import {{ prepareRunArtifacts, writePreparedRunArtifact }} from {json.dumps(bridge_uri)};
        const request = {json.dumps(request)};
        const artifacts = prepareRunArtifacts(request, false);
        try {{
          writePreparedRunArtifact(artifacts[0], "[]");
          writePreparedRunArtifact(artifacts[1], "{{}}");
          console.log(JSON.stringify({{
            childFinalExists: fs.existsSync(request.child_final_path),
            items: fs.readFileSync(request.items_path, "utf8"),
            result: fs.readFileSync(request.result_path, "utf8"),
          }}));
        }} finally {{
          for (const artifact of artifacts) fs.closeSync(artifact.fd);
        }}
    """

    run = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    assert json.loads(run.stdout) == {
        "childFinalExists": False,
        "items": "[]",
        "result": "{}",
    }


