def test_codex_bridge_ignores_security_critical_config_overrides() -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    script = f"""
        import {{ buildCodexLaunchConfiguration }} from {json.dumps(bridge_uri)};
        const launchConfiguration = buildCodexLaunchConfiguration({{
          codex_config: {{
            approval_policy: "on-request",
            network_access: true,
            permissions: ["danger"],
            env: {{
              TRACEPARENT: "00-evil-evil-01",
              USD_CLI_TEL_FILE: "/tmp/redirected.jsonl",
            }},
            sandbox_mode: "read-only",
            sandbox_permissions: "require_escalated",
            sandbox_workspace_write: {{ network_access: false }},
            "sandbox_workspace_write.writable_roots": ["/tmp/evil"],
            "\\\"sandbox_workspace_write\\\".writable_roots": ["/tmp/evil-quoted"],
            "sandbox_workspace_write.exclude_slash_tmp": false,
            "sandbox_workspace_write.exclude_tmpdir_env_var": false,
            windows: {{ sandbox: "unelevated" }},
            default_permissions: ":danger-full-access",
            model_provider: "proxy",
            model_providers: {{
              proxy: {{
                name: "Proxy",
                base_url: "https://proxy.example/v1",
                wire_api: "responses",
              }},
            }},
          }},
        }});
        console.log(JSON.stringify(launchConfiguration));
    """

    result = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    launch_configuration = json.loads(result.stdout)
    config = launch_configuration["config"]
    assert config["approval_policy"] == "never"
    assert "sandbox_mode" not in config
    assert "sandbox_workspace_write" not in config
    assert config["default_permissions"] == "content-workflow-child"
    assert "permissions" not in config
    assert launch_configuration["launcherConfigOverrides"] == [
        'permissions.content-workflow-child={ extends = ":read-only", '
        'filesystem = { ":workspace_roots" = "write" }, '
        "network = { enabled = true } }"
    ]
    assert "sandbox_workspace_write.writable_roots" not in config
    assert '"sandbox_workspace_write".writable_roots' not in config
    assert "sandbox_workspace_write.exclude_slash_tmp" not in config
    assert "sandbox_workspace_write.exclude_tmpdir_env_var" not in config
    assert "network_access" not in config
    assert "env" not in config
    assert "sandbox_permissions" not in config
    assert "windows" not in config
    assert "cli_auth_credentials_store" not in config
    assert config["features"] == {"plugins": False, "hooks": True}
    policy_hook = config["hooks"]["PreToolUse"][0]["hooks"][0]
    assert policy_hook["type"] == "command"
    assert "--python-policy-hook" in policy_hook["command"]
    assert config["model_provider"] == "proxy"
    assert config["model_providers"]["proxy"]["wire_api"] == "responses"
    assert "Ignoring security-critical Codex config key" in result.stderr


