def test_codex_bridge_writes_narrow_host_executable_prefixes(
    tmp_path: Path,
) -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    script = f"""
        import fs from "node:fs";
        import path from "node:path";
        import {{ prepareCodexLauncher }} from {json.dumps(bridge_uri)};
        const executableName = process.platform === "win32" ? "node" : path.basename(process.execPath);
        const launcher = prepareCodexLauncher(
          process.env,
          process.execPath,
          {json.dumps(str(tmp_path))},
          {{
            host_executables: [{{
              name: executableName,
              paths: [process.execPath],
              allowed_prefixes: [[executableName, "--version"]],
            }}],
          }},
        );
        const rules = fs.readFileSync(
          path.join(launcher.env.CODEX_HOME, "rules", "content-workflow.rules"),
          "utf8",
        );
        launcher.cleanup();
        console.log(JSON.stringify({{ executableName, rules }}));
    """

    completed = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    result = json.loads(completed.stdout)
    name = result["executableName"]
    assert f'host_executable(name="{name}"' in result["rules"]
    assert f'prefix_rule(pattern=["{name}","--version"]' in result["rules"]
    assert f'prefix_rule(pattern=["{name}"]' not in result["rules"]


