def test_codex_unshared_sandbox_reaches_exact_parent_daemon_through_proxy(
    tmp_path: Path,
) -> None:
    """Exercise the real bwrap network namespace used by the Codex SDK child."""

    from usd_cli import daemon as usd_cli_daemon
    from usd_core.config import Config as UsdCliConfig

    package_root = Path(runner.__file__).resolve().parents[1]
    binaries = sorted(
        package_root.glob("node_modules/@openai/codex-linux-*/vendor/*/bin/codex")
    )
    if sys.platform != "linux" or shutil.which("bwrap") is None or not binaries:
        pytest.skip("packaged Codex Linux sandbox is unavailable")
    codex = binaries[0]
    if not os.access(codex, os.X_OK):
        pytest.skip("packaged Codex binary is not executable")

    token = "test-parent-token"
    parent_pid = os.getpid()
    process_start_token = f"test-parent-{parent_pid}"
    instance_id = "test-parent-instance"
    attached_project = tmp_path / "parent-run"
    attached_project.mkdir()
    attached_config = UsdCliConfig(project_dir=attached_project)
    attached_config.state_dir.mkdir(parents=True)
    health_identity = {
        "pid": parent_pid,
        "process_start_token": process_start_token,
        "project_id": usd_cli_daemon._project_id(attached_config),
        "instance_id": instance_id,
        "lifecycle_owner": "external",
    }

    class ParentHealthHandler(BaseHTTPRequestHandler):
        def log_message(self, *_args: object) -> None:
            return None

        def do_GET(self) -> None:  # noqa: N802 - stdlib handler API
            if self.path != "/health" or self.headers.get("x-usd-cli-token") != token:
                self.send_response(401)
                self.end_headers()
                return
            payload = json.dumps(
                {"ok": True, "route": "exact-parent", **health_identity}
            ).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)

        def do_POST(self) -> None:  # noqa: N802 - stdlib handler API
            length = int(self.headers.get("Content-Length", "0"))
            try:
                request = json.loads(self.rfile.read(length))
            except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
                request = None
            if (
                self.path != "/cmd"
                or self.headers.get("x-usd-cli-token") != token
                or not isinstance(request, dict)
                or request.get("command") != "snapshot"
            ):
                self.send_response(401)
                self.end_headers()
                return
            payload = json.dumps(
                {"command": "snapshot", "ok": True, "summary": {}, "issues": []}
            ).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)

    server = ThreadingHTTPServer(("127.0.0.1", 0), ParentHealthHandler)
    server_thread = threading.Thread(target=server.serve_forever, daemon=True)
    server_thread.start()
    port = server.server_address[1]
    attached_config.server_state_path.write_text(
        json.dumps(
            {
                **health_identity,
                "host": "127.0.0.1",
                "port": port,
                "token": token,
            }
        ),
        encoding="utf-8",
    )
    launcher_tmp = tmp_path / ".content-workflow-codex-launcher-test"
    launcher_tmp.mkdir(mode=0o700)
    blocked_tmp = Path("/tmp") / f"content-workflow-blocked-{os.getpid()}"
    assert not blocked_tmp.exists()
    child_script = f"""
import errno
import time
from pathlib import Path
from usd_cli import client
from usd_core.config import Config

private_output = Path({str(launcher_tmp)!r}) / "rigged.usdz"
private_output.write_bytes(b"trusted-launcher-output")
try:
    Path({str(blocked_tmp)!r}).write_bytes(b"must-not-write")
except OSError as error:
    assert error.errno in {{errno.EACCES, errno.EROFS}}, error
else:
    raise AssertionError("general /tmp unexpectedly remained writable")
time.sleep(0.25)
attached_token = client._server_token(
    Config(project_dir=Path.cwd()),
    "http://127.0.0.1:{port}",
)
assert attached_token == {token!r}, attached_token
health = client._fetch_health(
    "http://127.0.0.1:{port}",
    attached_token,
    5.0,
)
assert health == {{
    "ok": True,
    "route": "exact-parent",
    "pid": {parent_pid},
    "process_start_token": {process_start_token!r},
    "project_id": {health_identity["project_id"]!r},
    "instance_id": {instance_id!r},
    "lifecycle_owner": "external",
}}, health
response = client._post(
    "http://127.0.0.1:{port}/cmd",
    attached_token,
    {{"command": "snapshot"}},
    5.0,
)
assert response.ok is True, response
print("parent-proxy-ok")
"""
    environment = dict(os.environ)
    environment.update(
        {
            "CONTENT_WORKFLOW_PARENT_USD_CLI_PROXY_ALLOWED": "1",
            "USD_CLI_ATTACHED_PROJECT_DIR": str(attached_project.resolve()),
        }
    )
    command = [
        str(codex),
        "sandbox",
        "-P",
        "content-workflow-child",
        "-C",
        str(package_root),
        "-c",
        (
            'permissions.content-workflow-child={ extends = ":read-only", '
            f"workspace_roots = {{ {json.dumps(str(launcher_tmp))} = true }}, "
            'filesystem = { ":workspace_roots" = "write" }, '
            "network = "
            '{ enabled = true, domains = { "127.0.0.1" = "allow" } } }'
        ),
        "-c",
        "features.network_proxy=true",
        "-c",
        "network_proxy.enabled=true",
        "-c",
        "network_proxy.enable_socks5=false",
        "-c",
        "network_proxy.enable_socks5_udp=false",
        "-c",
        "network_proxy.allow_upstream_proxy=false",
        "-c",
        "network_proxy.allow_local_binding=false",
        "-c",
        'network_proxy.domains."127.0.0.1"="allow"',
        "--",
        sys.executable,
        "-c",
        child_script,
    ]
    try:
        result = subprocess.run(
            command,
            check=False,
            capture_output=True,
            text=True,
            timeout=30,
            env=environment,
        )
    finally:
        server.shutdown()
        server.server_close()
        server_thread.join(timeout=5)

    if result.returncode != 0 and (
        "sandbox" in result.stderr.lower()
        and any(
            marker in result.stderr.lower()
            for marker in ("operation not permitted", "unavailable", "unsupported")
        )
    ):
        pytest.skip(f"Codex sandbox cannot run on this host: {result.stderr.strip()}")
    assert result.returncode == 0, result.stderr
    assert result.stdout.strip() == "parent-proxy-ok"
    assert (launcher_tmp / "rigged.usdz").read_bytes() == b"trusted-launcher-output"
    assert not blocked_tmp.exists()


