def test_codex_bridge_launcher_ignores_global_config_and_preserves_auth(
    tmp_path: Path,
) -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    user_home = tmp_path / "user-home"
    codex_home = user_home / ".codex"
    plugins_dir = codex_home / "plugins" / "hostile-plugin"
    plugins_dir.mkdir(parents=True)
    (codex_home / "config.toml").write_text(
        'cli_auth_credentials_store = "file"\n'
        'sandbox_mode = "danger-full-access"\n'
        'sandbox_permissions = ["disk-full-read-access"]\n'
        '[mcp_servers.hostile]\ncommand = "/tmp/hostile-mcp"\n',
        encoding="utf-8",
    )
    (codex_home / "auth.json").write_text(
        '{"tokens":{"access_token":"test-only"}}\n',
        encoding="utf-8",
    )
    (codex_home / "cloud-config-bundle-cache.json").write_text(
        '{"policy":"workspace-managed"}\n',
        encoding="utf-8",
    )
    (plugins_dir / "plugin.json").write_text("{}\n", encoding="utf-8")
    invocation_path = tmp_path / "codex-invocation.json"
    remote_staging_root = tmp_path / ".usd-cli-remote-render-staging"
    fake_codex = tmp_path / "fake-codex.mjs"
    fake_codex.write_text(
        f"#!{_node()}\n"
        'import fs from "node:fs";\n'
        'import path from "node:path";\n'
        'import process from "node:process";\n'
        "let input = '';\n"
        'process.stdin.setEncoding("utf8");\n'
        "for await (const chunk of process.stdin) input += chunk;\n"
        "fs.writeFileSync(process.env.CODEX_INVOCATION_PATH, JSON.stringify({\n"
        "  args: process.argv.slice(2),\n"
        "  codexHome: process.env.CODEX_HOME,\n"
        "  input,\n"
        '  initialAuth: fs.readFileSync(path.join(process.env.CODEX_HOME, "auth.json"), "utf8"),\n'
        "  initialCloudConfig: fs.existsSync(\n"
        '    path.join(process.env.CODEX_HOME, "cloud-config-bundle-cache.json"))\n'
        '    ? fs.readFileSync(path.join(process.env.CODEX_HOME, "cloud-config-bundle-cache.json"), "utf8")\n'
        "    : null,\n"
        "}));\n"
        'fs.writeFileSync(path.join(process.env.CODEX_HOME, "auth.json"), '
        '\'{"tokens":{"access_token":"refreshed"}}\\n\');\n',
        encoding="utf-8",
    )
    fake_codex.chmod(0o700)
    script = f"""
        import fs from "node:fs";
        import path from "node:path";
        import {{ spawnSync }} from "node:child_process";
        import {{
          prepareCodexLauncher,
          startThread,
        }} from {json.dumps(bridge_uri)};

        class FakeCodex {{
          constructor(options) {{
            this.options = options;
          }}
          startThread(threadOptions) {{
            return {{ codexOptions: this.options, threadOptions }};
          }}
        }}

        const sourceEnv = {{
          HOME: {json.dumps(str(user_home))},
          CODEX_HOME: {json.dumps(str(codex_home))},
          PATH: "/usr/bin",
          CODEX_API_KEY: "test-api-key",
          CODEX_INVOCATION_PATH: {json.dumps(str(invocation_path))},
          USD_CLI_REMOTE_RENDER_STAGING_ROOT: {json.dumps(str(remote_staging_root))},
        }};
        const request = {{
          repo_root: "/workspace/run",
          model: "gpt-test",
          codex_config: {{ model_provider: "openai" }},
          cli_auth_credentials_store: "file",
        }};
        const launcher = prepareCodexLauncher(
          sourceEnv,
          {json.dumps(str(fake_codex))},
          {json.dumps(str(tmp_path))},
          request,
        );
        const thread = startThread(
          FakeCodex,
          request,
          launcher,
        );
        const launched = spawnSync(
          thread.codexOptions.codexPathOverride,
          [
            "exec",
            "--experimental-json",
            "--config",
            'cli_auth_credentials_store="file"',
          ],
          {{
            cwd: launcher.workingDirectory ?? undefined,
            env: thread.codexOptions.env,
            input: "inspect this workspace",
            encoding: "utf8",
          }},
        );
        const launcherPrefix = launcher.workingDirectory ? ["exec"] : [];
        const rejected = spawnSync(
          thread.codexOptions.codexPathOverride,
          [...launcherPrefix, "login"],
          {{
            cwd: launcher.workingDirectory ?? undefined,
            env: thread.codexOptions.env,
            encoding: "utf8",
          }},
        );
        const launcherPath = launcher.codexPathOverride;
        const launcherDir = launcher.workingDirectory ?? path.dirname(launcherPath);
        const launcherArtifactPath = launcher.workingDirectory
          ? path.join(launcher.workingDirectory, "exec")
          : launcherPath;
        const launcherMode = fs.statSync(launcherArtifactPath).mode & 0o777;
        const launcherDirMode = fs.statSync(launcherDir).mode & 0o777;
        const caCertificateCount = launcher.env.CODEX_CA_CERTIFICATE
          ? (fs.readFileSync(launcher.env.CODEX_CA_CERTIFICATE, "utf8")
              .match(/-----BEGIN CERTIFICATE-----/g) ?? []).length
          : 0;
        const originalRmSync = fs.rmSync;
        let removalAttempts = 0;
        fs.rmSync = (target, options) => {{
          if (String(target) === launcherDir && removalAttempts++ === 0) {{
            throw new Error("simulated cleanup failure");
          }}
          return originalRmSync(target, options);
        }};
        let cleanupError = "";
        try {{
          launcher.cleanup();
        }} catch (error) {{
          cleanupError = error.message;
        }}
        const existsAfterFailedCleanup = fs.existsSync(launcherDir);
        fs.rmSync = originalRmSync;
        launcher.cleanup();
        launcher.cleanup();
        const result = {{
          sourceEnvUnchanged: sourceEnv.TMPDIR === undefined,
          launcherPath,
          launcherArtifactPath,
          windowsLauncher: launcher.workingDirectory !== null,
          launcherMode,
          launcherDirMode,
          caCertificateCount,
          env: thread.codexOptions.env,
          config: thread.codexOptions.config,
          threadOptions: thread.threadOptions,
          launchedStatus: launched.status,
          launchedStderr: launched.stderr,
          rejectedStatus: rejected.status,
          rejectedStderr: rejected.stderr,
          cleanupError,
          existsAfterFailedCleanup,
          removalAttempts,
          existsAfterCleanup: fs.existsSync(launcherDir),
        }};
        console.log(JSON.stringify(result));
    """

    completed = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    result = json.loads(completed.stdout)
    invocation = json.loads(invocation_path.read_text(encoding="utf-8"))
    launcher_root = str(Path(result["launcherArtifactPath"]).parent)
    assert json.loads(invocation.pop("initialAuth")) == {
        "tokens": {"access_token": "test-only"}
    }
    initial_cloud_config = invocation.pop("initialCloudConfig")
    if os.name == "nt":
        assert json.loads(initial_cloud_config) == {"policy": "workspace-managed"}
    else:
        assert initial_cloud_config is None
    expected_args = [
        "exec",
        "--ignore-user-config",
        "--dangerously-bypass-hook-trust",
    ]
    expected_args.extend(
        [
            "--experimental-json",
            "--config",
            'permissions.content-workflow-child={ extends = ":read-only", '
            'filesystem = { ":workspace_roots" = "write" }, '
            "network = { enabled = true }, workspace_roots = { "
            f"{json.dumps(launcher_root)} = true }} }}",
            "--config",
            'cli_auth_credentials_store="file"',
        ]
    )
    assert invocation == {
        "args": expected_args,
        "codexHome": result["env"]["CODEX_HOME"],
        "input": "inspect this workspace",
    }
    assert json.loads((codex_home / "auth.json").read_text(encoding="utf-8")) == {
        "tokens": {"access_token": "test-only"}
    }
    assert (codex_home / "config.toml").exists()
    assert (plugins_dir / "plugin.json").exists()
    assert result["sourceEnvUnchanged"] is True
    if os.name == "nt":
        assert result["windowsLauncher"] is True
        assert Path(result["launcherArtifactPath"]).name == "exec"
        assert result["launcherMode"] & stat.S_IWRITE
        assert result["launcherDirMode"] & stat.S_IWRITE
        assert result["caCertificateCount"] > 0
        assert Path(result["env"]["CODEX_CA_CERTIFICATE"]).parent == Path(
            result["env"]["CODEX_HOME"]
        )
    else:
        assert result["windowsLauncher"] is False
        assert Path(result["launcherPath"]).suffix == ".mjs"
        assert result["launcherMode"] == 0o700
        assert result["launcherDirMode"] == 0o700
        assert result["caCertificateCount"] == 0
    assert Path(result["launcherArtifactPath"]).parent.parent == tmp_path
    assert (
        Path(result["env"]["CODEX_HOME"]).parent
        == Path(result["launcherArtifactPath"]).parent
    )
    assert result["env"]["CODEX_API_KEY"] == "test-api-key"
    assert result["env"]["PATH"] == "/usr/bin"
    assert result["env"]["USD_CLI_REMOTE_RENDER_STAGING_ROOT"] == str(
        remote_staging_root
    )
    assert Path(result["env"]["TMPDIR"]).name == "tmp"
    assert (
        Path(result["env"]["TMPDIR"]).parent == Path(result["env"]["CODEX_HOME"]).parent
    )
    assert not Path(result["env"]["CODEX_HOME"]).is_relative_to(
        Path(result["env"]["TMPDIR"])
    )
    assert result["env"]["TMP"] == result["env"]["TMPDIR"]
    assert result["env"]["TEMP"] == result["env"]["TMPDIR"]
    policy_hooks = result["config"].pop("hooks")
    assert policy_hooks["PreToolUse"][0]["hooks"][0]["type"] == "command"
    assert (
        "--python-policy-hook" in policy_hooks["PreToolUse"][0]["hooks"][0]["command"]
    )
    assert result["config"] == {
        "model_provider": "openai",
        "approval_policy": "never",
        "cli_auth_credentials_store": "file",
        "features": {"plugins": False, "hooks": True},
        "default_permissions": "content-workflow-child",
    }
    assert result["threadOptions"] == {
        "workingDirectory": "/workspace/run",
        "skipGitRepoCheck": True,
        "model": "gpt-test",
    }
    assert result["launchedStatus"] == 0, result["launchedStderr"]
    assert result["rejectedStatus"] == 2
    assert "accepts only exec --experimental-json" in result["rejectedStderr"]
    assert result["cleanupError"] == "simulated cleanup failure"
    assert result["existsAfterFailedCleanup"] is True
    assert result["removalAttempts"] == 1
    assert result["existsAfterCleanup"] is False


def test_codex_bridge_real_sdk_injects_one_valid_permission_profile(
    tmp_path: Path,
) -> None:
    package_root = Path(runner.__file__).resolve().parents[1]
    sdk_package = package_root / "node_modules" / "@openai" / "codex-sdk"
    sdk_entry = sdk_package / "dist" / "index.js"
    if not sdk_entry.is_file():
        pytest.skip("installed @openai/codex-sdk is unavailable")
    sdk_metadata = json.loads(
        (sdk_package / "package.json").read_text(encoding="utf-8")
    )
    assert sdk_metadata["version"] == "0.147.0"

    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    invocation_path = tmp_path / "real-sdk-invocation.json"
    fake_codex = tmp_path / "fake-codex.mjs"
    fake_codex.write_text(
        f"#!{_node()}\n"
        'import fs from "node:fs";\n'
        'import process from "node:process";\n'
        "let input = '';\n"
        'process.stdin.setEncoding("utf8");\n'
        "for await (const chunk of process.stdin) input += chunk;\n"
        "fs.writeFileSync(process.env.CODEX_INVOCATION_PATH, JSON.stringify({\n"
        "  args: process.argv.slice(2),\n"
        "  input,\n"
        "}));\n"
        "console.log(JSON.stringify({type: 'thread.started', thread_id: 'sdk-test'}));\n"
        "console.log(JSON.stringify({type: 'item.completed', item: {\n"
        "  id: 'message-1', type: 'agent_message', text: 'sdk-launch-ok'\n"
        "}}));\n"
        "console.log(JSON.stringify({type: 'turn.completed', usage: {\n"
        "  input_tokens: 0, cached_input_tokens: 0, output_tokens: 0\n"
        "}}));\n",
        encoding="utf-8",
    )
    fake_codex.chmod(0o700)
    run_root = tmp_path / "run"
    run_root.mkdir()
    script = f"""
        import {{ Codex }} from {json.dumps(sdk_entry.resolve().as_uri())};
        import {{
          prepareCodexLauncher,
          startThread,
        }} from {json.dumps(bridge_uri)};

        const request = {{
          repo_root: {json.dumps(str(tmp_path))},
          model: "gpt-test",
          sandbox_writable_roots: [{json.dumps(str(run_root))}],
          child_launch: {{
            network_policy: {{
              mode: "reasoning_transport_only",
              tool_network_access: false,
              allowed_hosts: ["127.0.0.1"],
            }},
          }},
        }};
        const launcher = prepareCodexLauncher(
          {{
            PATH: process.env.PATH,
            CODEX_INVOCATION_PATH: {json.dumps(str(invocation_path))},
          }},
          {json.dumps(str(fake_codex))},
          {json.dumps(str(tmp_path))},
          request,
        );
        const originalWorkingDirectory = process.cwd();
        if (launcher.workingDirectory) process.chdir(launcher.workingDirectory);
        try {{
          const thread = startThread(Codex, request, launcher);
          const result = await thread.run("exercise the real SDK serializer");
          console.log(JSON.stringify({{
            finalResponse: result.finalResponse,
          }}));
        }} finally {{
          try {{
            process.chdir(originalWorkingDirectory);
          }} finally {{
            launcher.cleanup();
          }}
        }}
    """

    completed = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    assert json.loads(completed.stdout)["finalResponse"] == "sdk-launch-ok"
    invocation = json.loads(invocation_path.read_text(encoding="utf-8"))
    config_values = [
        invocation["args"][index + 1]
        for index, argument in enumerate(invocation["args"][:-1])
        if argument == "--config"
    ]
    assert "--sandbox" not in invocation["args"]
    assert "--add-dir" not in invocation["args"]
    assert config_values.count('approval_policy="never"') == 1
    assert config_values.count('windows.sandbox="elevated"') == 0
    permission_values = [
        value
        for value in config_values
        if value.startswith("permissions.content-workflow-child=")
    ]
    assert len(permission_values) == 1
    assert not any(
        value.startswith("permissions.content-workflow-child.")
        for value in config_values
    )
    parsed = tomllib.loads(permission_values[0])
    permission = parsed["permissions"]["content-workflow-child"]
    assert permission["extends"] == ":read-only"
    assert permission["filesystem"] == {":workspace_roots": "write"}
    assert permission["network"] == {
        "enabled": True,
        "domains": {"127.0.0.1": "allow"},
    }
    assert permission["workspace_roots"][str(run_root)] is True
    assert len(permission["workspace_roots"]) == 2
    launcher_roots = set(permission["workspace_roots"]) - {str(run_root)}
    assert len(launcher_roots) == 1
    launcher_root = Path(launcher_roots.pop())
    assert launcher_root.parent == tmp_path
    assert launcher_root.name.startswith(".content-workflow-codex-launcher-")
    assert invocation["input"] == "exercise the real SDK serializer"


def test_codex_bridge_rejects_native_windows_before_provider_execution() -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    script = f"""
        import {{ assertCodexHostSupported }} from {json.dumps(bridge_uri)};
        let windowsError = null;
        try {{
          assertCodexHostSupported("win32");
        }} catch (error) {{
          windowsError = String(error.message);
        }}
        assertCodexHostSupported("linux");
        console.log(JSON.stringify({{windowsError}}));
    """

    completed = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    observed = json.loads(completed.stdout)
    assert "not supported on native Windows" in observed["windowsError"]
    assert "WSL2" in observed["windowsError"]


def test_codex_bridge_resolves_named_provider_api_key() -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    script = f"""
        import {{ buildCodexConfig, startThread }} from {json.dumps(bridge_uri)};

        class FakeCodex {{
          constructor(options) {{
            this.options = options;
          }}
          startThread(threadOptions) {{
            return {{ codexOptions: this.options, threadOptions }};
          }}
        }}

        const request = {{
          repo_root: "/workspace/run",
          model: "openai/openai/gpt-5.6-sol",
          codex_api_key_env: "TEST_PROVIDER_API_KEY",
        }};
        const launcher = {{
          env: {{
            TEST_PROVIDER_API_KEY: "provider-test-secret",
          }},
          codexPathOverride: "/tmp/codex",
          codexConfig: buildCodexConfig(request, "/tmp"),
        }};
        const thread = startThread(
          FakeCodex,
          request,
          launcher,
        );
        console.log(JSON.stringify({{
          apiKey: thread.codexOptions.apiKey,
          envIsPreserved: thread.codexOptions.env === launcher.env,
        }}));
    """

    completed = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    assert json.loads(completed.stdout) == {
        "apiKey": "provider-test-secret",
        "envIsPreserved": True,
    }


@pytest.mark.skipif(
    hasattr(os, "geteuid") and os.geteuid() == 0,
    reason="root bypasses the read-only permission checks under test",
)
def test_codex_bridge_uses_shadow_home_when_original_is_read_only(
    tmp_path: Path,
) -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    codex_home = tmp_path / "read-only-codex-home"
    codex_home.mkdir()
    auth_path = codex_home / "auth.json"
    credentials_path = codex_home / ".credentials.json"
    auth_path.write_text('{"token":"test-auth"}\n', encoding="utf-8")
    credentials_path.write_text('{"token":"test-credentials"}\n', encoding="utf-8")
    auth_path.chmod(0o400)
    credentials_path.chmod(0o400)
    codex_home.chmod(0o500)
    script = f"""
        import fs from "node:fs";
        import path from "node:path";
        import {{ prepareCodexLauncher }} from {json.dumps(bridge_uri)};
        const launcher = prepareCodexLauncher(
          {{ CODEX_HOME: {json.dumps(str(codex_home))}, PATH: "/usr/bin" }},
          process.execPath,
          {json.dumps(str(tmp_path))},
          {{}},
        );
        const shadowHome = launcher.env.CODEX_HOME;
        const result = {{
          shadowed: shadowHome !== {json.dumps(str(codex_home))},
          auth: fs.readFileSync(path.join(shadowHome, "auth.json"), "utf8"),
          credentials: fs.readFileSync(
            path.join(shadowHome, ".credentials.json"), "utf8"
          ),
          authMode: fs.statSync(path.join(shadowHome, "auth.json")).mode & 0o777,
          homeMode: fs.statSync(shadowHome).mode & 0o777,
        }};
        launcher.cleanup();
        console.log(JSON.stringify(result));
    """
    try:
        completed = subprocess.run(
            [_node(), "--input-type=module", "-e", script],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        )
    finally:
        codex_home.chmod(0o700)
        auth_path.chmod(0o600)
        credentials_path.chmod(0o600)

    result = json.loads(completed.stdout)
    assert result.pop("shadowed") is True
    assert json.loads(result.pop("auth")) == {"token": "test-auth"}
    assert json.loads(result.pop("credentials")) == {"token": "test-credentials"}
    if os.name == "nt":
        assert result["authMode"] & stat.S_IWRITE
        assert result["homeMode"] & stat.S_IWRITE
    else:
        assert result == {"authMode": 0o600, "homeMode": 0o700}


@pytest.mark.skipif(
    hasattr(os, "geteuid") and os.geteuid() == 0,
    reason="root bypasses the read-only permission checks under test",
)
def test_codex_launcher_cleanup_covers_environment_setup_failure(
    tmp_path: Path,
) -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    codex_home = tmp_path / "read-only-codex-home"
    codex_home.mkdir()
    credential_target = tmp_path / "credential-target.json"
    credential_target.write_text('{"token":"test"}\n', encoding="utf-8")
    try:
        (codex_home / "auth.json").symlink_to(credential_target)
    except OSError as exc:
        pytest.skip(f"symlink creation is unavailable: {exc}")
    codex_home.chmod(0o500)
    script = f"""
        import fs from "node:fs";
        import {{ prepareCodexLauncher }} from {json.dumps(bridge_uri)};
        let threw = false;
        try {{
          prepareCodexLauncher(
            {{ CODEX_HOME: {json.dumps(str(codex_home))}, PATH: "/usr/bin" }},
            process.execPath,
            {json.dumps(str(tmp_path))},
            {{}},
          );
        }} catch {{
          threw = true;
        }}
        const leftovers = fs.readdirSync({json.dumps(str(tmp_path))})
          .filter((name) => name.startsWith(".content-workflow-codex-launcher-"));
        console.log(JSON.stringify({{ threw, leftovers }}));
    """
    try:
        completed = subprocess.run(
            [_node(), "--input-type=module", "-e", script],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        )
    finally:
        codex_home.chmod(0o700)

    assert json.loads(completed.stdout) == {"threw": True, "leftovers": []}


@pytest.mark.skipif(
    hasattr(os, "geteuid") and os.geteuid() == 0,
    reason="root bypasses the read-only permission checks under test",
)
@pytest.mark.parametrize("server_mode", [False, True])
def test_codex_bridge_cleans_launcher_for_process_lifetime(
    tmp_path: Path,
    server_mode: bool,
) -> None:
    app_dir = tmp_path / "app"
    app_dir.mkdir()
    bridge_path = app_dir / "codex_sdk_bridge.mjs"
    bridge_source = (
        Path(runner.__file__)
        .with_name("codex_sdk_bridge.mjs")
        .read_text(encoding="utf-8")
    )
    # This test exercises launcher lifetime using a fake executable. The native
    # The host-support preflight has separate packaged-CLI tests.
    bridge_path.write_text(
        bridge_source.replace(
            '  if (process.platform !== "win32") return;\n',
            "  return;\n",
            1,
        ),
        encoding="utf-8",
    )
    node_modules = app_dir / "node_modules" / "@openai"
    codex_package = node_modules / "codex"
    codex_package.mkdir(parents=True)
    (codex_package / "package.json").write_text(
        json.dumps(
            {
                "name": "@openai/codex",
                "version": "0.139.0",
                "bin": {"codex": "bin/codex.mjs"},
            }
        ),
        encoding="utf-8",
    )
    fake_executable = codex_package / "bin" / "codex.mjs"
    fake_executable.parent.mkdir()
    fake_executable.write_text(f"#!{_node()}\nprocess.exit(0);\n", encoding="utf-8")
    fake_executable.chmod(0o700)
    if os.name == "nt":
        for package_suffix, target_triple in (
            ("x64", "x86_64-pc-windows-msvc"),
            ("arm64", "aarch64-pc-windows-msvc"),
        ):
            native_package = node_modules / f"codex-win32-{package_suffix}"
            native_package.mkdir()
            (native_package / "package.json").write_text(
                json.dumps(
                    {
                        "name": "@openai/codex",
                        "version": f"0.139.0-win32-{package_suffix}",
                    }
                ),
                encoding="utf-8",
            )
            native_executable = (
                native_package / "vendor" / target_triple / "bin" / "codex.exe"
            )
            native_executable.parent.mkdir(parents=True)
            shutil.copy2(_node(), native_executable)
    sdk_package = node_modules / "codex-sdk"
    sdk_package.mkdir()
    (sdk_package / "package.json").write_text(
        json.dumps(
            {
                "name": "@openai/codex-sdk",
                "version": "0.139.0",
                "type": "module",
                "exports": "./index.mjs",
            }
        ),
        encoding="utf-8",
    )
    (sdk_package / "index.mjs").write_text(
        "export class Codex {\n"
        "  constructor(options) { this.options = options; }\n"
        "  startThread() {\n"
        "    return { run: async () => ({ finalResponse: 'ok', items: [] }) };\n"
        "  }\n"
        "}\n",
        encoding="utf-8",
    )
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    request_path = run_dir / "request.json"
    request_path.write_text(
        json.dumps(
            {
                "repo_root": str(tmp_path),
                "run_dir": str(run_dir),
                "prompt": "test",
                "child_final_path": str(raw_dir / "child-final.md"),
                "items_path": str(raw_dir / "items.json"),
            }
        ),
        encoding="utf-8",
    )
    launcher_tmp = tmp_path / "read-only-launcher-tmp"
    launcher_tmp.mkdir()
    launcher_tmp.chmod(0o500)
    env = {**os.environ, "TMPDIR": str(launcher_tmp)}
    command = [_node(), str(bridge_path)]
    input_text = None
    if server_mode:
        command.extend(["--server", str(request_path)])
        input_text = json.dumps({"type": "shutdown"}) + "\n"
    else:
        command.append(str(request_path))

    try:
        completed = subprocess.run(
            command,
            check=True,
            capture_output=True,
            text=True,
            input=input_text,
            env=env,
            timeout=10,
        )
    finally:
        launcher_tmp.chmod(0o700)

    if server_mode:
        messages = [json.loads(line) for line in completed.stdout.splitlines()]
        assert [message["type"] for message in messages] == ["ready", "shutdown_ack"]
    else:
        assert completed.stdout == "ok\n"
    assert list(launcher_tmp.iterdir()) == []
    assert list(run_dir.rglob(".content-workflow-codex-launcher-*")) == []


@pytest.mark.parametrize(
    "bridge_name",
    ["codex_sdk_bridge.mjs", "claude_bridge.mjs"],
)
def test_sdk_bridge_artifact_write_replaces_symlink_without_following(
    tmp_path: Path,
    bridge_name: str,
) -> None:
    bridge_uri = Path(runner.__file__).with_name(bridge_name).resolve().as_uri()
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    outside = tmp_path / "outside.txt"
    outside.write_text("keep\n", encoding="utf-8")
    output = raw_dir / "result.json"
    output.symlink_to(outside)
    script = f"""
        import {{ writeRunArtifact }} from {json.dumps(bridge_uri)};
        writeRunArtifact(
          {{ run_dir: {json.dumps(str(run_dir))} }},
          {json.dumps(str(output))},
          "safe\\n",
        );
    """

    subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    assert not output.is_symlink()
    assert output.read_text(encoding="utf-8") == "safe\n"
    assert outside.read_text(encoding="utf-8") == "keep\n"


