def test_delegated_vision_receipt_detects_child_tampering(tmp_path: Path) -> None:
    source_usd = tmp_path / "asset.usd"
    source_usd.write_bytes(b"usd")
    image = tmp_path / "render.png"
    image.write_bytes(b"render")
    report = tmp_path / "vision.json"
    evidence = {
        "source_usd": {
            "path": str(source_usd),
            "sha256": runner._file_digest(source_usd),
        },
        "render_metadata_source": None,
        "images": [
            {
                "label": "Final render",
                "path": str(image),
                "sha256": runner._file_digest(image),
                "render_metadata": None,
            }
        ],
    }
    observations = {
        **evidence,
        "evidence_sha256": hashlib.sha256(
            json.dumps(evidence, sort_keys=True, separators=(",", ":")).encode()
        ).hexdigest(),
    }
    report.write_text(json.dumps(observations), encoding="utf-8")
    receipt = runner._delegated_vision_evidence_receipt(
        phase="final-review",
        report_path=report,
        observations=observations,
    )

    runner._verify_delegated_vision_evidence([receipt], current_receipt=receipt)
    report.write_text('{"changed": true}', encoding="utf-8")

    with pytest.raises(UnsafeRunArtifactError, match="report changed"):
        runner._verify_delegated_vision_evidence([receipt])


def test_delegated_vision_verification_binds_every_final_render(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    final_dir = run_dir / "final_renders"
    raw_dir.mkdir(parents=True)
    final_dir.mkdir()
    source_usd = tmp_path / "asset.usd"
    source_usd.write_bytes(b"usd")
    final_paths = []
    for name in (
        "final_oblique.png",
        "final_front_py.png",
        "final_top.png",
        "final_side_px.png",
    ):
        path = final_dir / name
        path.write_bytes(name.encode("utf-8"))
        final_paths.append(path)
    report = raw_dir / "vision_observations_final.json"
    report.write_text("{}", encoding="utf-8")
    render_metadata = raw_dir / "vision_render_metadata_final.json"
    render_metadata.write_text("{}", encoding="utf-8")
    receipt = runner.DelegatedVisionEvidenceReceipt(
        phase="final-review",
        report_path=report,
        report_sha256=runner._file_digest(report),
        evidence_sha256="evidence",
        source_usd_path=source_usd,
        source_usd_sha256=runner._file_digest(source_usd),
        image_artifacts=tuple(
            (path, runner._file_digest(path)) for path in final_paths
        ),
        render_metadata_image_paths=tuple(final_paths),
        render_metadata_path=render_metadata,
        render_metadata_sha256=runner._file_digest(render_metadata),
    )

    verification_path = runner._write_delegated_vision_evidence_verification(
        run_dir=run_dir,
        receipts=[receipt],
    )

    verification = json.loads(verification_path.read_text(encoding="utf-8"))
    assert len(verification["canonical_final_renders"]) == 4
    if os.name == "nt":
        assert verification_path.stat().st_mode & stat.S_IWRITE
    else:
        assert stat.S_IMODE(verification_path.stat().st_mode) == 0o600


