def test_codex_bridge_requires_https_for_a_remote_base_url() -> None:
    """The API key travels to this endpoint on every turn, retries included.

    Over plaintext http it crosses the network in the clear (CWE-319). A local
    proxy stays allowed: it never leaves the host, and demanding a certificate
    for loopback pushes people toward disabling verification instead.
    """

    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    script = f"""
        import {{ buildCodexConfig }} from {json.dumps(bridge_uri)};
        const attempt = (url) => {{
          try {{
            buildCodexConfig({{
              codex_sandbox_mode: "workspace-write",
              codex_base_url: url,
            }});
            return "accepted";
          }} catch (error) {{
            return `rejected: ${{error.message}}`;
          }}
        }};
        console.log(JSON.stringify({{
          remote_http: attempt("http://codex-proxy.example.com/v1"),
          remote_https: attempt("https://codex-proxy.example.com/v1"),
          loopback_http: attempt("http://127.0.0.1:8011/v1"),
          localhost_http: attempt("http://localhost:8011/v1"),
        }}));
    """

    result = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    outcome = json.loads(result.stdout)

    assert outcome["remote_http"].startswith("rejected: "), outcome
    assert "https is required" in outcome["remote_http"]
    assert outcome["remote_https"] == "accepted", outcome
    assert outcome["loopback_http"] == "accepted", outcome
    assert outcome["localhost_http"] == "accepted", outcome


def test_codex_bridge_uses_exact_responses_endpoint_for_thread_config() -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    endpoint = "https://integrate.api.nvidia.com/v1/responses"
    script = f"""
        import {{ buildCodexConfig, startThread }} from {json.dumps(bridge_uri)};

        class FakeCodex {{
          constructor(options) {{ this.options = options; }}
          startThread() {{ return this.options; }}
        }}

        const request = {{
          repo_root: "/workspace/run",
          codex_base_url: "https://integrate.api.nvidia.com/v1",
          codex_responses_url: {json.dumps(endpoint)},
          codex_api_key_env: "NGC_API_KEY",
        }};
        const launcher = {{
          env: {{NGC_API_KEY: "test-only-key"}},
          codexPathOverride: "/tmp/codex",
          codexConfig: buildCodexConfig(request, "/tmp"),
        }};
        console.log(JSON.stringify(startThread(FakeCodex, request, launcher)));
    """

    result = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    options = json.loads(result.stdout)
