def test_codex_bridge_responses_provider_credential_binding_is_fail_closed() -> None:
    bridge_uri = (
        Path(runner.__file__).with_name("codex_sdk_bridge.mjs").resolve().as_uri()
    )
    endpoint = "https://integrate.api.nvidia.com/v1/responses"
    script = f"""
        import {{ buildCodexConfig }} from {json.dumps(bridge_uri)};
        const endpoint = {json.dumps(endpoint)};
        const provider = (request) => {{
          const config = buildCodexConfig(request, "/tmp");
          return config.model_providers[config.model_provider];
        }};
        let invalid;
        try {{
          provider({{
            codex_responses_url: endpoint,
            codex_api_key_env: "NGC-API-KEY",
          }});
          invalid = "accepted";
        }} catch (error) {{
          invalid = String(error.message);
        }}
        console.log(JSON.stringify({{
          fallback: provider({{codex_responses_url: endpoint}}).env_key,
          override: provider({{
            codex_responses_url: endpoint,
            codex_api_key_env: "NGC_API_KEY",
            codex_config: {{
              model_provider: "nvidia",
              model_providers: {{nvidia: {{
                base_url: "https://integrate.api.nvidia.com/v1",
                wire_api: "responses",
                env_key: "PROVIDER_API_KEY",
              }}}},
            }},
          }}).env_key,
          invalid,
        }}));
    """

    result = subprocess.run(
        [_node(), "--input-type=module", "-e", script],
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    observed = json.loads(result.stdout)

    assert observed["fallback"] == "OPENAI_API_KEY"
    assert observed["override"] == "NGC_API_KEY"
    assert "Invalid codex_api_key_env" in observed["invalid"]


