def test_final_render_paths_accept_nested_view_directories(tmp_path: Path) -> None:
    """Children group multi-view output into subdirectories.

    A flat `final_renders/*.png` glob scored such a run as producing zero
    renders, which failed both the render contract and the
    `api_operation_counts` cross-check that compares against this list.
    """

    run_dir = tmp_path / "run"
    top_dir = run_dir / "final_renders" / "top"
    bottom_dir = run_dir / "final_renders" / "bottom"
    top_dir.mkdir(parents=True)
    bottom_dir.mkdir(parents=True)
    (run_dir / "final_renders" / "final_flat.png").write_text("png", encoding="utf-8")
    (top_dir / "quality_az000.png").write_text("png", encoding="utf-8")
    (bottom_dir / "quality_az180.png").write_text("png", encoding="utf-8")
    (top_dir / "segmentation.legend.txt").write_text("legend", encoding="utf-8")

    paths = runner._usd_cli_final_render_paths(run_dir)

    assert [path.name for path in paths] == [
        "quality_az180.png",
        "final_flat.png",
        "quality_az000.png",
    ]


def test_stream_validated_usd_copy_streams_without_buffering(tmp_path: Path) -> None:
    """The audit copy must reproduce the source exactly, at any size.

    The copy used to load the whole stage into memory, which forced a 512 MiB
    ceiling that failed a real 905 MB `output/materialized.usda` -- its binding
    audit reported `verified_target_count: 0` purely because of file size.
    """

    run_dir = tmp_path / "run"
    (run_dir / "output").mkdir(parents=True)
    source = run_dir / "output" / "materialized.usda"
    # Multiple LF-only lines catch Windows CRT text-mode translation. The
    # retained render input must preserve the exact authored USD bytes.
    payload = b'#usda 1.0\ndef Xform "A" {}\ndef Xform "B" {}\n' + b"x" * (
        3 * 1024 * 1024
    )
    source.write_bytes(payload)
    destination = tmp_path / "snapshot.usda"

    artifact = runner._stream_validated_usd_copy(
        run_dir=run_dir,
        source=source,
        destination=destination,
    )

    assert destination.read_bytes() == payload
    assert artifact.size_bytes == len(payload)
    assert not list(tmp_path.glob(".*tmp"))


def test_stream_validated_usd_copy_rejects_symlinked_destination(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    (run_dir / "output").mkdir(parents=True)
    source = run_dir / "output" / "materialized.usda"
    source.write_bytes(b"#usda 1.0\n")
    outside = tmp_path / "outside.usda"
    outside.write_bytes(b"original")
    destination = tmp_path / "published.usda"
    destination.symlink_to(outside)

    with pytest.raises(
        ValueError,
        match="must resolve without traversing symlinks",
    ):
        runner._stream_validated_usd_copy(
            run_dir=run_dir,
            source=source,
            destination=destination,
        )
    assert outside.read_bytes() == b"original"


