def test_child_bridge_python_policy_blocks_before_command_execution(
    tmp_path: Path,
) -> None:
    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    generated = tmp_path / "generated.py"
    generated.write_text("raise SystemExit('must not run')\n", encoding="utf-8")
    payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(tmp_path),
        "tool_name": "Bash",
        "tool_input": {"command": f"python {generated}"},
    }

    completed = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(tmp_path)],
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    decision = json.loads(completed.stdout)
    assert decision["hookSpecificOutput"]["permissionDecision"] == "deny"
    assert (
        "provenance-verified"
        in decision["hookSpecificOutput"]["permissionDecisionReason"]
    )


def test_child_bridge_python_policy_rejects_digest_bound_child_writable_script(
    tmp_path: Path,
) -> None:
    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    staged = tmp_path / "scripts" / "prepare_mesh.py"
    staged.parent.mkdir()
    staged.write_text("print('trusted')\n", encoding="utf-8")
    trusted_digests = {
        str(staged.resolve()): hashlib.sha256(staged.read_bytes()).hexdigest()
    }
    payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(tmp_path),
        "tool_name": "Bash",
        "tool_input": {"command": "python scripts/prepare_mesh.py"},
    }
    command = [
        _node(),
        str(bridge),
        "--python-policy-hook",
        str(tmp_path),
        json.dumps(trusted_digests),
    ]

    denied = subprocess.run(
        command,
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    decision = json.loads(denied.stdout)
    assert decision["hookSpecificOutput"]["permissionDecision"] == "deny"
    assert (
        "provenance-verified"
        in decision["hookSpecificOutput"]["permissionDecisionReason"]
    )


def test_child_bridge_python_policy_verifies_all_staged_imports(
    tmp_path: Path,
) -> None:
    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    child_cwd = tmp_path / "run"
    child_cwd.mkdir()
    scripts = tmp_path / "parent-tools" / "scripts"
    scripts.mkdir(parents=True)
    entry = scripts / "prepare_mesh.py"
    imported = scripts / "mesh_geometry.py"
    entry.write_text("import mesh_geometry\n", encoding="utf-8")
    imported.write_text("VALUE = 'trusted'\n", encoding="utf-8")
    trusted_digests = {
        str(path.resolve()): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in (entry, imported)
    }
    payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(child_cwd),
        "tool_name": "Bash",
        "tool_input": {"command": f"python {entry}"},
    }
    command = [
        _node(),
        str(bridge),
        "--python-policy-hook",
        str(tmp_path),
        json.dumps(trusted_digests),
    ]

    allowed = subprocess.run(
        command,
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(allowed.stdout) == {}

    imported.write_text("VALUE = 'model-authored'\n", encoding="utf-8")
    denied = subprocess.run(
        command,
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    decision = json.loads(denied.stdout)
    assert decision["hookSpecificOutput"]["permissionDecision"] == "deny"
    assert (
        "provenance-verified"
        in (decision["hookSpecificOutput"]["permissionDecisionReason"])
    )

    imported.write_text("VALUE = 'trusted'\n", encoding="utf-8")
    (scripts / "json.py").write_text("VALUE = 'shadow'\n", encoding="utf-8")
    denied = subprocess.run(
        command,
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    decision = json.loads(denied.stdout)
    assert decision["hookSpecificOutput"]["permissionDecision"] == "deny"
    assert (
        "provenance-verified"
        in (decision["hookSpecificOutput"]["permissionDecisionReason"])
    )


