def test_child_python_policy_rejects_an_untrusted_shell_script(
    tmp_path: Path,
) -> None:
    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    generated = tmp_path / "generated.sh"
    generated.write_text("#!/bin/sh\npython -c 'print(1)'\n", encoding="utf-8")
    generated.chmod(0o700)
    command = f"sh {generated}"
    payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(tmp_path),
        "tool_name": "Bash",
        "tool_input": {"command": command},
    }

    completed = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(tmp_path)],
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )

    decision = json.loads(completed.stdout)
    assert decision["hookSpecificOutput"]["permissionDecision"] == "deny"
    assert (
        "provenance-verified"
        in decision["hookSpecificOutput"]["permissionDecisionReason"]
    )
    direct_payload = {
        **payload,
        "tool_input": {"command": str(generated)},
    }
    direct_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(tmp_path)],
        input=json.dumps(direct_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert (
        json.loads(direct_decision.stdout)["hookSpecificOutput"]["permissionDecision"]
        == "deny"
    )

    raw_dir = tmp_path / "raw"
    raw_dir.mkdir()
    (raw_dir / "codex_items.json").write_text(
        json.dumps(
            [
                {
                    "type": "command_execution",
                    "status": "completed",
                    "command": command,
                    "exit_code": 0,
                }
            ]
        ),
        encoding="utf-8",
    )
    assert runner._record_model_authored_python_violation(tmp_path) is True


