def test_child_python_policy_allows_only_unchanged_checked_in_script(
    tmp_path: Path,
) -> None:
    repo = tmp_path / "repo"
    repo.mkdir()
    subprocess.run(["git", "init", "-q"], cwd=repo, check=True)
    subprocess.run(["git", "config", "core.autocrlf", "false"], cwd=repo, check=True)
    subprocess.run(
        ["git", "config", "user.email", "test@example.com"], cwd=repo, check=True
    )
    subprocess.run(["git", "config", "user.name", "Test"], cwd=repo, check=True)
    script = repo / "tools/inspect_asset.py"
    script.parent.mkdir()
    script.write_text("print('trusted')\n", encoding="utf-8")
    shell_script = repo / "tools/inspect_asset.sh"
    shell_script.write_text("jq -e . asset.json\n", encoding="utf-8")
    windows_script = repo / "tools/inspect_asset.cmd"
    windows_script.write_text("@echo off\r\n", encoding="utf-8")
    subprocess.run(["git", "add", "tools"], cwd=repo, check=True)
    subprocess.run(["git", "commit", "-qm", "add trusted tools"], cwd=repo, check=True)

    raw_dir = tmp_path / "run/raw"
    raw_dir.mkdir(parents=True)
    command = f"python {script} --asset asset.usd"
    (raw_dir / "codex_items.json").write_text(
        json.dumps([{"command": command, "exit_code": 0}]), encoding="utf-8"
    )

    assert (
        runner._record_model_authored_python_violation(
            raw_dir.parent,
            trusted_repo_root=repo,
        )
        is False
    )
    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    hook_payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(raw_dir.parent),
        "tool_name": "Bash",
        "tool_input": {"command": command},
    }
    trusted_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(hook_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(trusted_decision.stdout) == {}
    uv_payload = {
        **hook_payload,
        "tool_input": {"command": f"uv run --project {repo} python {script}"},
    }
    trusted_uv_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(uv_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(trusted_uv_decision.stdout) == {}
    trusted_shell_payload = {
        **hook_payload,
        "tool_input": {"command": f"sh {shell_script}"},
    }
    trusted_shell_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(trusted_shell_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(trusted_shell_decision.stdout) == {}
    trusted_windows_payload = {
        **hook_payload,
        "tool_input": {"command": str(windows_script)},
    }
    trusted_windows_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(trusted_windows_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(trusted_windows_decision.stdout) == {}
    (raw_dir / "codex_items.json").write_text(
        json.dumps(
            [
                {
                    "type": "command_execution",
                    "status": "completed",
                    "command": command,
                    "exit_code": 0,
                },
                {
                    "type": "command_execution",
                    "status": "completed",
                    "command": f"sh {shell_script}",
                    "exit_code": 0,
                },
                {
                    "type": "command_execution",
                    "status": "completed",
                    "command": str(windows_script),
                    "exit_code": 0,
                },
            ]
        ),
        encoding="utf-8",
    )
    assert (
        runner._record_model_authored_python_violation(
            raw_dir.parent,
            trusted_repo_root=repo,
        )
        is False
    )

    script.write_text("print('changed')\n", encoding="utf-8")
    assert (
        runner._record_model_authored_python_violation(
            raw_dir.parent,
            trusted_repo_root=repo,
        )
        is True
    )
    changed_decision = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(hook_payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert (
        json.loads(changed_decision.stdout)["hookSpecificOutput"]["permissionDecision"]
        == "deny"
    )


@pytest.mark.skipif(os.name != "nt", reason="Windows CRLF checkout semantics")
def test_child_python_policy_allows_unchanged_crlf_checked_in_script(
    tmp_path: Path,
) -> None:
    repo = tmp_path / "repo"
    repo.mkdir()
    subprocess.run(["git", "init", "-q"], cwd=repo, check=True)
    subprocess.run(["git", "config", "core.autocrlf", "true"], cwd=repo, check=True)
    subprocess.run(
        ["git", "config", "user.email", "test@example.com"], cwd=repo, check=True
    )
    subprocess.run(["git", "config", "user.name", "Test"], cwd=repo, check=True)
    script = repo / "tools" / "inspect_asset.py"
    script.parent.mkdir()
    script.write_bytes(b"print('trusted')\r\n")
    subprocess.run(["git", "add", "tools/inspect_asset.py"], cwd=repo, check=True)
    subprocess.run(
        ["git", "commit", "-qm", "add trusted CRLF tool"], cwd=repo, check=True
    )
    expected = subprocess.run(
        ["git", "rev-parse", "HEAD:tools/inspect_asset.py"],
        cwd=repo,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()
    raw_hash = subprocess.run(
        ["git", "hash-object", "--no-filters", "--", str(script)],
        cwd=repo,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()
    assert raw_hash != expected

    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    command = f'python "{script}"'
    (raw_dir / "codex_items.json").write_text(
        json.dumps([{"command": command, "exit_code": 0}]), encoding="utf-8"
    )
    assert (
        runner._record_model_authored_python_violation(
            run_dir,
            trusted_repo_root=repo,
        )
        is False
    )

    bridge = Path(runner.__file__).with_name("codex_sdk_bridge.mjs")
    payload = {
        "hook_event_name": "PreToolUse",
        "cwd": str(run_dir),
        "tool_name": "Bash",
        "tool_input": {"command": command},
    }
    completed = subprocess.run(
        [_node(), str(bridge), "--python-policy-hook", str(repo)],
        input=json.dumps(payload),
        check=True,
        capture_output=True,
        text=True,
        timeout=10,
    )
    assert json.loads(completed.stdout) == {}


