def test_every_child_scene_watchdog_is_scoped_to_run_directory() -> None:
    source = Path(runner.__file__).read_text(encoding="utf-8")
    tree = ast.parse(source)
    calls = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id in {"_make_scene_watchdog", "_scene_backend_watchdog"}
    ]

    assert len(calls) == 4
    keyword_name = {
        "_make_scene_watchdog": "output_root",
        "_scene_backend_watchdog": "run_dir",
    }
    for call in calls:
        output_root = next(
            (
                keyword.value
                for keyword in call.keywords
                if keyword.arg == keyword_name[call.func.id]
            ),
            None,
        )
        assert isinstance(output_root, ast.Name)
        assert output_root.id in {"run_dir", "output_root"}


