@pytest.mark.skipif(sys.platform != "linux", reason="Linux subreaper regression")
def test_run_subprocess_reaps_adopted_zombies_while_provider_is_alive(
    tmp_path: Path,
) -> None:
    supervisor_pid_path = tmp_path / "supervisor.pid"
    ready_path = tmp_path / "provider.ready"
    target_script = "\n".join(
        [
            "from pathlib import Path",
            "import os, sys, time",
            "for _index in range(32):",
            "    first = os.fork()",
            "    if first == 0:",
            "        second = os.fork()",
            "        if second == 0:",
            "            os._exit(0)",
            "        os._exit(0)",
            "    os.waitpid(first, 0)",
            "Path(sys.argv[1]).write_text(str(os.getppid()), encoding='ascii')",
            "Path(sys.argv[2]).write_text('ready', encoding='ascii')",
            "time.sleep(2)",
        ]
    )
    result: list[int] = []
    failure: list[BaseException] = []

    def invoke() -> None:
        try:
            result.append(
                _run_subprocess_with_timeout(
                    command=[
                        sys.executable,
                        "-c",
                        target_script,
                        str(supervisor_pid_path),
                        str(ready_path),
                    ],
                    cwd=tmp_path,
                    env=os.environ.copy(),
                    timeout_seconds=5,
                    log_stream=StringIO(),
                    timeout_label="live adopted-zombie test",
                    heartbeat_interval_seconds=0,
                    watchdog_interval_seconds=0,
                )
            )
        except BaseException as exc:  # noqa: BLE001 - relay thread failure
            failure.append(exc)

    worker = threading.Thread(target=invoke)
    worker.start()
    deadline = time.monotonic() + 3
    while not ready_path.exists():
        if time.monotonic() >= deadline:
            pytest.fail("provider did not report readiness")
        time.sleep(0.01)

    supervisor_pid = int(supervisor_pid_path.read_text(encoding="ascii"))

    def adopted_zombies() -> list[int]:
        children_path = Path(f"/proc/{supervisor_pid}/task/{supervisor_pid}/children")
        try:
            child_pids = [
                int(value)
                for value in children_path.read_text(encoding="ascii").split()
            ]
        except FileNotFoundError:
            return []
        zombies: list[int] = []
        for child_pid in child_pids:
            try:
                state = (
                    Path(f"/proc/{child_pid}/stat")
                    .read_text(encoding="ascii")
                    .rsplit(")", 1)[1]
                    .split()[0]
                )
            except (FileNotFoundError, ProcessLookupError):
                continue
            if state == "Z":
                zombies.append(child_pid)
        return zombies

    deadline = time.monotonic() + 1
    while adopted_zombies() and time.monotonic() < deadline:
        time.sleep(0.01)
    assert adopted_zombies() == []

    worker.join(timeout=5)
    assert not worker.is_alive()
    assert failure == []
    assert result == [0]


