def test_import_staged_bridge_outputs_redacts_credentials(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    stage_root = tmp_path / "stage"
