    stage = runner._BridgeOutputStage(
        root=stage_root,
        staged_request=stage_root / "request.json",
        staged_child_final=stage_root / "child-final",
        staged_items=stage_root / "items.json",
        staged_result=stage_root / "result.json",
        child_final=run_dir / "child-final.md",
        items=raw_dir / "codex_items.json",
        result=raw_dir / "codex_result.json",
    )
    stage.staged_child_final.write_text(f"token={secret}\n", encoding="utf-8")
