def _write_physics_ovrtx_review_evidence(
    run_dir: Path,
    *,
    iteration: int,
) -> tuple[Path, Path]:
    runtime_dir = run_dir / "runtime"
    raw_dir = run_dir / "raw"
    runtime_dir.mkdir(parents=True, exist_ok=True)
    raw_dir.mkdir(parents=True, exist_ok=True)
    recording_path = runtime_dir / "recording.usda"
    recording_path.write_text("#usda 1.0\n", encoding="utf-8")
    report_path = runtime_dir / "runtime_validation_report.json"
    report_path.write_text(
        json.dumps(
            {
                "engine": "fake",
                "recording_usda": str(recording_path),
            }
        ),
        encoding="utf-8",
    )
    frame_path = runtime_dir / "frame_0000.png"
    Image.new("RGB", (32, 32), "white").save(frame_path)
    (raw_dir / f"physics_render_frames_{iteration}.json").write_text(
        json.dumps(
            {
                "status": "success",
                "renderer": "ovrtx",
                "frame_paths": [str(frame_path)],
            }
        ),
        encoding="utf-8",
    )
    return report_path, frame_path


