def test_step_copy_uses_captured_bytes_after_source_retarget(
    tmp_path: Path, monkeypatch: Any
) -> None:
    run_dir = tmp_path / "run"
    source = run_dir / "raw" / "source.json"
    source.parent.mkdir(parents=True)
    source.write_bytes(b'{"trusted":true}\n')
    external = tmp_path / "external.json"
    external.write_bytes(b'{"secret":"outside"}\n')
    original_read = runner.read_contained_artifact

    def capture_then_retarget(*args: Any, **kwargs: Any) -> Any:
        artifact = original_read(*args, **kwargs)
        source.unlink()
        source.symlink_to(external)
        return artifact

    monkeypatch.setattr(runner, "read_contained_artifact", capture_then_retarget)
    destination = run_dir / "steps" / "step-1" / "source.json"

    assert (
        runner._copy_step_artifact(
            source,
            destination,
            run_dir=run_dir,
        )
        == destination
    )
    assert destination.read_bytes() == b'{"trusted":true}\n'


def test_captured_usd_stage_uses_original_bytes_and_rejects_composition(
    tmp_path: Path, monkeypatch: Any
) -> None:
    from pxr import Usd

    original_path = tmp_path / "original.usda"
    malicious_path = tmp_path / "malicious.usda"
    original_stage = Usd.Stage.CreateNew(str(original_path))
    original_stage.DefinePrim("/Original", "Xform")
    original_stage.GetRootLayer().Save()
    malicious_stage = Usd.Stage.CreateNew(str(malicious_path))
    malicious_stage.DefinePrim("/Malicious", "Xform")
    malicious_stage.GetRootLayer().Save()
    original_read = runner.read_contained_artifact

    def capture_then_retarget(*args: Any, **kwargs: Any) -> Any:
        artifact = original_read(*args, **kwargs)
        original_path.unlink()
        original_path.symlink_to(malicious_path)
        return artifact

    monkeypatch.setattr(runner, "read_contained_artifact", capture_then_retarget)
    captured_stage = runner._open_captured_usd_stage(
        root=tmp_path,
        path=original_path,
    )
    assert captured_stage.GetPrimAtPath("/Original").IsValid()
    assert not captured_stage.GetPrimAtPath("/Malicious").IsValid()

    monkeypatch.setattr(runner, "read_contained_artifact", original_read)
    sublayer_path = tmp_path / "sublayer.usda"
    sublayer = Usd.Stage.CreateNew(str(sublayer_path))
    sublayer.DefinePrim("/FromSublayer", "Xform")
    sublayer.GetRootLayer().Save()
    composed_path = tmp_path / "composed.usda"
    composed = Usd.Stage.CreateNew(str(composed_path))
    composed.GetRootLayer().subLayerPaths.append(sublayer_path.name)
    composed.GetRootLayer().Save()

    with pytest.raises(RuntimeError, match="self-contained flattened stage"):
        runner._open_captured_usd_stage(root=tmp_path, path=composed_path)


