def test_material_step_snapshot_rejects_symlinked_steps_root(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    for name in (
        "assignments.json",
        "api_operation_counts.json",
        "visual_quality_assessment.json",
        "final_summary.md",
    ):
        (run_dir / name).write_text("{}\n", encoding="utf-8")
    external_steps = tmp_path / "external-steps"
