def test_clean_slate_finalizer_preserves_ignored_basis_curve_appearance(
    tmp_path: Path,
) -> None:
    from pxr import Usd, UsdGeom, UsdShade

    inputs = _write_usd_cli_material_inputs(tmp_path)
    (tmp_path / "curve.png").write_bytes(b"curve texture")
    inputs["usd"].write_text(
        """#usda 1.0
(
    defaultPrim = "World"
)
def Xform "World" (
    prepend apiSchemas = ["MaterialBindingAPI"]
)
{
    rel material:binding:physics = </World/Looks/CurvePhysicsMaterial>
    def BasisCurves "Seam" (
        prepend apiSchemas = ["MaterialBindingAPI"]
    )
    {
        point3f[] points = [(0, 0, 0), (1, 1, 0)]
        int[] curveVertexCounts = [2]
        rel material:binding = </World/Looks/CurveMaterial>
        color3f[] primvars:displayColor = [(0.2, 0.3, 0.4)] (
            interpolation = "constant"
        )
        token type = "linear"
        token wrap = "nonperiodic"
    }
    def Scope "Looks"
    {
        def Material "CurveMaterial"
        {
            token outputs:surface.connect = </World/Looks/CurveMaterial/Shader.outputs:surface>
            def Shader "Shader"
            {
                uniform token info:id = "UsdPreviewSurface"
                color3f inputs:diffuseColor = (0.2, 0.3, 0.4)
                asset inputs:file = @curve.png@
                token outputs:surface
            }
        }
        def Material "CurvePhysicsMaterial"
        {
        }
    }
}
""",
        encoding="utf-8",
    )
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    output = run_dir / "output" / "materialized.usda"
    output.parent.mkdir(parents=True)
    (run_dir / "raw").mkdir(exist_ok=True)
    (run_dir / "raw" / "existing.png").write_bytes(b"texture")
    output.write_text(
        """#usda 1.0
(
    defaultPrim = "World"
)
def Xform "World"
{
    def BasisCurves "Seam"
    {
        point3f[] points = [(0, 0, 0), (1, 1, 0)]
        int[] curveVertexCounts = [2]
        token type = "linear"
        token wrap = "nonperiodic"
    }
    def Shader "ExistingShader"
    {
        asset inputs:file = @../raw/existing.png@
    }
}
""",
        encoding="utf-8",
    )

    preservation = runner._restore_ignored_basis_curve_appearance(
        config=config,
        run_dir=run_dir,
    )

    assert preservation["preserved_curve_count"] == 1
    assert preservation["imported_material_count"] == 2
    assert preservation["records"][0]["source_material_paths"]["physics"] == (
        "/World/Looks/CurvePhysicsMaterial"
    )
    stage = Usd.Stage.Open(str(output))
    assert stage is not None
    curve = stage.GetPrimAtPath("/World/Seam")
    material, _relationship = UsdShade.MaterialBindingAPI(curve).ComputeBoundMaterial()
    assert material and material.GetPrim().IsValid()
    surface_shader = material.ComputeSurfaceSource()[0]
    assert surface_shader
    assert surface_shader.GetInput("file").Get().path == "../../curve.png"
    physics_material, _physics_relationship = UsdShade.MaterialBindingAPI(
        curve
    ).ComputeBoundMaterial(materialPurpose="physics")
    assert physics_material and physics_material.GetPrim().IsValid()
    existing_texture = stage.GetAttributeAtPath(
        "/World/ExistingShader.inputs:file"
    ).Get()
    assert existing_texture.path == "../raw/existing.png"
    display_color = UsdGeom.PrimvarsAPI(curve).GetPrimvar("displayColor")
    assert display_color.Get() == [(0.2, 0.3, 0.4)]

    repeated_preservation = runner._restore_ignored_basis_curve_appearance(
        config=config,
        run_dir=run_dir,
    )
    assert repeated_preservation["preserved_curve_count"] == 1

    assert (
        runner._write_reopened_clean_slate_appearance_audit(
            config=config,
            run_dir=run_dir,
            manifest=runner._resolved_material_manifest(config),
            patch={"material_assignments": [], "reviewed_no_override": []},
        )
        == []
    )
    audit = json.loads(
        (run_dir / "raw" / "reopened_appearance_audit.json").read_text(encoding="utf-8")
    )
    assert audit["status"] == "pass"
    assert audit["preserved_basis_curve_count"] == 1


