def test_preserved_basis_curve_material_avoids_unverified_collision(
    tmp_path: Path,
) -> None:
    from pxr import Usd, UsdGeom, UsdShade

    source = tmp_path / "source.usda"
    source_stage = Usd.Stage.CreateNew(str(source))
    UsdShade.Material.Define(source_stage, "/World/Looks/CurveMaterial")
    source_stage.Save()

    output_stage = Usd.Stage.CreateInMemory()
    world = UsdGeom.Xform.Define(output_stage, "/World")
    output_stage.SetDefaultPrim(world.GetPrim())
    suffix = hashlib.sha256(b"/World/Looks/CurveMaterial").hexdigest()[:12]
    container_path = "/World/Looks/__PreservedBasisCurveMaterials"
    UsdGeom.Scope.Define(output_stage, container_path)
    destination_path = container_path + "/CurveMaterial_" + suffix
    UsdShade.Material.Define(output_stage, destination_path)

    preserved = runner._preserved_basis_curve_material(
        stage=output_stage,
        source_usd_path=source,
        source_material_path="/World/Looks/CurveMaterial",
    )

    assert str(preserved.GetPath()) == destination_path + "_1"
    assert output_stage.GetPrimAtPath(destination_path).IsValid()

    container_collision_stage = Usd.Stage.CreateInMemory()
    collision_world = UsdGeom.Xform.Define(container_collision_stage, "/World")
    container_collision_stage.SetDefaultPrim(collision_world.GetPrim())
    UsdGeom.Xform.Define(container_collision_stage, container_path)
    with pytest.raises(RuntimeError, match="container collides with a non-Scope"):
        runner._preserved_basis_curve_material(
            stage=container_collision_stage,
            source_usd_path=source,
            source_material_path="/World/Looks/CurveMaterial",
        )
    assert container_collision_stage.GetPrimAtPath(container_path).IsA(UsdGeom.Xform)


