def test_optimized_restoration_allows_removed_legacy_appearance_and_binds_source(
    tmp_path: Path,
) -> None:
    from pxr import Usd, UsdShade

    source = tmp_path / "source.usda"
    source.write_text(
        """#usda 1.0
def Xform "World"
{
    def Xform "Prototype"
    {
        def Mesh "Body" (
            prepend apiSchemas = ["MaterialBindingAPI"]
        )
        {
            rel material:binding = </World/Looks/Legacy>
        }
    }
    def Xform "Runtime"
    {
        def Mesh "Body" {}
    }
    def Scope "Looks"
    {
        def Material "Legacy"
        {
            def Shader "Shader" {}
        }
    }
}
""",
        encoding="utf-8",
    )
    run_dir = tmp_path / "run"
    output = run_dir / "output/materialized.usda"
    output.parent.mkdir(parents=True)
    output.write_text(
        """#usda 1.0
def Xform "World"
{
    def Xform "Prototype"
    {
        def Mesh "Body" (
            prepend apiSchemas = ["MaterialBindingAPI"]
        )
        {
            rel material:binding = </World/Looks/Obsolete>
        }
    }
    def Xform "Runtime"
    {
        def Mesh "Body" (
            prepend apiSchemas = ["MaterialBindingAPI"]
        )
        {
            rel material:binding = </World/Looks/Paint>
        }
    }
    def Scope "Looks"
    {
        def Material "Obsolete" {}
        def Material "Paint" {}
    }
}
""",
        encoding="utf-8",
    )

    restored = runner._restore_validated_optimized_source_bindings(
        run_dir=run_dir,
        output_usd=output,
        expected_materials={"/World/Prototype/Body": ("Paint", "/World/Looks/Paint")},
        runtime_aliases={"/World/Runtime/Body": "/World/Prototype/Body"},
    )
    ignored = runner._source_appearance_only_prim_paths(source)
    audit = runner._validate_optimized_output_stage(
        run_dir=run_dir,
        source_prim_paths={
            "/World",
            "/World/Prototype",
            "/World/Prototype/Body",
            "/World/Runtime",
            "/World/Runtime/Body",
            "/World/Looks",
            "/World/Looks/Legacy",
            "/World/Looks/Legacy/Shader",
        },
        output_usd=output,
        expected_materials={"/World/Prototype/Body": ("Paint", "/World/Looks/Paint")},
        allowed_missing_source_paths=ignored,
    )

    assert restored == (1, 0)
    restored_stage = Usd.Stage.Open(str(output))
    restored_material = UsdShade.MaterialBindingAPI(
        restored_stage.GetPrimAtPath("/World/Prototype/Body")
    ).ComputeBoundMaterial()[0]
    assert str(restored_material.GetPath()) == "/World/Looks/Paint"
    assert ignored == {
        "/World/Looks",
        "/World/Looks/Legacy",
        "/World/Looks/Legacy/Shader",
    }
    assert audit["verified_bound_target_count"] == 1
    assert audit["allowed_missing_appearance_prim_count"] == 2


