@pytest.mark.parametrize(
    ("child_timeout_seconds", "scene_tool_timeout_seconds", "expected_budget"),
    [
        pytest.param(0.0, 60.0, 900.0, id="disabled-child-timeout"),
        pytest.param(5.0, 60.0, 900.0, id="short-child-timeout"),
        pytest.param(0.0, 1800.0, 1800.0, id="long-service-budget"),
    ],
)
def test_material_usd_cli_readiness_budget_is_independent_of_child_timeout(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    child_timeout_seconds: float,
    scene_tool_timeout_seconds: float,
    expected_budget: float,
) -> None:
    """`--child-timeout 0` disables only the child-turn timeout; the mandatory
    `usd-cli --version` / render-probe readiness keeps its own positive budget
    (the physics preflight pattern)."""

    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    captured_budgets: list[float] = []
    captured_sessions: list[object] = []
    lifecycle: list[str] = []
    daemon_lease = object()
    session = SimpleNamespace(workflow="materials-assign")

    monkeypatch.setattr(
        runner,
        "_start_usd_cli_run_daemon",
        lambda **_kwargs: lifecycle.append("daemon_start") or daemon_lease,
    )
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda **kwargs: (
            lifecycle.append("daemon_stop")
            if kwargs == {"lease": daemon_lease}
            else pytest.fail("material cleanup did not use the captured daemon lease")
        ),
    )
    monkeypatch.setattr(
        runner,
        "_attach_workflow_usd_cli_session",
        lambda **_kwargs: session,
    )

    def capture_readiness(_repo_root: Path, **kwargs: Any) -> None:
        assert lifecycle == ["daemon_start"]
        lifecycle.append("readiness")
        captured_budgets.append(kwargs["timeout_seconds"])
        captured_sessions.append(kwargs["session"])
        raise RuntimeError("stop after capturing the readiness budget")

    monkeypatch.setattr(runner, "_coverage_gap_issues", lambda _coverage: [])
    monkeypatch.setattr(runner, "ensure_usd_cli_ovrtx_ready", capture_readiness)
    monkeypatch.setattr(
        runner,
        "_run_child_agent",
        lambda **_kwargs: pytest.fail("child must not launch"),
    )

    result = runner.run_material_assignment(
        _usd_cli_material_assign_config(
            tmp_path,
            inputs,
            child_timeout_seconds=child_timeout_seconds,
            scene_tool_timeout_seconds=scene_tool_timeout_seconds,
        )
    )

    assert result.returncode == 2
    # Readiness remains launcher-owned and independent of the child turn's timeout.
    assert captured_budgets == [expected_budget]
    assert all(budget > 0 for budget in captured_budgets)
    assert captured_sessions[0].workflow == "materials-assign"
    assert lifecycle == ["daemon_start", "readiness", "daemon_stop"]


