def test_external_usd_cli_start_retains_anchor_until_strict_cleanup(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    request: pytest.FixtureRequest,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    target = tmp_path / "usd-cli"
    target.write_text("#!/bin/sh\n", encoding="utf-8")
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=target,
    )
    real_close_anchor = runner._close_usd_cli_run_state_anchor
    anchor = runner._prepare_usd_cli_run_state(
        run_dir,
        external_lifecycle=True,
    )
    request.addfinalizer(lambda: real_close_anchor(anchor))
    lease = runner.UsdCliDaemonLease(
        target_path=target,
        identity=_fake_usd_cli_daemon_identity(),
        server_state_bytes=_fake_external_usd_cli_server_state(),
        daemon_ledger_bytes=b"123:t1\n",
    )
    calls: dict[str, object] = {}
    monkeypatch.setattr(
        runner,
        "_prepare_usd_cli_run_state",
        lambda *_args, **_kwargs: anchor,
    )

    def start_from_anchor(**kwargs: object) -> runner.UsdCliDaemonLease:
        calls.update(kwargs)
        return lease

    monkeypatch.setattr(
        runner,
        "_start_usd_cli_run_daemon_from_anchor",
        start_from_anchor,
    )
    monkeypatch.setattr(
        runner,
        "_close_usd_cli_run_state_anchor",
        lambda _anchor: pytest.fail("external lease anchor closed before teardown"),
    )

    observed = runner._start_usd_cli_run_daemon(
        route=route,
        run_dir=run_dir,
        external_lifecycle=True,
    )

    assert observed.run_dir == run_dir
    assert observed.state_anchor is anchor
    assert calls["defer_child_config"] is True

    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_strict",
        lambda **kwargs: calls.update(strict_cleanup=kwargs["lease"]),
    )
    runner._stop_usd_cli_run_daemon_best_effort(lease=observed)
    assert calls["strict_cleanup"] is observed


def _allow_fake_usd_cli_telemetry_route(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Let route-mechanics tests use fixture executables after ownership checks."""

    def fake_package_route(_repo_root: Path) -> usd_cli_common.UsdCliPackageRoute:
        wrapper = shutil.which("usd-cli-tel", path=os.environ.get("PATH", ""))
        target = shutil.which("usd-cli", path=os.environ.get("PATH", ""))
        if wrapper is None or target is None:
            raise RuntimeError("fixture package route is unavailable")
        return usd_cli_common.UsdCliPackageRoute(
            wrapper=Path(wrapper).absolute(),
            target=Path(target).absolute(),
            source_root=(Path("/test") / usd_cli_common.USD_CLI_SOURCE_PATH / "src"),
            source_revision="a" * 40,
        )

    monkeypatch.setattr(
        runner,
        "resolve_package_owned_usd_cli_route",
        fake_package_route,
    )

    def fake_start_usd_cli_run_daemon(**kwargs: object) -> runner.UsdCliDaemonLease:
        run_dir = Path(str(kwargs["run_dir"]))
        state_dir = run_dir / ".usd-cli"
        state_dir.mkdir(parents=True, exist_ok=True)
        server_state = _fake_external_usd_cli_server_state()
        (state_dir / "server.json").write_bytes(server_state)
        return runner.UsdCliDaemonLease(
            target_path=Path("/test/usd-cli"),
            identity=_fake_usd_cli_daemon_identity(),
            server_state_bytes=server_state,
            daemon_ledger_bytes=b"123:t1\n",
            run_dir=run_dir,
        )

    monkeypatch.setattr(
        runner,
        "_start_usd_cli_run_daemon",
        fake_start_usd_cli_run_daemon,
    )
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(runner, "_activate_usd_cli_child_config", lambda _lease: None)


