def _write_staged_physics_packet(
    physics_packet_writer: Any,
    *,
    run_dir: Path,
    source_usd: Path,
) -> dict[str, Any]:
    """Write a physics fixture packet with its confined usd-cli source."""

    packet = physics_packet_writer(run_dir, source_usd)
    staged = runner._stage_usd_cli_input_tree(
        label="source",
        source_usd_path=source_usd,
        run_dir=run_dir,
    )
    packet["staged_source"] = {"staged_usd_path": str(staged.staged_usd_path)}
    return packet


def _stage_material_vqa_policy_inputs(tmp_path: Path, run_dir: Path) -> None:
    """Provide the confined source/library pair required by direct VQA tests."""

    source = tmp_path / "asset.usd"
    materials = tmp_path / "materials.usd"
    reference = tmp_path / "reference.png"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    materials.write_text("#usda 1.0\n", encoding="utf-8")
    Image.new("RGB", (1, 1), color="white").save(reference)
    run_dir.mkdir(parents=True, exist_ok=True)
    runner._stage_usd_cli_input_tree(
        label="source",
        source_usd_path=source,
        run_dir=run_dir,
    )
    runner._stage_usd_cli_input_tree(
        label="material_library",
        source_usd_path=materials,
        run_dir=run_dir,
    )


def test_child_telemetry_route_accepts_installed_in_tree_package(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    tool_bin = tmp_path / "package-bin"
    source_root = tmp_path / "repo" / "usd-cli" / "src"
    tool_bin.mkdir()
    source_root.mkdir(parents=True)
    executable_suffix = ".exe" if os.name == "nt" else ""
    wrapper = tool_bin / f"usd-cli-tel{executable_suffix}"
    target = tool_bin / f"usd-cli{executable_suffix}"
    if os.name == "nt":
        node_executable = shutil.which("node")
        if node_executable is None:
            pytest.skip("Node.js is required for a native Windows probe fixture")
        shutil.copy2(node_executable, wrapper)
        shutil.copy2(node_executable, target)
    else:
        wrapper.write_text(
            '#!/bin/sh\nexec "$USD_CLI_TEL_TARGET" "$@"\n',
            encoding="utf-8",
        )
        target.write_text(
            "#!/bin/sh\nprintf 'usd-cli test\\n'\n",
            encoding="utf-8",
        )
        wrapper.chmod(wrapper.stat().st_mode | stat.S_IXUSR)
        target.chmod(target.stat().st_mode | stat.S_IXUSR)
    monkeypatch.setenv("PATH", os.defpath)
    monkeypatch.setattr(
        runner,
        "resolve_package_owned_usd_cli_route",
        lambda _repo_root: usd_cli_common.UsdCliPackageRoute(
            wrapper=wrapper.resolve(),
            target=target.resolve(),
            source_root=source_root.resolve(),
            source_revision="c" * 40,
        ),
    )

    route = runner._prepare_usd_cli_telemetry_route(
        tmp_path,
        repo_root=tmp_path / "repo",
    )

    assert route.status == "active"
    assert route.wrapper_path == wrapper
    assert route.target_path == target


def test_workflow_telemetry_route_reuses_validation_within_one_run(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    run_dir = tmp_path / "run"
    package_bin = tmp_path / "package-bin"
    source_root = tmp_path / "usd-cli" / "src"
    package_bin.mkdir()
    source_root.mkdir(parents=True, exist_ok=True)
    wrapper = package_bin / "usd-cli-tel"
    target = package_bin / "usd-cli"
    wrapper.write_text('#!/bin/sh\nexec "$USD_CLI_TEL_TARGET" "$@"\n', encoding="utf-8")
    target.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
    wrapper.chmod(wrapper.stat().st_mode | stat.S_IXUSR)
    target.chmod(target.stat().st_mode | stat.S_IXUSR)
    resolutions = 0

    def package_route(_repo_root: Path) -> usd_cli_common.UsdCliPackageRoute:
        nonlocal resolutions
        resolutions += 1
        return usd_cli_common.UsdCliPackageRoute(
            wrapper=wrapper,
            target=target,
            source_root=source_root,
            source_revision="a" * 40,
        )

    monkeypatch.setattr(runner, "resolve_package_owned_usd_cli_route", package_route)
