    config = _usd_cli_material_assign_config(tmp_path, inputs)

    first = runner._workflow_usd_cli_telemetry_route(config, run_dir)
    second = runner._workflow_usd_cli_telemetry_route(config, run_dir)

    assert first is second
    assert first.active is True
