def test_workflow_telemetry_route_cache_rejects_ignored_import_artifact(
    tmp_path: Path,
) -> None:
    repo_root = tmp_path / "repo"
    source_root = repo_root / usd_cli_common.USD_CLI_SOURCE_PATH / "src"
    package_bin = tmp_path / "package-bin"
    repo_root.mkdir()
    for relative in usd_cli_common.USD_CLI_REQUIRED_SOURCE:
        source = repo_root / relative
        source.parent.mkdir(parents=True, exist_ok=True)
        source.write_text(f"{relative.as_posix()}\n", encoding="utf-8")
    (repo_root / ".gitignore").write_text("*.so\n", encoding="utf-8")
    package_bin.mkdir()
    wrapper = package_bin / "usd-cli-tel"
    target = package_bin / "usd-cli"
    wrapper.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
    target.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
    wrapper.chmod(wrapper.stat().st_mode | stat.S_IXUSR)
    target.chmod(target.stat().st_mode | stat.S_IXUSR)
    subprocess.run(["git", "init", "-q"], cwd=repo_root, check=True)
    subprocess.run(["git", "add", "."], cwd=repo_root, check=True)
    subprocess.run(
        [
            "git",
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.com",
            "commit",
            "-qm",
            "fixture",
        ],
        cwd=repo_root,
        check=True,
    )
    source_revision = usd_cli_common.usd_cli_source_revision(repo_root)
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=wrapper,
        target_path=target,
        source_root=source_root,
        source_revision=source_revision,
    )
    cache = runner._UsdCliTelemetryRouteCache(
        run_dir=tmp_path / "run",
        repo_root=repo_root,
        route=route,
        wrapper_identity=runner._usd_cli_executable_identity(wrapper),
        target_identity=runner._usd_cli_executable_identity(target),
    )

    assert runner._usd_cli_route_cache_is_current(cache) is True

    ignored_native_module = source_root / "usd_cli" / "main.so"
    ignored_native_module.write_bytes(b"unrecorded native module")
    assert (
        subprocess.run(
            ["git", "status", "--porcelain", "--untracked-files=all"],
            cwd=repo_root,
            check=True,
            capture_output=True,
            text=True,
        ).stdout
        == ""
    )

    assert runner._usd_cli_route_cache_is_current(cache) is False


def test_child_dispatch_marks_live_view_lifecycle(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv(runner.LIVE_VIEWER_PROGRESS_ENV, "1")
    # Register restoration before exercising code that mutates os.environ
    # directly, while preserving the absent-key precondition under test.
    monkeypatch.setenv(runner.LIVE_VIEWER_CHILD_LAUNCHED_ENV, "0")
