def test_child_telemetry_route_rejects_foreign_shadow_without_executing_it(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    foreign_bin = tmp_path / "foreign-bin"
    package_bin = tmp_path / "package-bin"
    foreign_bin.mkdir()
    package_bin.mkdir()
    execution_marker = tmp_path / "foreign-executed"
    for name in ("usd-cli", "usd-cli-tel"):
        executable = foreign_bin / name
        executable.write_text(
            f"#!/bin/sh\ntouch {execution_marker!s}\nexit 0\n",
            encoding="utf-8",
        )
        executable.chmod(executable.stat().st_mode | stat.S_IXUSR)
    wrapper = package_bin / "usd-cli-tel"
    target = package_bin / "usd-cli"
    wrapper.write_text('#!/bin/sh\nexec "$USD_CLI_TEL_TARGET" "$@"\n', encoding="utf-8")
    target.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
    wrapper.chmod(wrapper.stat().st_mode | stat.S_IXUSR)
    target.chmod(target.stat().st_mode | stat.S_IXUSR)
    monkeypatch.setenv("PATH", str(foreign_bin))
    monkeypatch.setattr(
        runner,
        "resolve_package_owned_usd_cli_route",
        lambda _repo_root: usd_cli_common.UsdCliPackageRoute(
            wrapper=wrapper,
            target=target,
            source_root=tmp_path / "repo" / "usd-cli" / "src",
            source_revision="d" * 40,
        ),
    )
    if os.name == "nt":
        monkeypatch.setattr(
            runner,
            "_probe_usd_cli_telemetry_wrapper",
            lambda *_args: None,
        )

    route = runner._prepare_usd_cli_telemetry_route(
        tmp_path,
        repo_root=Path(__file__).resolve().parents[4],
    )

    assert route.status == "active"
    assert route.wrapper_path == wrapper
    assert route.target_path == target
    assert not execution_marker.exists()


