def test_prepare_usd_cli_run_state_refuses_live_stale_state(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    state_dir = run_dir / ".usd-cli"
