def test_bind_parent_capability_preserves_verified_server_route(
    tmp_path: Path,
) -> None:
    config = runner.MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "source.usda",
        reference_images=[],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usda",
    )
    capability = SimpleNamespace(
        identity_path=tmp_path / "identity.json",
        identity_sha256="a" * 64,
        server_url="http://127.0.0.1:43210",
    )

    bound = runner.bind_parent_usd_cli_capability(config, capability)

    assert bound is not config
    assert bound.parent_usd_cli_session_identity == capability.identity_path
    assert bound.parent_usd_cli_session_identity_sha256 == capability.identity_sha256
    assert bound.usd_cli_server_url == capability.server_url
    # The server route must be part of the config contract.  A dynamically
    # attached attribute is silently omitted by dataclasses.asdict(), which can
    # make a standalone child lose the parent GPU daemon when a launcher saves
    # or rebuilds its config.
    assert asdict(bound)["usd_cli_server_url"] == capability.server_url


