def test_parent_capability_opens_initial_scene_read_only(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    initial_scene = tmp_path / "source.usda"
    initial_scene.write_text("#usda 1.0\n", encoding="utf-8")
    opened: list[tuple[Path, bool]] = []
    daemon_calls: list[dict[str, object]] = []
    session = SimpleNamespace(
        session_id="workflow-test",
        open=lambda path, *, read_only=False: opened.append((path, read_only)),
    )

    def start_daemon(**kwargs: object) -> object:
        daemon_calls.append(kwargs)
        return object()

    stubs = {
        "_validate_parent_managed_child_confinement": lambda *_args, **_kwargs: None,
        "_workflow_usd_cli_telemetry_route": lambda *_args, **_kwargs: SimpleNamespace(
            active=True, target_path=tmp_path / "usd-cli"
        ),
        "_start_usd_cli_run_daemon": start_daemon,
        "_attach_workflow_usd_cli_session": lambda **_kwargs: session,
        "ensure_usd_cli_ovrtx_ready": lambda *_args, **_kwargs: object(),
        "_activate_usd_cli_child_config": lambda _lease: None,
        "_write_shared_parent_usd_cli_session_identity": lambda **_kwargs: (
            tmp_path / "identity.json",
            "a" * 64,
            "http://127.0.0.1:1",
        ),
    }
    for name, stub in stubs.items():
        monkeypatch.setattr(runner, name, stub)

    pinned_render = {"backends": [{"url": "https://selected.example.test"}]}
    pinned_api_keys = {"https://selected.example.test": "parent-secret"}
    capability = runner.start_parent_usd_cli_capability(
        config=SimpleNamespace(repo_root=tmp_path, child_timeout_seconds=30.0),
        run_dir=run_dir,
        workflow="test-workflow",
        input_roots=(initial_scene,),
        initial_scene=initial_scene,
        pinned_render_config=pinned_render,
        pinned_render_backend_api_keys=pinned_api_keys,
    )

    assert capability.session is session
    assert opened == [(initial_scene, True)]
    assert daemon_calls[0]["pinned_render_config"] == pinned_render
    assert daemon_calls[0]["pinned_render_backend_api_keys"] == pinned_api_keys


