def test_attached_parent_session_rejects_launcher_drift_for_command_and_teardown(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from content_agent_workflows.common import usd_cli_session

    repo_root = tmp_path / "repo"
    repo_root.mkdir()
    wrapper = repo_root / "usd-cli-tel"
    target = repo_root / "usd-cli"
    for executable in (wrapper, target):
        executable.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
        executable.chmod(0o700)
    route = usd_cli_common.UsdCliPackageRoute(
        wrapper=wrapper,
        target=target,
        source_root=repo_root,
        source_revision="a" * 40,
    )
    monkeypatch.setattr(
        usd_cli_session,
        "resolve_package_owned_usd_cli_route",
        lambda _repo_root: route,
    )
    run_dir = tmp_path / "run"
    run_dir.mkdir(mode=0o700)
    run_dir.chmod(0o700)
    checkpoint = run_dir / "raw" / "usd_cli_command_receipts.checkpoint.json"
    checkpoint.parent.mkdir(mode=0o700)
    checkpoint.parent.chmod(0o700)
    checkpoint.write_bytes(b"sealed receipt checkpoint")
    state_path = run_dir / ".usd-cli" / "server.json"
    state_path.parent.mkdir()
    state_path.write_text(
        json.dumps(
            {
                "host": "127.0.0.1",
                "port": 43210,
                "token": "exact-parent-token",
            }
        ),
        encoding="utf-8",
    )
    session = runner._attach_workflow_usd_cli_session(
        repo_root=repo_root,
        run_dir=run_dir,
        workflow="asset.run",
    )
    assert session._package_route_pin is not None
    assert session._package_route_pin.route == route

    original_uid = wrapper.stat().st_uid
    replacement = repo_root / "replacement-usd-cli-tel"
    replacement.write_text("#!/bin/sh\nexit 99\n", encoding="utf-8")
    replacement.chmod(0o700)
    os.replace(replacement, wrapper)
    assert wrapper.stat().st_uid == original_uid
    monkeypatch.setattr(
        usd_cli_session,
        "controlled_usd_cli_telemetry_env",
        lambda **_kwargs: {},
    )
    monkeypatch.setattr(
        usd_cli_session,
        "run_bounded_usd_cli_subprocess",
        lambda *_args, **_kwargs: pytest.fail("replaced parent launcher executed"),
    )

    with pytest.raises(RuntimeError, match="implementation identity changed"):
        session.run_json(["info"])
    with pytest.raises(RuntimeError, match="implementation identity changed"):
        session.close()


