def test_usd_cli_daemon_log_tail_is_bounded_and_marks_truncation(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    anchor = runner._prepare_usd_cli_run_state(run_dir)
    try:
        daemon_log = run_dir / ".usd-cli" / "daemon.log"
        daemon_log.write_bytes(b"prefix-should-be-dropped\n" + b"z" * 4096)

        observed = runner._read_usd_cli_daemon_log_tail(anchor, max_bytes=1024)

        assert len(observed) < 1024
        assert observed.startswith(b"[usd-cli daemon log truncated;")
        assert observed.endswith(b"bytes]\n")
        assert b"prefix-should-be-dropped" not in observed
        assert b"z" not in observed
    finally:
        runner._close_usd_cli_run_state_anchor(anchor)


