@pytest.mark.parametrize(
    "start_name",
    ["_start_usd_cli_run_daemon", "_start_usd_cli_run_daemon_strict"],
)
def test_usd_cli_daemon_rejects_route_drift_before_state_mutation(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    start_name: str,
) -> None:
    repo_root = tmp_path / "repo"
    source_root = repo_root / usd_cli_common.USD_CLI_SOURCE_PATH / "src"
    source_root.mkdir(parents=True)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    wrapper = tmp_path / "usd-cli-tel"
    target = tmp_path / "usd-cli"
    replacement_target = tmp_path / "usd-cli-replacement"
    for executable in (wrapper, target, replacement_target):
        executable.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
        executable.chmod(0o755)
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=wrapper,
        target_path=target,
        source_root=source_root,
        source_revision="a" * 40,
    )
    monkeypatch.setattr(runner, "find_repo_root", lambda _start=None: repo_root)
    monkeypatch.setattr(
        runner,
        "resolve_package_owned_usd_cli_route",
        lambda _root: usd_cli_common.UsdCliPackageRoute(
            wrapper=wrapper,
            target=replacement_target,
            source_root=source_root,
            source_revision="a" * 40,
        ),
    )
    monkeypatch.setattr(
        runner,
        "_prepare_usd_cli_run_state",
        lambda *_args, **_kwargs: pytest.fail("route drift created daemon state"),
    )
    monkeypatch.setattr(
        runner,
        "run_bounded_usd_cli_subprocess",
        lambda *_args, **_kwargs: pytest.fail("route drift launched usd-cli"),
    )

    start = getattr(runner, start_name)
    kwargs: dict[str, object] = {"route": route, "run_dir": run_dir}
    if start_name.endswith("_strict"):
        kwargs["idle_timeout_seconds"] = 3600
    with pytest.raises(
        RuntimeError,
        match="package route changed before daemon state creation",
    ):
        start(**kwargs)

    assert not (run_dir / ".usd-cli").exists()


@pytest.mark.parametrize("parent_state_name", [".usd-cli", ".ov", ".3dsc"])
def test_start_usd_cli_run_daemon_captures_authenticated_state(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    parent_state_name: str,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    parent_state = tmp_path / parent_state_name
    parent_state.mkdir()
    parent_payloads = {
        "config.toml": (
            b"[render]\n"
            b'renderer = "remote"\n'
            b'remote_url = "https://ovrtx.example.test"\n'
            b'remote_api_key = "project-key"\n'
            b"[[render.backends]]\n"
            b'url = "https://backup.example.test"\n'
            b'api_key = "backup-key"\n'
        ),
        "server.json": b'{"pid":9999}\n',
        "daemon.pids": b"9999:t-parent\n",
    }
    for name, payload in parent_payloads.items():
        (parent_state / name).write_bytes(payload)
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=tmp_path / "usd-cli",
    )
    calls: list[dict[str, Any]] = []

    def fake_run(command: list[str], **kwargs: Any) -> subprocess.CompletedProcess[str]:
        calls.append({"command": command, **kwargs})
        state_dir = run_dir / ".usd-cli"
        assert (state_dir / "config.toml").is_file()
        if os.name == "nt":
            assert state_dir.is_dir()
            assert os.access(state_dir / "config.toml", os.W_OK)
        else:
            assert stat.S_IMODE(state_dir.stat().st_mode) == 0o700
            assert stat.S_IMODE((state_dir / "config.toml").stat().st_mode) == 0o600
        assert b"project-key" in (state_dir / "config.toml").read_bytes()
        assert b"backup-key" in (state_dir / "config.toml").read_bytes()
        for name, payload in parent_payloads.items():
            assert (parent_state / name).read_bytes() == payload
        (state_dir / "server.json").write_text(
            json.dumps(_trusted_usd_cli_daemon_state(run_dir)),
            encoding="utf-8",
        )
        (state_dir / "daemon.pids").write_bytes(b"123:t1\n")
        return subprocess.CompletedProcess(command, 0, "started", "")

    monkeypatch.setattr(runner, "run_bounded_usd_cli_subprocess", fake_run)
    _route_windows_daemon_start_through_bounded_fixture(monkeypatch, route)
    monkeypatch.setattr(
        runner,
        "sanitized_usd_cli_execution_env",
        lambda executable_dir=None: {
            "SAFE": "1",
            "USD_CLI_SERVER_HOST": "::1",
            "PATH": usd_cli_common.pinned_usd_cli_executable_path(executable_dir),
        },
    )
    monkeypatch.setattr(runner.shutil, "which", lambda *_args, **_kwargs: None)
    _mock_live_usd_cli_daemon(monkeypatch)

    lease = runner._start_usd_cli_run_daemon(route=route, run_dir=run_dir)

    assert calls == [
        {
            "command": [str(route.target_path), "server", "start"],
            "cwd": run_dir,
            "env": {
                "PATH": os.pathsep.join(
                    dict.fromkeys(
                        [
                            str(tmp_path.resolve()),
                            *[
                                entry
                                for entry in os.defpath.split(os.pathsep)
                                if entry and Path(entry).is_absolute()
                            ],
                        ]
                    )
                ),
                "SAFE": "1",
                "USD_CLI_REMOTE_RENDER_STAGING_ROOT": str(
                    runner._usd_cli_remote_render_staging_root(run_dir.resolve())
                ),
                "USD_CLI_SERVER_ALLOWED_ROOTS": str(run_dir.resolve()),
                "USD_CLI_SERVER_ALLOWED_WRITE_ROOTS": str(run_dir.resolve()),
                "USD_CLI_SERVER_HOST": "127.0.0.1",
                "USD_CLI_SERVER_IDLE_TIMEOUT": (
                    f"{runner.USD_CLI_DAEMON_IDLE_TIMEOUT_SECONDS}s"
                ),
                "USD_CLI_LOCK_RENDER_CONFIG": "1",
            },
            "timeout": runner.USD_CLI_DAEMON_START_TIMEOUT_SECONDS,
        }
    ]
    assert lease.target_path == route.target_path
    assert lease.identity == runner.UsdCliDaemonIdentity(
        pid=123,
        process_start_token="t1",
        project_id=runner._usd_cli_project_id(run_dir),
        instance_id="trusted-instance",
        process_group_id=123,
        os_session_id=123,
    )
    assert json.loads(lease.server_state_bytes)["token"] == "trusted-token"
    assert lease.daemon_ledger_bytes == b"123:t1\n"
    child_config_path = run_dir / ".usd-cli" / "config.toml"
    child_config_bytes = child_config_path.read_bytes()
    assert b"project-key" not in child_config_bytes
    assert b"backup-key" not in child_config_bytes
    assert tomllib.loads(child_config_bytes.decode("utf-8")) == {
        "render": {
            "renderer": "remote",
            "remote_url": "https://ovrtx.example.test",
            "backends": [{"url": "https://backup.example.test"}],
        },
    }
    for name, payload in parent_payloads.items():
        assert (parent_state / name).read_bytes() == payload


@pytest.mark.parametrize("failure_kind", ["nonzero", "timeout", "output_limit"])
def test_failed_usd_cli_daemon_start_cleans_captured_ledger(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    failure_kind: str,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=tmp_path / "usd-cli",
    )
    cleanup_evidence: list[runner.UsdCliDaemonCleanupEvidence] = []

    def fake_run(
        command: list[str], **_kwargs: Any
    ) -> subprocess.CompletedProcess[str]:
        state_dir = run_dir / ".usd-cli"
        (state_dir / "daemon.pids").write_bytes(b"4242:t-owned\n")
        if failure_kind == "timeout":
            raise subprocess.TimeoutExpired(command, 1.0)
        if failure_kind == "output_limit":
            raise usd_cli_common.UsdCliSubprocessOutputError("bounded output exceeded")
        return subprocess.CompletedProcess(command, 17, "", "spawn failed late")

    monkeypatch.setattr(runner, "run_bounded_usd_cli_subprocess", fake_run)
    _route_windows_daemon_start_through_bounded_fixture(monkeypatch, route)
    monkeypatch.setattr(
        runner,
        "_local_process_start_token",
        lambda pid: "t-owned" if pid == 4242 else None,
    )
    monkeypatch.setattr(runner, "_local_process_group_identity", lambda _pid: None)
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda *, lease: cleanup_evidence.append(lease),
    )

    with pytest.raises(RuntimeError, match="usd-cli daemon|server start"):
        runner._start_usd_cli_run_daemon(route=route, run_dir=run_dir)

    assert len(cleanup_evidence) == 1
    evidence = cleanup_evidence[0]
    assert evidence.target_path == route.target_path
