def test_state_appearing_during_ledger_capture_invalidates_ledger_only_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    anchor = runner._prepare_usd_cli_run_state(run_dir)
    try:
        ledger_path = run_dir / ".usd-cli" / "daemon.pids"
        ledger_path.write_bytes(b"4242:t-owned\n")
        original_read = runner._read_usd_cli_run_state_file

        def racing_read(
            captured_anchor: runner.UsdCliRunStateAnchor,
            name: str,
            **kwargs: Any,
        ) -> bytes:
            payload = original_read(captured_anchor, name, **kwargs)
            if name == "daemon.pids":
                (run_dir / ".usd-cli" / "server.json").write_text(
                    "{malformed",
                    encoding="utf-8",
                )
            return payload

        monkeypatch.setattr(runner, "_read_usd_cli_run_state_file", racing_read)
        monkeypatch.setattr(
            runner,
            "_local_process_start_token",
            lambda pid: "t-owned" if pid == 4242 else None,
        )

        assert (
            runner._capture_usd_cli_daemon_cleanup_evidence(
                target_path=tmp_path / "usd-cli",
                run_dir=run_dir,
                anchor=anchor,
            )
            is None
        )
    finally:
        runner._close_usd_cli_run_state_anchor(anchor)


