@pytest.mark.parametrize(
    "failure_kind",
    [
        "dead_before_health",
        "health_pid",
        "health_token",
        "health_project",
        "health_instance",
        "exit_after_health",
        "exit_before_lease",
        "ledger_replaced",
    ],
)
def test_usd_cli_daemon_lease_binds_live_state_ledger_and_health(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    failure_kind: str,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=tmp_path / "usd-cli",
    )
    trusted_state = _trusted_usd_cli_daemon_state(run_dir)
    cleanup_evidence: list[runner.UsdCliDaemonCleanupEvidence] = []

    def fake_run(
        command: list[str], **_kwargs: Any
    ) -> subprocess.CompletedProcess[str]:
        state_dir = run_dir / ".usd-cli"
        (state_dir / "server.json").write_text(
            json.dumps(trusted_state),
            encoding="utf-8",
        )
        (state_dir / "daemon.pids").write_bytes(b"123:t1\n")
        return subprocess.CompletedProcess(command, 0, "started", "")

    live_tokens: list[str | None]
    if failure_kind == "dead_before_health":
        live_tokens = [None]
    elif failure_kind == "exit_after_health":
        live_tokens = ["t1", None]
    elif failure_kind == "exit_before_lease":
        live_tokens = ["t1", "t1", None]
    else:
        live_tokens = ["t1", "t1", "t1"]

    final_token = live_tokens[-1]

    def fake_process_start_token(_pid: int) -> str | None:
        return live_tokens.pop(0) if live_tokens else final_token

    def fake_health(state: dict[str, Any]) -> dict[str, Any]:
        health = {
            "ok": True,
            **{
                field: state[field]
                for field in (
                    "pid",
                    "process_start_token",
                    "project_id",
                    "instance_id",
                    "lifecycle_owner",
                )
            },
        }
        mismatched_fields = {
            "health_pid": ("pid", 999),
            "health_token": ("process_start_token", "t-other"),
            "health_project": ("project_id", "other-project"),
            "health_instance": ("instance_id", "other-instance"),
        }
        if failure_kind in mismatched_fields:
            field, value = mismatched_fields[failure_kind]
            health[field] = value
        if failure_kind == "ledger_replaced":
            (run_dir / ".usd-cli" / "daemon.pids").write_bytes(b"123:t-other\n")
        return health

    monkeypatch.setattr(runner, "run_bounded_usd_cli_subprocess", fake_run)
    _route_windows_daemon_start_through_bounded_fixture(monkeypatch, route)
    monkeypatch.setattr(runner, "_local_process_start_token", fake_process_start_token)
    monkeypatch.setattr(runner, "_probe_usd_cli_daemon_health", fake_health)
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda *, lease: cleanup_evidence.append(lease),
    )

    with pytest.raises(RuntimeError, match="usd-cli daemon"):
        runner._start_usd_cli_run_daemon(route=route, run_dir=run_dir)

    expected_cleanup_count = 1 if failure_kind.startswith("health_") else 0
    assert len(cleanup_evidence) == expected_cleanup_count


