def test_strict_usd_cli_start_retains_failed_spawn_for_strict_cleanup(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=tmp_path / "usd-cli",
    )
    identity = _fake_usd_cli_daemon_identity()
    captured = runner.UsdCliDaemonCleanupEvidence(
        target_path=route.target_path,
        identities=(identity,),
        daemon_ledger_bytes=b"123:t1\n",
    )
    teardown = runner.UsdCliDaemonTeardownEvidence(
        identity=identity,
        host=None,
        port=None,
        daemon_was_started=True,
        process_released=True,
        descendants_released=True,
        sessions_released=True,
        listener_released=True,
        daemon_leases_released=True,
        state_directory_released=True,
    )
    cleanup_leases: list[runner.UsdCliDaemonCleanupEvidence] = []

    monkeypatch.setattr(
        runner,
        "run_bounded_usd_cli_subprocess",
        lambda command, **_kwargs: subprocess.CompletedProcess(
            command,
            17,
            "",
            "spawn failed after registration",
        ),
    )
    _route_windows_daemon_start_through_bounded_fixture(monkeypatch, route)
    monkeypatch.setattr(
        runner,
        "_capture_usd_cli_daemon_cleanup_evidence_with_retry",
        lambda **_kwargs: captured,
    )
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda **_kwargs: pytest.fail(
            "strict startup must not use best-effort cleanup"
        ),
    )

    def strict_cleanup(
        *, lease: runner.UsdCliDaemonCleanupEvidence
    ) -> runner.UsdCliDaemonTeardownEvidence:
        cleanup_leases.append(lease)
        assert lease.run_dir == run_dir
        assert lease.state_anchor is not None
        runner._close_usd_cli_run_state_anchor(lease.state_anchor)
        return teardown

    monkeypatch.setattr(runner, "_stop_usd_cli_run_daemon_strict", strict_cleanup)

    with pytest.raises(runner.UsdCliDaemonStrictStartError) as exc_info:
        runner._start_usd_cli_run_daemon_strict(
            route=route,
            run_dir=run_dir,
            idle_timeout_seconds=3600,
        )

    assert exc_info.value.teardown_evidence == teardown
    assert len(cleanup_leases) == 1


