@pytest.mark.skipif(
    sys.platform == "win32",
    reason="POSIX process-group observation regression",
)
def test_usd_cli_process_group_helpers_observe_current_process() -> None:
    process_group_id = os.getpgrp()
    session_id = os.getsid(0)

    assert runner._usd_cli_process_group_exists(process_group_id)
    if process_group_id > 1 and session_id > 1:
        assert runner._local_process_group_identity(os.getpid()) == (
            process_group_id,
            session_id,
        )
    else:
        assert runner._local_process_group_identity(os.getpid()) is None
    members = runner._usd_cli_process_group_members(process_group_id)
    assert any(member[0] == os.getpid() for member in members)


