def _write_optimizer_source(path: Path, *mesh_names: str) -> None:
    mesh_lines = "\n".join(f'    def Mesh "{name}" {{}}' for name in mesh_names)
    layer_text = (
        '#usda 1.0\n(\n    defaultPrim = "World"\n)\n\n'
        f'def Xform "World"\n{{\n{mesh_lines}\n}}\n'
    )
    if path.suffix.lower() != ".usdc":
        path.write_text(layer_text, encoding="utf-8")
        return
    from pxr import Sdf

    layer = Sdf.Layer.CreateAnonymous("optimizer-test.usda")
    assert layer.ImportFromString(layer_text)
    assert layer.Export(str(path))


def _write_composed_optimizer_source(path: Path, *mesh_names: str) -> None:
    sublayer = path.with_name(f"{path.stem}_geometry.usda")
    _write_optimizer_source(sublayer, *mesh_names)
    path.write_text(
        (
            "#usda 1.0\n(\n"
            f"    subLayers = [@{sublayer.name}@]\n"
            '    defaultPrim = "World"\n'
            ")\n"
        ),
        encoding="utf-8",
    )


def _deinstance_instance_roots(stage: Any) -> tuple[str, ...]:
    """Deinstance every instanced root so flattening exposes authorable prims.

    Mirrors the deinstancing side of the packaged usd-cli appearance-clear
    capability. The in-tree ``usd_core`` package that provides
    ``clear_appearance`` is a dev-checkout install that the CI unit
    environment intentionally lacks, and these fixtures carry no authored
    appearance to clear — deinstancing is the only load-bearing effect.
    """

    instance_root_paths = [
        prim.GetPath() for prim in stage.Traverse() if prim.IsInstance()
    ]
    for prim_path in instance_root_paths:
        stage.GetPrimAtPath(prim_path).SetInstanceable(False)
    return tuple(str(prim_path) for prim_path in instance_root_paths)


def _write_internal_instance_optimizer_source(
    path: Path,
    *,
    prototype_in_sublayer: bool,
) -> None:
    from pxr import Usd, UsdGeom

    def define_mesh(stage: Any, prim_path: str) -> None:
        mesh = UsdGeom.Mesh.Define(stage, prim_path)
        mesh.GetPointsAttr().Set([(0, 0, 0), (1, 0, 0), (0, 1, 0)])
        mesh.GetFaceVertexCountsAttr().Set([3])
        mesh.GetFaceVertexIndicesAttr().Set([0, 1, 2])

    stage = Usd.Stage.CreateInMemory()
    if prototype_in_sublayer:
        prototype_path = path.with_name(f"{path.stem}_prototype.usda")
        prototype_stage = Usd.Stage.CreateInMemory()
        prototype_world = UsdGeom.Xform.Define(prototype_stage, "/World").GetPrim()
        UsdGeom.Xform.Define(prototype_stage, "/World/Prototype")
        define_mesh(prototype_stage, "/World/Prototype/Mesh")
        prototype_stage.SetDefaultPrim(prototype_world)
        assert prototype_stage.GetRootLayer().Export(str(prototype_path))
        stage.GetRootLayer().subLayerPaths = [str(prototype_path)]
        world = stage.GetPrimAtPath("/World")
    else:
        world = UsdGeom.Xform.Define(stage, "/World").GetPrim()
        UsdGeom.Xform.Define(stage, "/World/Prototype")
        define_mesh(stage, "/World/Prototype/Mesh")
    instance = UsdGeom.Xform.Define(stage, "/World/Instance").GetPrim()
    instance.GetReferences().AddInternalReference("/World/Prototype")
    instance.SetInstanceable(True)
    stage.SetDefaultPrim(world)
    assert stage.GetRootLayer().Export(str(path))


def _write_external_instance_optimizer_source(
    path: Path,
    *,
    asset_path: Path,
    include_direct_mesh: bool,
    reference_identifier: str | None = None,
) -> None:
    from pxr import Usd, UsdGeom

    stage = Usd.Stage.CreateInMemory()
    world = UsdGeom.Xform.Define(stage, "/World").GetPrim()
    if include_direct_mesh:
        UsdGeom.Mesh.Define(stage, "/World/Body")
    instance = UsdGeom.Xform.Define(stage, "/World/Instance").GetPrim()
    instance.GetReferences().AddReference(
        reference_identifier or str(asset_path), "/Asset"
    )
    instance.SetInstanceable(True)
    stage.SetDefaultPrim(world)
    assert stage.GetRootLayer().Export(str(path))


def _write_external_instance_asset(path: Path) -> None:
    from pxr import Usd, UsdGeom

    stage = Usd.Stage.CreateInMemory()
    root = UsdGeom.Xform.Define(stage, "/Asset").GetPrim()
    UsdGeom.Mesh.Define(stage, "/Asset/Mesh")
    stage.SetDefaultPrim(root)
    assert stage.GetRootLayer().Export(str(path))


def _patch_optimizer_test_runtime(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    monkeypatch.setattr(runner, "_coverage_gap_issues", lambda _coverage: [])
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    monkeypatch.setattr(
        runner,
        "ensure_usd_cli_available",
        lambda _repo_root=None: "usd-cli 0.1.0 (renderer: ovrtx)",
    )
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)

    def fake_prepare_clean_inspection(
        *,
        config: MaterialAssignConfig,
        run_dir: Path,
        raw_inspection_usd_path: Path,
        clean_inspection_usd_path: Path,
        source_sha256: str,
        telemetry_route: runner.UsdCliTelemetryRoute | None = None,
    ) -> tuple[Path, str]:
        del telemetry_route
        shutil.copyfile(raw_inspection_usd_path, clean_inspection_usd_path)
        raw_digest = runner._file_digest(raw_inspection_usd_path, within=run_dir)
        clean_digest = runner._file_digest(clean_inspection_usd_path, within=run_dir)
        counts = {name: 0 for name in runner._APPEARANCE_AUDIT_ZERO_COUNTS}

        def audit_response(*, overlay_active: bool) -> dict[str, Any]:
            return {
                "schema_version": "1",
                "command": "appearance-audit",
                "ok": True,
                "summary": {"clear": True, "overlay_active": overlay_active},
                "data": {
                    "clear": True,
                    "overlay_active": overlay_active,
                    "counts": counts,
                },
            }

        clear_response = {
            "schema_version": "1",
            "command": "appearance-clear",
            "ok": True,
            "summary": {"clear": True},
            "data": {
                "audit": {
                    "clear": True,
                    "overlay_active": True,
                    "counts": counts,
                }
            },
        }
        report_path = (
            run_dir / "raw" / "scene_optimizer" / "appearance_clear_report.json"
        )
        report_path.write_text(
            json.dumps(
                {
                    "schema_version": (
                        runner.OPTIMIZED_INSPECTION_APPEARANCE_SCHEMA_VERSION
                    ),
                    "capability": runner.APPEARANCE_CLEAR_CAPABILITY,
                    "status": "pass",
                    "source_usd_path": str(config.usd_path),
                    "source_sha256_before": source_sha256,
                    "source_sha256_after": source_sha256,
                    "source_unchanged": True,
                    "raw_inspection_usd_path": str(raw_inspection_usd_path),
                    "raw_inspection_sha256_before": raw_digest,
                    "raw_inspection_sha256_after": raw_digest,
                    "raw_inspection_unchanged": True,
                    "clean_inspection_usd_path": str(clean_inspection_usd_path),
                    "clean_inspection_sha256": clean_digest,
                    "open_response": {"command": "open", "ok": True},
                    "appearance_clear_response": clear_response,
                    "appearance_audit_response": audit_response(overlay_active=True),
                    "save_response": {
                        "command": "save",
                        "ok": True,
                        "summary": {
                            "path": str(clean_inspection_usd_path),
                            "flattened": True,
                        },
                    },
                    "reopen_response": {"command": "open", "ok": True},
                    "reopened_appearance_audit_response": audit_response(
                        overlay_active=False
                    ),
                }
            ),
            encoding="utf-8",
        )
        return report_path, clean_digest

    monkeypatch.setattr(
        runner,
        "_prepare_appearance_neutral_optimized_inspection",
        fake_prepare_clean_inspection,
    )


@pytest.mark.parametrize("prototype_in_sublayer", [False, True])
def test_usd_cli_optimizer_maps_internal_instance_proxy_to_authorable_prototype(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    prototype_in_sublayer: bool,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    _write_internal_instance_optimizer_source(
        inputs["usd"],
        prototype_in_sublayer=prototype_in_sublayer,
    )
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    _patch_optimizer_test_runtime(monkeypatch, tmp_path)

    def prepare_deinstanced_clean_inspection(
        *,
        config: MaterialAssignConfig,
        run_dir: Path,
        raw_inspection_usd_path: Path,
        clean_inspection_usd_path: Path,
        source_sha256: str,
        telemetry_route: runner.UsdCliTelemetryRoute | None = None,
    ) -> tuple[Path, str]:
        from pxr import Usd

        del config, source_sha256, telemetry_route
        stage = Usd.Stage.Open(str(raw_inspection_usd_path))
        assert stage is not None
        assert _deinstance_instance_roots(stage) == ("/World/Instance",)
        assert stage.Flatten().Export(str(clean_inspection_usd_path))
        reopened = Usd.Stage.Open(str(clean_inspection_usd_path))
        assert reopened is not None
        clean_mesh = reopened.GetPrimAtPath("/World/Instance/Mesh")
        assert clean_mesh.IsValid() and not clean_mesh.IsInstanceProxy()
        report_path = (
            run_dir / "raw" / "scene_optimizer" / "appearance_clear_report.json"
        )
        report_path.write_text('{"status":"pass"}\n', encoding="utf-8")
        return (
            report_path,
            runner._file_digest(clean_inspection_usd_path, within=run_dir),
        )

    monkeypatch.setattr(
        runner,
        "_prepare_appearance_neutral_optimized_inspection",
        prepare_deinstanced_clean_inspection,
    )

    def fake_optimize(context: dict[str, Any]) -> dict[str, Any]:
        inspection = Path(context["output_usd_path"])
        _write_internal_instance_optimizer_source(
            inspection,
            prototype_in_sublayer=False,
        )
        return {
            **context,
            "optimization_success": True,
            "optimized_usd_path": str(inspection),
            "optimization_metadata": {
                "correspondence_map": {
                    "full_mapping": {
                        "original_to_prototype": {
                            "/World/Prototype/Mesh": ["/World/Prototype/Mesh"],
                        }
                    }
                }
            },
        }

    monkeypatch.setattr(runner, "_run_workflow_owned_optimizer", fake_optimize)

    context = runner._prepare_usd_cli_optimized_inspection(
        config=_usd_cli_material_assign_config(
            tmp_path,
            inputs,
            optimize=True,
        ),
        run_dir=run_dir,
        trace_writer=TraceWriter(run_dir),
    )

    correspondence = json.loads(context.correspondence_path.read_text(encoding="utf-8"))
    assert correspondence["inspection_to_source"] == {
        "/World/Instance/Mesh": ["/World/Prototype/Mesh"],
        "/World/Prototype/Mesh": ["/World/Prototype/Mesh"],
    }
    assert correspondence["source_to_inspection"]["/World/Prototype/Mesh"] == [
        "/World/Instance/Mesh",
        "/World/Prototype/Mesh",
    ]
    assert correspondence["validated_inspection_material_prim_count"] == 2


def test_ensure_usd_cli_available_never_discovers_via_path(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # A similarly named executable on PATH is never enough: authorization is
    # repository-scoped, so the caller must always name the repo root and the
    # ambient PATH is never consulted.
    def forbidden_which(*_args: object, **_kwargs: object) -> str:
        raise AssertionError("ensure_usd_cli_available must not consult PATH")

    monkeypatch.setattr(runner.shutil, "which", forbidden_which)
    with pytest.raises(TypeError):
        runner.ensure_usd_cli_available()  # type: ignore[call-arg]
    with pytest.raises(RuntimeError, match="not distributed with this repository"):
        runner.ensure_usd_cli_available(tmp_path)


def _write_authorized_usd_cli_source(repo_root: Path) -> None:
    for relative in usd_cli_common.USD_CLI_REQUIRED_SOURCE:
        path = repo_root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("source\n", encoding="utf-8")


def test_ensure_usd_cli_available_public_tree_reports_unavailable_hint(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(runner.shutil, "which", lambda _name, **_kwargs: None)
    # No in-tree source marker: a staged public tree cannot authorize a global
    # executable merely because it happens to be on PATH.
    with pytest.raises(RuntimeError, match="not distributed with this repository"):
        runner.ensure_usd_cli_available(tmp_path)

    _write_authorized_usd_cli_source(tmp_path)
    if usd_cli_common.USD_CLI_REQUIRED_SOURCE:
        with pytest.raises(RuntimeError, match="uv pip install -e"):
            runner.ensure_usd_cli_available(tmp_path)
    else:
        # Public staging ships a fail-closed compatibility module. Synthetic
        # marker files must not turn that build into an executable backend.
        with pytest.raises(RuntimeError, match="not distributed with this repository"):
            runner.ensure_usd_cli_available(tmp_path)


def _write_usd_cli_child_artifacts(
    child_run_dir: Path,
    *,
    include_output_usd: bool = True,
    vqa: dict[str, Any] | None = None,
) -> None:
    raw_dir = child_run_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    (child_run_dir / "final_renders").mkdir(parents=True, exist_ok=True)
    request_path = child_run_dir / "request.json"
    request = (
        json.loads(request_path.read_text(encoding="utf-8"))
        if request_path.is_file()
        else {}
    )
    inputs = request.get("inputs") if isinstance(request, dict) else {}
    source_path = Path(
        str(
            inputs.get("usd")
            if isinstance(inputs, dict) and inputs.get("usd")
            else child_run_dir.parent / "asset.usd"
        )
    ).resolve()
    source_digest = (
        runner._file_digest(source_path) if source_path.is_file() else "0" * 64
    )
    optimized = (raw_dir / "scene_optimizer" / "result.json").is_file()
    candidate = (
        {
            "runtime_path": "/World/OptimizedBody",
            "source_path": "/World/Body",
        }
        if optimized
        else {"source_path": "/World/Body"}
    )
    decision_group: dict[str, Any] = {
        "family": "body shell",
        "material_name": "Paint White Satin",
        "material_path": "/World/Looks/Paint_White_Satin",
        "rationale": "The reference shows a white satin body shell.",
    }
    if optimized:
        decision_group.update(
            {
                "runtime_prim_paths": ["/World/OptimizedBody"],
                "source_prim_paths": ["/World/Body"],
                "prim_paths": ["/World/Body"],
            }
        )
    else:
        decision_group["prim_paths"] = ["/World/Body"]
    (raw_dir / "visible_candidate_prims.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.visible-candidate-prims.v1",
                "path_space": "inspection" if optimized else "source",
                "candidate_visible_prim_count": 1,
                "candidates": [candidate],
            }
        ),
        encoding="utf-8",
    )
    (raw_dir / "material_decision_patch.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.material-decision-patch.v1",
                "material_assignments": [decision_group],
                "reviewed_no_override": [],
            }
        ),
        encoding="utf-8",
    )
    (child_run_dir / "assignments.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.assignments.v1",
                "assignments": [decision_group],
                "coverage": {
                    "candidate_visible_prim_count": 1,
                    "material_decision_prim_count": 1,
                    "material_assignment_prim_count": 1,
                    "missing_assignment_prim_count": 0,
                    "rejected_assignment_prim_count": 0,
                    "unassigned_visible_prim_count": 0,
                },
            }
        ),
        encoding="utf-8",
    )
    vqa_document: dict[str, Any] = {
        "schema_version": "content-agents.visual-quality-assessment.v1",
        "status": "pass",
        "checked_views": [str(child_run_dir / "final_renders" / "final_top.png")],
        "reference_images": [],
        "reference_files": [],
        "issues_found": [],
        "issues_fixed": [],
        "unresolved_issues": [],
        "assessment_notes": "Final render inspected with no unresolved issues.",
    }
    if vqa is not None:
        vqa_document.update(vqa)
    (child_run_dir / "visual_quality_assessment.json").write_text(
        json.dumps(vqa_document),
        encoding="utf-8",
    )
    (child_run_dir / "api_operation_counts.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.api-operation-counts.v1",
                "api_operation_count_total": 12,
                "render_count_total": 4,
                "pick_calls": 0,
                "material_override_commands": 1,
                "final_renders": 1,
                "coverage_candidate_visible_prims": 1,
                "coverage_material_decision_prims": 1,
                "coverage_missing_assignment_prims": 0,
                "coverage_rejected_assignment_prims": 0,
                "coverage_unassigned_visible_prims": 0,
            }
        ),
        encoding="utf-8",
    )
    (child_run_dir / "final_summary.md").write_text(
        "# Material assignment summary\n",
        encoding="utf-8",
    )
    Image.new("RGB", (16, 16), color=(245, 245, 245)).save(
        child_run_dir / "final_renders" / "final_top.png"
    )
    (raw_dir / "appearance_clear_report.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.appearance-clear-report.v1",
                "capability": "appearance.clear.v1",
                "status": "pass",
                "source_usd_path": str(source_path),
                "source_sha256_before": source_digest,
                "source_sha256_after": source_digest,
                "source_unchanged": True,
                "cli_response": {
                    "schema_version": "1",
                    "command": "appearance-clear",
                    "ok": True,
                    "summary": {"clear": True},
                    "data": {
                        "audit": {
                            "clear": True,
                            "overlay_active": True,
                            "counts": {
                                "binding_relationships_with_targets": 0,
                                "effective_material_bindings": 0,
                                "effective_shader_appearances": 0,
                                "direct_shader_outputs": 0,
                                "display_values": 0,
                                "instance_proxies": 0,
                            },
                        }
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    if include_output_usd:
        (child_run_dir / "output").mkdir(parents=True, exist_ok=True)
        (child_run_dir / "output" / "materialized.usda").write_text(
            """#usda 1.0
(
    defaultPrim = "World"
)

def Xform "World"
{
    def Scope "Looks"
    {
        def Material "Paint_White_Satin" {}
    }

    def Mesh "Body"
    {
        rel material:binding = </World/Looks/Paint_White_Satin>
    }
}
""",
            encoding="utf-8",
        )
    (child_run_dir / "child-final.md").write_text("done", encoding="utf-8")


def _write_compact_material_post_apply_review(
    *,
    run_dir: Path,
    output_sha256: str | None = None,
    checked_views: list[Path] | None = None,
) -> Path:
    output = run_dir / "output" / "materialized.usda"
    views = checked_views or runner._usd_cli_final_render_paths(run_dir)
    turntables = runner._usd_cli_turntable_artifact_paths(run_dir)
    receipt = runner._load_bounded_json_object(
        run_dir / "raw" / "material_application_receipt.json",
        within=run_dir,
    )
    retained = receipt.get("reviewed_output_binding") if receipt is not None else None
    output_binding = (
        dict(retained)
        if isinstance(retained, dict)
        else {
            "path": str(output),
            "sha256": runner._file_digest(output),
            "size_bytes": output.stat().st_size,
        }
    )
    if output_sha256 is not None:
        output_binding["sha256"] = output_sha256
    render_signature = runner._material_review_render_signature(
        runner._material_review_render_bindings(run_dir)
    )
    packet_path = run_dir / "raw" / "material_vqa_review_packet.json"
    packet_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.material-vqa-review-packet.v1",
                "output_binding": output_binding,
                "render_signature": render_signature,
            }
        ),
        encoding="utf-8",
    )
    packet_artifact = runner._read_file_artifact(packet_path, within=run_dir)
    assert packet_artifact is not None
    review = {
        "schema_version": runner.MATERIAL_POST_APPLY_REVIEW_SCHEMA_VERSION,
        "status": "pass",
        "reviewed_output_usd": output_binding["path"],
        "reviewed_output_sha256": output_binding["sha256"],
        "review_packet_binding": {
            "path": str(packet_path),
            "sha256": packet_artifact.sha256,
            "size_bytes": packet_artifact.size_bytes,
        },
        "review_render_signature": render_signature,
        "checked_views": [str(path) for path in views],
        "checked_turntable_artifacts": [str(path) for path in turntables],
        "issues_found": [],
        "issues_fixed": [],
        "unresolved_issues": [],
        "assessment_notes": (
            "Reviewed every final render and turntable frame against the reference."
        ),
    }
    path = run_dir / "raw" / "material_post_apply_review.json"
    path.write_text(json.dumps(review), encoding="utf-8")
    return path


def test_canonical_vqa_requires_bound_review_packet(tmp_path: Path) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    _write_usd_cli_child_artifacts(run_dir)
    output_digest = runner._file_digest(run_dir / "output" / "materialized.usda")

    _write_compact_material_post_apply_review(run_dir=run_dir)
    assert (
        runner._canonical_vqa_from_post_apply_review(
            config=config,
            run_dir=run_dir,
            output_digest=output_digest,
        )
        is not None
    )

    output_path = run_dir / "output" / "materialized.usda"
    output_artifact = runner._read_file_artifact(output_path, within=run_dir)
    assert output_artifact is not None
    reviewed_binding = runner._retain_material_reviewed_output(
        run_dir=run_dir,
        output_path=output_path,
        output_artifact=output_artifact,
    )
    (run_dir / "raw" / "material_application_receipt.json").write_text(
        json.dumps({"reviewed_output_binding": reviewed_binding}),
        encoding="utf-8",
    )
    _write_compact_material_post_apply_review(run_dir=run_dir)
    output_path.write_text('#usda 1.0\ndef Xform "Finalized" {}\n', encoding="utf-8")
    assert (
        runner._canonical_vqa_from_post_apply_review(
            config=config,
            run_dir=run_dir,
            output_digest=runner._file_digest(output_path, within=run_dir),
        )
        is not None
    )

    packet_path = run_dir / "raw" / "material_vqa_review_packet.json"
    for malformed in (False, True):
        _write_compact_material_post_apply_review(run_dir=run_dir)
        if malformed:
            packet_path.write_text("{}", encoding="utf-8")
        else:
            packet_path.unlink()
        assert (
            runner._canonical_vqa_from_post_apply_review(
                config=config,
                run_dir=run_dir,
                output_digest=output_digest,
            )
            is None
        )


def _write_complete_material_review_renders(
    run_dir: Path,
    *,
    turntable_directory: str = "turntable",
) -> list[Path]:
    final_dir = run_dir / "final_renders"
    turntable_dir = final_dir / turntable_directory
    turntable_dir.mkdir(parents=True, exist_ok=True)
    paths: list[Path] = []
    for index in range(24):
        path = turntable_dir / f"frame_{index:04d}.png"
        Image.new(
            "RGB",
            (16, 16),
            color=(index * 7, 255 - index * 5, index * 3),
        ).save(path)
        paths.append(path)
    for index, name in enumerate(
        ("final_top.png", "final_front.png", "final_side.png", "final_oblique.png")
    ):
        path = final_dir / name
        Image.new("RGB", (16, 16), color=(210 - index * 10,) * 3).save(path)
        paths.append(path)
    for index in range(4):
        path = final_dir / f"final_segmentation_{index}.png"
        Image.new("RGB", (16, 16), color=(index * 40, 30, 220)).save(path)
        paths.append(path)
    return paths


def test_material_vqa_packet_builds_lossless_hash_bound_review_sheets(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    _write_usd_cli_child_artifacts(run_dir)
    render_paths = _write_complete_material_review_renders(run_dir)
    output_path = run_dir / "output" / "materialized.usda"
    output_artifact = runner._read_file_artifact(output_path, within=run_dir)
    assert output_artifact is not None
    reviewed_binding = runner._retain_material_reviewed_output(
        run_dir=run_dir,
        output_path=output_path,
        output_artifact=output_artifact,
    )
    (run_dir / "raw" / "material_application_receipt.json").write_text(
        json.dumps({"reviewed_output_binding": reviewed_binding}),
        encoding="utf-8",
    )

    packet_path, packet, image_inputs = runner._write_material_vqa_review_packet(
        config=config,
        run_dir=run_dir,
        review_iteration=1,
        reference_evidence_binding=None,
        assessment=None,
        history=None,
    )

    assert packet_path.is_file()
    assert packet["output_binding"] == reviewed_binding
    assert len(packet["final_renders"]) == 32
    assert len(packet["review_sheets"]) == 6
    assert len(image_inputs) == 6
    assert all(not item["label"].startswith("Reference image") for item in image_inputs)
    turntable_sheets = packet["review_sheets"][:4]
    assert all(sheet["rows"] == 2 for sheet in turntable_sheets)
    assert all(sheet["columns"] == 3 for sheet in turntable_sheets)
    assert all(sheet["cell_size"] == [16, 16] for sheet in turntable_sheets)
    bound_frames = [
        tile["frame"] for sheet in turntable_sheets for tile in sheet["tiles"]
    ]
    assert [binding["path"] for binding in bound_frames] == [
        str(path) for path in render_paths[:24]
    ]
    assert all(
        binding["sha256"] == runner._file_digest(Path(binding["path"]))
        for binding in bound_frames
    )
    with Image.open(turntable_sheets[0]["path"]) as sheet_image:
        assert sheet_image.size == (48, 32)


