def test_material_vqa_packet_uses_captured_flat_render_batches(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    _write_usd_cli_child_artifacts(run_dir)
    final_dir = run_dir / "final_renders"
    final_dir.mkdir(parents=True, exist_ok=True)

    def render_path(angle: int, generation: int) -> Path:
        suffix = "" if generation == 1 else f"_{generation}"
        return (
            final_dir
            / f"asset__640x640__quality__focus-asset__az{angle:03d}-el20{suffix}.png"
        )

    def write_turn_items(
        items_path: Path,
        *,
        verification_generation: int,
        turntable_shared_generation: int,
        turntable_other_generation: int,
        human_output_in_reverse_order: bool = False,
    ) -> tuple[list[Path], list[Path]]:
        verification = [
            render_path(angle, verification_generation) for angle in range(0, 360, 90)
        ]
        turntable = [
            render_path(
                angle,
                (
                    turntable_shared_generation
                    if angle % 90 == 0
                    else turntable_other_generation
                ),
            )
            for angle in range(0, 360, 15)
        ]
        for index, path in enumerate(verification + turntable):
            Image.new("RGB", (16, 16), color=(index, index, index)).save(path)

        def response(paths: list[Path]) -> dict[str, object]:
            return {
                "command": "render",
                "ok": True,
                "summary": {"orbit": len(paths)},
                "data": {"results": [{"path": str(path)} for path in paths]},
            }

        if human_output_in_reverse_order:

            def human_response(paths: list[Path]) -> str:
                return "\n".join(
                    [f"camera: /asset/cam | orbit: {len(paths)}"]
                    + [
                        f"render: {path.relative_to(run_dir)} (rgb:/asset/cam)"
                        for path in paths
                    ]
                )

            items = [
                {
                    "type": "command_execution",
                    "aggregated_output": human_response(turntable),
                },
                {
                    "type": "command_execution",
                    "aggregated_output": human_response(verification),
                },
            ]
        else:
            items = [
                {
                    "type": "command_execution",
                    "aggregated_output": (
                        json.dumps(response(verification))
                        + "\n"
                        + json.dumps(response(turntable))
                    ),
                }
            ]
        items_path.write_text(json.dumps(items), encoding="utf-8")
        return verification, turntable

    write_turn_items(
        run_dir / "raw" / "codex_items.json",
        verification_generation=1,
        turntable_shared_generation=2,
        turntable_other_generation=1,
    )
    write_turn_items(
        run_dir / "raw" / "vqa_refinement_2_items.json",
        verification_generation=3,
        turntable_shared_generation=4,
        turntable_other_generation=2,
        human_output_in_reverse_order=True,
    )
    expected_verification = [render_path(angle, 5) for angle in range(0, 360, 90)]
    expected_turntable = [render_path(angle, 6) for angle in range(0, 360, 15)]
    for index, path in enumerate(expected_verification + expected_turntable):
        Image.new("RGB", (16, 16), color=(index, index, index)).save(path)

    def wrapper_response(paths: list[Path]) -> dict[str, object]:
        return {
            "command": "render",
            "ok": True,
            "summary": {"orbit": len(paths)},
            "data": {"results": [{"path": str(path)} for path in paths]},
        }

    (run_dir / "raw" / "wrapper_material_execution_2.json").write_text(
        json.dumps(
            {
                "responses": {
                    "verification_render": wrapper_response(expected_verification),
                    "turntable_render": wrapper_response(expected_turntable),
                }
            }
        ),
        encoding="utf-8",
    )

    _packet_path, packet, _image_inputs = runner._write_material_vqa_review_packet(
        config=config,
        run_dir=run_dir,
        review_iteration=2,
        reference_evidence_binding=None,
        assessment=None,
        history=None,
    )

    assert runner._usd_cli_final_render_paths(run_dir) == (
        expected_verification + expected_turntable
    )
    assert runner._usd_cli_turntable_frame_paths(run_dir) == expected_turntable
    assert [
        Path(binding["path"])
        for binding in packet["final_renders"]
        if binding["kind"] == "verification_view"
    ] == expected_verification
    assert [
        Path(binding["path"])
        for binding in packet["final_renders"]
        if binding["kind"] == "turntable_frame"
    ] == expected_turntable


def test_material_vqa_packet_recovers_pretty_redirected_wait_responses(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    _write_usd_cli_child_artifacts(run_dir)
    final_dir = run_dir / "final_renders"
    trace_dir = run_dir / "trace"
    final_dir.mkdir(parents=True, exist_ok=True)
    trace_dir.mkdir(parents=True, exist_ok=True)

    def render_paths(*, orbit: int, generation: int) -> list[Path]:
        paths = []
        for index in range(orbit):
            angle = index * (360 // orbit)
            suffix = "" if generation == 1 or angle % 90 else f"_{generation}"
            path = (
                final_dir / f"asset__640x640__quality__focus-asset__az{angle:03d}-el20"
                f"{suffix}.png"
            )
            Image.new("RGB", (16, 16), color=(index, index, index)).save(path)
            paths.append(path)
        return paths

    verification = render_paths(orbit=4, generation=1)
    turntable = render_paths(orbit=24, generation=2)
    items = []
    for job, name, paths in (
        ("j4", "verification", verification),
        ("j5", "turntable", turntable),
    ):
        orbit = len(paths)
        response = {
            "command": "render",
            "ok": True,
            "summary": {"orbit": orbit},
            "data": {"results": [{"path": str(path)} for path in paths]},
        }
        response_path = trace_dir / f"{name}_wait.json"
        response_path.write_text(json.dumps(response), encoding="utf-8")
        items.append(
            {
                "type": "command_execution",
                "status": "completed",
                "command": (
                    '/bin/bash -lc "set -euo pipefail\n'
                    f"usd-cli-tel --json wait {job} --timeout 1500 > "
                    f"trace/{name}_wait.json\n"
                    f"jq -e '{{command,ok,summary,artifact_count:{orbit}}}' "
                    f'trace/{name}_wait.json"'
                ),
                "aggregated_output": (
                    json.dumps({"command": "jobs", "ok": True}, indent=2)
                    + "\n"
                    + json.dumps(
                        {
                            "command": "render",
                            "ok": True,
                            "summary": {"orbit": orbit},
                            "artifact_count": orbit,
                        },
                        indent=2,
                    )
                ),
            }
        )
    (run_dir / "raw" / "codex_items.json").write_text(
        json.dumps(items),
        encoding="utf-8",
    )

    _packet_path, packet, _image_inputs = runner._write_material_vqa_review_packet(
        config=config,
        run_dir=run_dir,
        review_iteration=1,
        reference_evidence_binding=None,
        assessment=None,
        history=None,
    )

    assert runner._usd_cli_final_render_paths(run_dir) == verification + turntable
    assert runner._usd_cli_turntable_frame_paths(run_dir) == turntable
    assert [
        Path(binding["path"])
        for binding in packet["final_renders"]
        if binding["kind"] == "turntable_frame"
    ] == turntable


