def test_material_post_apply_review_turn_is_fresh_structured_and_tool_free(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(
        tmp_path,
        inputs,
        vision_backend="test_vision_backend",
        vision_model="test_vision_model",
    )
    run_dir = config.output_dir
    assert run_dir is not None
    _write_usd_cli_child_artifacts(run_dir)
    _write_complete_material_review_renders(run_dir)
    reference_page = run_dir / "raw" / "reference_page.png"
    Image.new("RGB", (8, 8), "blue").save(reference_page)
    (run_dir / "raw" / "material_reference_evidence.json").write_text(
        json.dumps(
            {
                "source_files": [{"path": "finish.pdf", "kind": "pdf"}],
                "image_inputs": [
                    {"label": "Reference PDF page", "path": str(reference_page)}
                ],
                "text_evidence": [],
            }
        )
    )
    reference_evidence = json.loads(
        (run_dir / "raw" / "material_reference_evidence.json").read_text()
    )
    reference_evidence_binding = runner._material_reference_evidence_binding(
        run_dir=run_dir,
        evidence=reference_evidence,
    )
    calls: list[dict[str, object]] = []
    delegated_calls: list[dict[str, object]] = []
    verification_calls: list[tuple[list[object], object | None]] = []
    receipts: list[Any] = []
    current_receipt = object()

    def fake_prepare_delegated_vision_turn(**kwargs: object) -> tuple[str, list]:
        delegated_calls.append(kwargs)
        evidence_receipts = kwargs["evidence_receipts"]
        assert isinstance(evidence_receipts, list)
        evidence_receipts.append(current_receipt)
        return f"{kwargs['prompt']}\nDelegated VQA evidence.", []

    def fake_verify_delegated_vision_evidence(
        evidence_receipts: list[object],
        *,
        current_receipt: object | None = None,
    ) -> None:
        verification_calls.append((evidence_receipts, current_receipt))

    def fake_run_child_agent(**kwargs: object) -> int:
        calls.append(kwargs)
        child_final_path = kwargs["child_final_path"]
        assert isinstance(child_final_path, Path)
        child_final_path.write_text(
            json.dumps(
                {
                    "status": "pass",
                    "issues_found": [],
                    "issues_fixed": [],
                    "unresolved_issues": [],
                    "assessment_notes": "All 32 bound render views match.",
                    "affected_renders": [],
                    "affected_prim_paths": [],
                }
            ),
            encoding="utf-8",
        )
        (run_dir / "raw" / "vqa_review_1_result.json").write_text(
            json.dumps(
                {
                    "usage": {
                        "input_tokens": 1234,
                        "cached_input_tokens": 0,
                        "output_tokens": 92,
                    }
                }
            ),
            encoding="utf-8",
        )
        return 0

    monkeypatch.setattr(runner, "_run_child_agent", fake_run_child_agent)
    monkeypatch.setattr(
        runner,
        "_prepare_delegated_vision_turn",
        fake_prepare_delegated_vision_turn,
    )
    monkeypatch.setattr(
        runner,
        "_verify_delegated_vision_evidence",
        fake_verify_delegated_vision_evidence,
    )

    returncode = runner._run_material_post_apply_review_turn(
        config=config,
        run_dir=run_dir,
        trace_writer=TraceWriter(run_dir),
        review_iteration=1,
        reference_evidence_binding=reference_evidence_binding,
        delegated_vision_receipts=receipts,
    )

    assert returncode == 0
    assert len(calls) == 1
    assert calls[0]["stage_skills"] is False
    assert calls[0]["tools_disabled"] is True
    assert calls[0]["bridge_artifact_prefix"] == "vqa_review_1"
    prompt = calls[0]["prompt"]
    output_schema = calls[0]["output_schema"]
    assert isinstance(prompt, str)
    assert isinstance(output_schema, dict)
    assert "Delegated VQA evidence." in prompt
    assert calls[0]["prompt_image_inputs"] == []
    assert len(delegated_calls[0]["prompt_image_inputs"]) == 7
    assert verification_calls == [([current_receipt], current_receipt)]
    packet = json.loads(
        (run_dir / "raw" / "material_vqa_review_packet.json").read_text()
    )
    affected_path_choices = runner._material_review_affected_path_choices(packet)
    assert packet["reference_file_evidence"]["source_files"][0]["kind"] == "pdf"
    assert output_schema == runner._material_review_output_schema(
        affected_path_choices=affected_path_choices
    )
    assert "Judge material identity at comparable visible orientations" in prompt
    assert "black-background reflections" in prompt
    issue_schema = output_schema["properties"]["issues_found"]["items"]
    assert issue_schema["properties"]["affected_prim_paths"]["minItems"] == 1
    assert (
        issue_schema["properties"]["affected_prim_paths"]["items"]["enum"]
        == affected_path_choices
    )
    assert "Do not call tools" in prompt
    review = json.loads(
        (run_dir / "raw" / "material_post_apply_review.json").read_text()
    )
    metrics = json.loads(
        (run_dir / "raw" / "material_vqa_review_metrics.json").read_text()
    )
    assert review["reviewed_output_sha256"] == packet["output_binding"]["sha256"]
    assert review["review_render_signature"] == packet["render_signature"]
    assert review["delegated_reviewed_render_signature"] == (
        runner._image_inputs_signature(runner._vqa_refinement_image_inputs(run_dir, []))
    )
    assert len(review["checked_view_bindings"]) == 32
    assert metrics["reviews"][0]["input_tokens"] == 1234


def test_material_review_requires_active_issue_material_group_handoff(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    response_path = raw_dir / "review.json"
    issue = {
        "severity": "major",
        "description": "The frame is too dark.",
        "expected_appearance": "A bright orange frame.",
        "actual_appearance": "A muddy brown frame.",
        "status": "active",
        "affected_prim_paths": [],
        "evidence_artifacts": ["turntable.png"],
    }
    response = {
        "status": "unresolved_issues",
        "issues_found": [issue],
        "issues_fixed": [],
        "unresolved_issues": [issue["description"]],
        "assessment_notes": "The frame needs one surgical material repair.",
        "affected_renders": ["turntable.png"],
        "affected_prim_paths": [],
    }
    response_path.write_text(json.dumps(response), encoding="utf-8")

    with pytest.raises(ValueError, match="semantic contract"):
        runner._load_material_review_semantic_response(
            response_path,
            run_dir=run_dir,
            allowed_affected_paths={"/Looks/Orange"},
        )

    issue["affected_prim_paths"] = ["/Looks/Orange"]
    response_path.write_text(json.dumps(response), encoding="utf-8")
    semantic = runner._load_material_review_semantic_response(
        response_path,
        run_dir=run_dir,
        allowed_affected_paths={"/Looks/Orange"},
    )
    assert semantic["affected_prim_paths"] == ["/Looks/Orange"]


def test_material_repair_scope_rejects_broad_or_unrelated_changes(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)

    def patch(material_a: str, material_b: str) -> dict[str, object]:
        return {
            "schema_version": "content-agents.material-decision-patch.v1",
            "candidate_count": 2,
            "material_assignments": [
                {
                    "material_name": material_a,
                    "material_path": f"/World/Looks/{material_a}",
                    "prim_paths": ["/World/A"],
                },
                {
                    "material_name": material_b,
                    "material_path": f"/World/Looks/{material_b}",
                    "prim_paths": ["/World/B"],
                },
            ],
            "reviewed_no_override": [],
        }

    before = patch("MatA", "MatB")
    assessment = {
        "signature": "issue-signature",
        "active_issues": [
            {
                "description": "Part A is too dark.",
                "affected_prim_paths": ["/World/A"],
            }
        ],
    }
    scope_path = raw_dir / "material_repair_scope_2.json"
    (raw_dir / "material_decision_patch.json").write_text(
        json.dumps(patch("MatA", "MatC")),
        encoding="utf-8",
    )
    scope_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.material-repair-scope.v1",
                "issue_signature": "issue-signature",
                "status": "applied",
                "target_prim_paths": ["/World/B"],
                "rationale": "Changed an unrelated part.",
            }
        ),
        encoding="utf-8",
    )
    with pytest.raises(ValueError, match="broadened beyond VQA-affected"):
        runner._validate_material_repair_scope(
            run_dir=run_dir,
            scope_path=scope_path,
            assessment=assessment,
            before_patch=before,
        )

    (raw_dir / "material_decision_patch.json").write_text(
        json.dumps(patch("MatC", "MatB")),
        encoding="utf-8",
    )
    scope_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.material-repair-scope.v1",
                "issue_signature": "issue-signature",
                "status": "applied",
                "target_prim_paths": ["/World/A", "/World/B"],
                "rationale": "Declared more paths than the repair changed.",
            }
        ),
        encoding="utf-8",
    )
    with pytest.raises(ValueError, match="exactly equal"):
        runner._validate_material_repair_scope(
            run_dir=run_dir,
            scope_path=scope_path,
            assessment=assessment,
            before_patch=before,
        )

    scope_path.write_text(
        json.dumps(
            {
                "schema_version": "content-agents.material-repair-scope.v1",
                "issue_signature": "issue-signature",
                "status": "applied",
                "target_prim_paths": ["/World/A"],
                "rationale": "Changed only the VQA-affected part.",
            }
        ),
        encoding="utf-8",
    )
    assert runner._validate_material_repair_scope(
        run_dir=run_dir,
        scope_path=scope_path,
        assessment=assessment,
        before_patch=before,
    ) == ("applied", ["/World/A"])


