@pytest.mark.parametrize("composition_arc", ["sublayer", "reference", "payload"])
def test_material_source_baseline_includes_composed_usd_layers(
    tmp_path: Path,
    composition_arc: str,
) -> None:
    from pxr import Usd

    dependency = tmp_path / f"{composition_arc}_dependency.usda"
    dependency_stage = Usd.Stage.CreateNew(str(dependency))
    dependency_stage.DefinePrim("/Asset", "Xform")
    dependency_stage.DefinePrim("/Asset/Body", "Mesh")
    dependency_stage.GetRootLayer().defaultPrim = "Asset"
    dependency_stage.GetRootLayer().Save()

    source = tmp_path / f"{composition_arc}_source.usda"
    source_stage = Usd.Stage.CreateNew(str(source))
    if composition_arc == "sublayer":
        source_stage.GetRootLayer().subLayerPaths.append(dependency.name)
    else:
        root = source_stage.DefinePrim("/World", "Xform")
        if composition_arc == "reference":
            root.GetReferences().AddReference(str(dependency), "/Asset")
        else:
            root.GetPayloads().AddPayload(str(dependency), "/Asset")
    source_stage.GetRootLayer().Save()

    baseline = runner._capture_material_source_baseline(source)

    paths = {item["path"] for item in baseline["artifacts"]}
    assert str(source.resolve()) in paths
    assert str(dependency.resolve()) in paths


def test_material_source_baseline_records_unresolved_composition(
    tmp_path: Path,
) -> None:
    """An unresolved reference is evidence, not a failure.

    USD skips a sublayer it cannot open and composes the stage without it, and
    MDL modules resolve outside USD asset resolution entirely. Aborting here
    rejected assets that compose and materialize correctly, so the baseline
    names what was skipped instead.
    """

    source = tmp_path / "missing-sublayer.usda"
    source.write_text(
        "#usda 1.0\n(\n    subLayers = [@missing.usda@]\n)\n",
        encoding="utf-8",
    )

    baseline = runner._capture_material_source_baseline(source)

    assert baseline["unresolved_dependencies"] == ["missing.usda"]
    # A reference resolving to nothing contributes no bytes, so the digest
    # still covers exactly the artifacts that were read.
    assert baseline["dependency_count"] == len(baseline["artifacts"])
    assert baseline["dependency_set_sha256"]


def test_material_source_baseline_reports_no_unresolved_for_complete_source(
    tmp_path: Path,
) -> None:
    source = tmp_path / "complete.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")

    baseline = runner._capture_material_source_baseline(source)

    assert baseline["unresolved_dependencies"] == []


