def test_scene_child_host_policy_allows_only_coordinator_subcommands(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    executable = tmp_path / (
        "content-workflow-cli.exe" if os.name == "nt" else "content-workflow-cli"
    )
    executable.write_bytes(b"test executable")
    monkeypatch.setattr(runner, "_child_workflow_name", lambda _config: "scene.run")
    monkeypatch.setattr(
        runner.shutil,
        "which",
        lambda name: str(executable) if name == "content-workflow-cli" else None,
    )
    config = SimpleNamespace(scene_backend="not-usd-cli")

    entries = runner._codex_host_executables(config, tmp_path)
    entry = next(item for item in entries if item["name"] == "content-workflow-cli")

    assert entry["paths"] == [str(executable.resolve())]
    expected_prefixes = [
        ["content-workflow-cli", "scene", command]
        for command in (
            "phase",
            "decompose",
            "process",
            "material-task",
            "collect",
        )
    ]
    if os.name == "nt":
        expected_prefixes.insert(0, ["content-workflow-cli", "artifact", "write-json"])
    assert entry["allowed_prefixes"] == expected_prefixes
    assert ["content-workflow-cli", "scene", "run"] not in entry["allowed_prefixes"]


@pytest.mark.skipif(os.name != "nt", reason="Windows host executable policy")
def test_codex_host_executables_pin_active_windows_python(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config = SimpleNamespace(scene_backend="not-usd-cli")
    monkeypatch.setattr(runner, "_child_workflow_name", lambda _config: "test.run")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    helper = tmp_path / "trusted" / "prepare_mesh.py"
    helper.parent.mkdir()
    helper.write_text("print('trusted')\n", encoding="utf-8")
    digest = hashlib.sha256(helper.read_bytes()).hexdigest()

    entries = runner._codex_host_executables(
        config,
        run_dir,
        trusted_script_digests={str(helper.resolve()): digest},
    )
    entry = next(item for item in entries if item["name"] == "python")
    cli_entry = next(item for item in entries if item["name"] == "content-workflow-cli")

    assert entry == {
        "name": "python",
        "paths": [str(Path(sys.executable).resolve())],
        "allowed_prefixes": [
            ["python", "--version"],
            ["python", str(helper.resolve())],
            ["python", "-E", str(helper.resolve())],
            ["python", helper.resolve().as_posix()],
            ["python", "-E", helper.resolve().as_posix()],
        ],
    }
    assert cli_entry["allowed_prefixes"] == [
        ["content-workflow-cli", "artifact", "write-json"]
    ]


