def test_claude_request_uses_confined_cwd_without_additional_directories(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _allow_fake_usd_cli_telemetry_route(monkeypatch)
    inputs = _write_usd_cli_material_inputs(tmp_path)
    run_dir = tmp_path / "runs" / "asset-1"
    (run_dir / "raw").mkdir(parents=True)
    config = _usd_cli_material_assign_config(
        tmp_path,
        inputs,
        agent_cwd=run_dir,
        runner=runner.RUNNER_CLAUDE,
    )
    child_bin = tmp_path / "child-bin"
    child_bin.mkdir()
    executable_suffix = ".exe" if os.name == "nt" else ""
    for name in ("usd-cli", "usd-cli-tel"):
        executable = child_bin / f"{name}{executable_suffix}"
        if os.name == "nt":
            node_executable = shutil.which("node")
            if node_executable is None:
                pytest.skip("Node.js is required for a native Windows fixture")
            shutil.copy2(node_executable, executable)
        else:
            executable.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
            executable.chmod(executable.stat().st_mode | stat.S_IXUSR)
    monkeypatch.setenv("PATH", str(child_bin))

    subprocess_call: dict[str, Any] = {}

    def fake_subprocess_with_timeout(**kwargs: Any) -> int:
        subprocess_call.update(kwargs)
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )
    returncode = runner._run_child_agent_claude(
        config=config,
        prompt="prompt",
        run_dir=run_dir,
        child_output_path=run_dir / "child-output.log",
        child_final_path=run_dir / "child-final.md",
    )

    assert returncode == 0
    sdk_request = json.loads(
        (run_dir / "raw" / "claude_request.json").read_text(encoding="utf-8")
    )
    assert sdk_request["repo_root"] == str(run_dir.resolve())
    assert sdk_request["additional_directories"] == []
    assert sdk_request["workflow"] == "materials.assign"
    assert sdk_request["scene_backend"] == runner.SCENE_BACKEND_USD_CLI
    child_env = subprocess_call["env"]
    assert child_env["PATH"] == os.environ["PATH"]
    assert os.path.normcase(child_env["USD_CLI_TEL_TARGET"]) == os.path.normcase(
        str((child_bin / f"usd-cli{executable_suffix}").resolve())
    )


