def test_codex_bridge_env_carries_run_trace_context(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _allow_fake_usd_cli_telemetry_route(monkeypatch)
    monkeypatch.setattr(
        runner,
        "_probe_usd_cli_telemetry_wrapper",
        lambda *_args: None,
    )
    inputs = _write_usd_cli_material_inputs(tmp_path)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    child_bin = tmp_path / "child-bin"
    child_bin.mkdir()
    for name in ("usd-cli", "usd-cli-tel"):
        executable = child_bin / name
        executable.write_text("#!/bin/sh\nexit 0\n", encoding="utf-8")
        executable.chmod(executable.stat().st_mode | stat.S_IXUSR)
    monkeypatch.setenv("PATH", str(child_bin))
    monkeypatch.setenv(
        runner.PARENT_USD_CLI_AUTH_PROXY_ENV,
        "http://127.0.0.1:32123",
    )

    env = runner._codex_bridge_env(config, run_dir)
    assert env["XDG_CACHE_HOME"] == str(run_dir.resolve() / ".cache")
    assert env["WARP_CACHE_PATH"] == str(run_dir.resolve() / ".cache" / "warp")
    assert env["USD_CLI_TEL_FILE"] == str(run_dir / "raw" / "usd_cli_telemetry.jsonl")
    assert env[runner.USD_CLI_REMOTE_RENDER_STAGING_ROOT_ENV] == str(
        runner._usd_cli_remote_render_staging_root(run_dir.resolve())
    )
    assert env["TRACEPARENT"].startswith("00-")
    assert env["PATH"] == os.environ["PATH"]
    assert env["USD_CLI_TEL_TARGET"] == str((child_bin / "usd-cli").resolve())
    assert runner.PARENT_USD_CLI_AUTH_PROXY_ENV not in env
    if os.name == "nt":
        assert env["PYTHONSAFEPATH"] == ""
        assert env["CONTENT_WORKFLOW_CONTROLLED_ARTIFACT_ROOT"] == str(
            run_dir.resolve()
        )
    # Without a run dir (legacy callers) the env stays telemetry-free.
    assert "TRACEPARENT" not in runner._codex_bridge_env(config)


