def test_reused_output_dir_mints_and_persists_a_fresh_trace_context(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    config = _usd_cli_material_assign_config(tmp_path, inputs)

    first = runner._build_request(config, run_dir)
    (run_dir / "request.json").write_text(json.dumps(first), encoding="utf-8")
    first_context = runner._run_trace_context(run_dir)

    second = runner._build_request(config, run_dir)
    (run_dir / "request.json").write_text(json.dumps(second), encoding="utf-8")
    second_context = runner._run_trace_context(run_dir)

    assert first_context != second_context
    assert first_context == (
        first["telemetry"]["trace_id"],
        first["telemetry"]["root_span_id"],
    )
    assert second_context == (
        second["telemetry"]["trace_id"],
        second["telemetry"]["root_span_id"],
    )


def test_reused_output_dir_archives_all_prior_usd_cli_run_artifacts(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = runner._prepare_run_dir(config)
    with runner._VALIDATED_MATERIAL_STRIPS_LOCK:
        runner._VALIDATED_MATERIAL_STRIPS[str(run_dir.resolve())] = "prior-digest"
    prior_files = {
        run_dir / "trace" / "events.jsonl": "old trace\n",
        run_dir / "raw" / "usd_cli_telemetry.jsonl.1": "old rotated\n",
        run_dir / "raw" / "usd_cli_telemetry.jsonl": "old live\n",
        run_dir / "raw" / "codex_items.json": "old bridge items\n",
        run_dir / "assignments.json": "old assignments\n",
        run_dir / "api_operation_counts.json": "old counts\n",
        run_dir / "visual_quality_assessment.json": "old VQA\n",
        run_dir / "final_summary.md": "old summary\n",
        run_dir / "validation_evidence.json": "old evidence\n",
        run_dir / "run_cost_metrics.json": "old costs\n",
        run_dir / "output" / "materialized.usda": "old USD\n",
        run_dir / "final_renders" / "old.png": "old render\n",
        run_dir / ".usd-cli" / "server.json": "old daemon state\n",
    }
    for path, content in prior_files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")

    assert runner._prepare_run_dir(config) == run_dir
    with runner._VALIDATED_MATERIAL_STRIPS_LOCK:
        assert str(run_dir.resolve()) not in runner._VALIDATED_MATERIAL_STRIPS

    assert all(not path.exists() for path in prior_files)
    archives = list((run_dir / "raw" / "prior_usd_cli_runs").iterdir())
    assert len(archives) == 1
    assert (archives[0] / "trace" / "events.jsonl").read_text(
        encoding="utf-8"
    ) == "old trace\n"
    assert (archives[0] / "raw" / "usd_cli_telemetry.jsonl.1").read_text(
        encoding="utf-8"
    ) == "old rotated\n"
    assert (archives[0] / "raw" / "usd_cli_telemetry.jsonl").read_text(
        encoding="utf-8"
    ) == "old live\n"
    assert (archives[0] / "raw" / "codex_items.json").read_text(
        encoding="utf-8"
    ) == "old bridge items\n"
    assert (archives[0] / "assignments.json").read_text(
        encoding="utf-8"
    ) == "old assignments\n"
    assert (archives[0] / "output" / "materialized.usda").read_text(
        encoding="utf-8"
    ) == "old USD\n"
    assert (archives[0] / "final_renders" / "old.png").read_text(
        encoding="utf-8"
    ) == "old render\n"
    assert (archives[0] / ".usd-cli" / "server.json").read_text(
        encoding="utf-8"
    ) == "old daemon state\n"
    assert not (run_dir / ".usd-cli").exists()
    assert (run_dir / "raw").is_dir()
    assert (run_dir / "trace").is_dir()
    assert (run_dir / "final_renders").is_dir()
    assert (run_dir / "output").is_dir()


