def test_usd_cli_normalizes_known_pre_migration_child_artifacts(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    _write_usd_cli_child_artifacts(run_dir)

    assignments_path = run_dir / "assignments.json"
    assignments = json.loads(assignments_path.read_text(encoding="utf-8"))
    legacy_groups = assignments.pop("assignments")
    for group in legacy_groups:
        group["coverage_status"] = "assigned"
    assignments.pop("coverage")
    assignments["schema_version"] = "content-agents.material-assignments.v1"
    assignments["assignment_groups"] = legacy_groups
    assignments_path.write_text(json.dumps(assignments), encoding="utf-8")

    vqa_path = run_dir / "visual_quality_assessment.json"
    vqa = json.loads(vqa_path.read_text(encoding="utf-8"))
    vqa.update(
        {
            "schema_version": ("content-agents.material-visual-quality-assessment.v1"),
            "status": "pass_with_limitations",
            "issues_found": [
                {
                    "severity": "minor",
                    "description": "The palette has no exact wood material.",
                    "affected_prim_paths": ["/World/Body"],
                    "affected_renders": vqa["checked_views"],
                }
            ],
            "issues_fixed": [
                {"description": "Replaced an obstructed verification view."}
            ],
            "unresolved_issues": ["The palette has no exact wood material."],
            "assessment_notes": ["Bindings are complete.", "Renders are legible."],
        }
    )
    vqa_path.write_text(json.dumps(vqa), encoding="utf-8")

    normalized = runner._normalize_usd_cli_child_contract_artifacts(run_dir)

    assert normalized == [assignments_path, vqa_path]
    normalized_assignments = json.loads(assignments_path.read_text(encoding="utf-8"))
    normalized_vqa = json.loads(vqa_path.read_text(encoding="utf-8"))
    assert runner._valid_usd_cli_assignments(
        normalized_assignments,
        run_dir=run_dir,
    )
    assert runner._valid_usd_cli_visual_quality(normalized_vqa, run_dir=run_dir)
    assert normalized_assignments["assignments"][0]["coverage_status"] == (
        "material_assignment"
    )
    assert normalized_vqa["status"] == "unresolved_issues"
    assert normalized_vqa["issues_fixed"] == [
        "Replaced an obstructed verification view."
    ]
    assert (run_dir / "raw" / "child_assignments.pre_normalization.json").is_file()
    assert (
        run_dir / "raw" / "child_visual_quality_assessment.pre_normalization.json"
    ).is_file()


def test_usd_cli_normalizes_assignment_identity_from_staged_manifests(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    staged_source = run_dir / "inputs" / "source" / "asset.usda"
    staged_library = run_dir / "inputs" / "material_library" / "materials.usda"
    staged_source.parent.mkdir(parents=True)
    staged_library.parent.mkdir(parents=True)
    staged_source.write_text("#usda 1.0\n", encoding="utf-8")
