def test_usd_cli_contract_requires_exact_schemas_and_consistent_counts(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    _write_usd_cli_child_artifacts(run_dir)
    artifact_paths = (
        run_dir / "raw" / "visible_candidate_prims.json",
        run_dir / "assignments.json",
        run_dir / "api_operation_counts.json",
        run_dir / "visual_quality_assessment.json",
    )
    for path in artifact_paths:
        payload = json.loads(path.read_text(encoding="utf-8"))
        payload.pop("schema_version")
        path.write_text(json.dumps(payload), encoding="utf-8")
    missing = runner._usd_cli_missing_contract_artifacts(run_dir)
    assert all(str(path) in missing for path in artifact_paths)

    _write_usd_cli_child_artifacts(run_dir)
    counts_path = run_dir / "api_operation_counts.json"
    counts = json.loads(counts_path.read_text(encoding="utf-8"))
    counts["material_override_commands"] = 2
    counts["final_renders"] = 3
    counts_path.write_text(json.dumps(counts), encoding="utf-8")
    assert not runner._valid_usd_cli_operation_counts(counts, run_dir=run_dir)

    _write_usd_cli_child_artifacts(run_dir)
    counts = json.loads(counts_path.read_text(encoding="utf-8"))
    counts["api_operation_count_total"] = 1
    counts["pick_calls"] = 1
    counts_path.write_text(json.dumps(counts), encoding="utf-8")
    assert not runner._valid_usd_cli_operation_counts(counts, run_dir=run_dir)


