def test_usd_cli_finalizer_accepts_exact_library_import_identity(
    tmp_path: Path,
) -> None:
    from pxr import Usd, UsdGeom, UsdShade

    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    (run_dir / "raw").mkdir(parents=True)
    (run_dir / "output").mkdir()

    output = run_dir / "output" / "materialized.usda"
    stage = Usd.Stage.CreateNew(str(output))
    world = UsdGeom.Xform.Define(stage, "/World")
    stage.SetDefaultPrim(world.GetPrim())
    body = UsdGeom.Mesh.Define(stage, "/World/Body")
    imported_path = (
        "/World/Looks/Paint_White_Satin_"
        + hashlib.sha256(b"/World/Looks/Paint_White_Satin").hexdigest()[:12]
    )
    imported = UsdShade.Material.Define(stage, imported_path)
    imported.GetPrim().SetCustomDataByKey(
        "usdCliLibrarySourcePrim",
        "/World/Looks/Paint_White_Satin",
    )
    imported.GetPrim().SetCustomDataByKey(
        "usdCliLibraryAsset",
        os.path.relpath(inputs["materials_usd"], output.parent),
    )
    UsdShade.MaterialBindingAPI.Apply(body.GetPrim()).Bind(imported)
    stage.Save()

    patch = {
        "material_assignments": [
            {
                "material_name": "Paint White Satin",
                "material_path": "/World/Looks/Paint_White_Satin",
                "prim_paths": ["/World/Body"],
                "source_prim_paths": ["/World/Body"],
                "runtime_prim_paths": ["/World/Body"],
            }
        ],
        "reviewed_no_override": [],
    }
    candidates = {"candidates": [{"source_path": "/World/Body"}]}
    manifest = runner._resolved_material_manifest(config)

    assert (
        runner._write_usd_cli_binding_audit(
            config=config,
            run_dir=run_dir,
            manifest=manifest,
            patch=patch,
            candidate_document=candidates,
        )
        == []
    )
    assert (
        runner._write_reopened_clean_slate_appearance_audit(
            config=config,
            run_dir=run_dir,
            manifest=manifest,
            patch=patch,
        )
        == []
    )
    assert (
        runner._write_reopened_clean_slate_appearance_audit(
            config=config,
            run_dir=run_dir,
            manifest=manifest,
            patch=patch,
        )
        == []
    )
    assert (
        runner._validate_optimized_output_stage(
            run_dir=run_dir,
            source_prim_paths={"/World", "/World/Body"},
            output_usd=output,
            expected_materials={
                "/World/Body": (
                    "Paint White Satin",
                    "/World/Looks/Paint_White_Satin",
                )
            },
        )["verified_bound_target_count"]
        == 1
    )

    binding_audit = json.loads(
        (run_dir / "raw" / "binding_audit.json").read_text(encoding="utf-8")
    )
    assert binding_audit["status"] == "pass"
    assert binding_audit["records"][0]["bound_material_path"] == imported_path
    reopened_audit = json.loads(
        (run_dir / "raw" / "reopened_appearance_audit.json").read_text(encoding="utf-8")
    )
    assert reopened_audit["status"] == "pass"
    strip_report = runner._strip_validated_material_provenance(
        run_dir=run_dir,
        output_usd=output,
    )
    assert strip_report["stripped_prim_count"] == 1
    stripped_stage = Usd.Stage.Open(str(output))
    stripped_prim = stripped_stage.GetPrimAtPath(imported.GetPath())
    assert stripped_prim.IsValid()
    assert not stripped_prim.HasCustomDataKey("usdCliLibraryAsset")
    assert not stripped_prim.HasCustomDataKey("usdCliLibrarySourcePrim")
    runner._write_private_json(
        run_dir / "raw" / "material_provenance_strip.json",
        strip_report,
        within=run_dir,
    )
    # Recovery re-finalization audits the materialized USD after stripping its
    # private provenance.  The exact-import name remains a deterministic,
    # manifest-bound identity and must therefore still be accepted.
    assert (
        runner._write_usd_cli_binding_audit(
            config=config,
            run_dir=run_dir,
            manifest=manifest,
            patch=patch,
            candidate_document=candidates,
        )
        == []
    )
    assert (
        runner._write_reopened_clean_slate_appearance_audit(
            config=config,
            run_dir=run_dir,
            manifest=manifest,
            patch=patch,
        )
        == []
    )
    # The optimized source-space restoration preflight and derivative audit
    # also consume the wrapper-owned strip trust.  Without that allowance,
    # they reject the legitimate deterministic import after its private
    # provenance metadata was removed.
    assert runner._restore_validated_optimized_source_bindings(
        run_dir=run_dir,
        output_usd=output,
        expected_materials={
            "/World/Body": (
                "Paint White Satin",
                "/World/Looks/Paint_White_Satin",
            )
        },
        runtime_aliases={},
    ) == (0, 0)
    assert (
        runner._validate_optimized_output_stage(
            run_dir=run_dir,
            source_prim_paths={"/World", "/World/Body"},
            output_usd=output,
            expected_materials={
                "/World/Body": (
                    "Paint White Satin",
                    "/World/Looks/Paint_White_Satin",
                )
            },
        )["verified_bound_target_count"]
        == 1
    )


def test_source_restoration_reanchors_proven_checkpoint_library_identity(
    tmp_path: Path,
) -> None:
    from pxr import Usd, UsdGeom, UsdShade

    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    (run_dir / "raw").mkdir(parents=True)
    staged_library = runner._stage_usd_cli_input_tree(
        label="material_library",
        source_usd_path=inputs["materials_usd"],
        run_dir=run_dir,
    ).staged_usd_path
    output = run_dir / "output" / "materialized.usda"
    output.parent.mkdir()
    checkpoint = run_dir / ".usd-cli" / "checkpoints" / "post_refinement.usd"
    checkpoint.parent.mkdir(parents=True)
    imported_path = "/World/Looks/Paint_White_Satin_6ddc192f849f"
    stored_identity = os.path.relpath(staged_library, checkpoint.parent)

    def write_bound_stage(path: Path) -> None:
        stage = Usd.Stage.CreateNew(str(path))
        world = UsdGeom.Xform.Define(stage, "/World")
        stage.SetDefaultPrim(world.GetPrim())
        body = UsdGeom.Mesh.Define(stage, "/World/Body")
        material = UsdShade.Material.Define(stage, imported_path)
        material.GetPrim().SetCustomDataByKey(
            "usdCliLibrarySourcePrim",
            "/World/Looks/Paint_White_Satin",
        )
        material.GetPrim().SetCustomDataByKey(
            "usdCliLibraryAsset",
            stored_identity,
        )
        UsdShade.MaterialBindingAPI.Apply(body.GetPrim()).Bind(material)
        stage.Save()

    write_bound_stage(checkpoint)
    write_bound_stage(output)

    assert runner._restore_validated_optimized_source_bindings(
        run_dir=run_dir,
        output_usd=output,
        expected_materials={
            "/World/Body": (
                "Paint White Satin",
                "/World/Looks/Paint_White_Satin",
            )
        },
        runtime_aliases={},
    ) == (0, 1)

    reopened = Usd.Stage.Open(str(output))
    assert reopened is not None
    assert reopened.GetPrimAtPath(imported_path).GetCustomDataByKey(
        "usdCliLibraryAsset"
    ) == os.path.realpath(staged_library)
    assert (
        runner._write_usd_cli_binding_audit(
            config=config,
            run_dir=run_dir,
            manifest=runner._resolved_material_manifest(config),
            patch={
                "material_assignments": [
                    {
                        "material_name": "Paint White Satin",
                        "material_path": "/World/Looks/Paint_White_Satin",
                        "prim_paths": ["/World/Body"],
                    }
                ],
                "reviewed_no_override": [],
            },
            candidate_document={"candidates": [{"source_path": "/World/Body"}]},
        )
        == []
    )


