    digest = runner._file_digest(inputs["usd"])
    (raw_dir / "source_integrity.json").write_text(
        json.dumps({"initial_sha256": digest}),
        encoding="utf-8",
    )
    complete_response = {
        "schema_version": "1",
        "command": "appearance-clear",
        "ok": True,
        "summary": {"clear": True, "bindings_masked": 2},
        "data": {
            "audit": {
                "clear": True,
                "overlay_active": True,
                "counts": {
                    "binding_relationships_with_targets": 0,
                    "effective_material_bindings": 0,
                    "effective_shader_appearances": 0,
                    "direct_shader_outputs": 0,
                    "display_values": 0,
                    "instance_proxies": 0,
                },
            }
        },
    }
    incomplete_response = json.loads(json.dumps(complete_response))
    del incomplete_response["data"]["audit"]["counts"]["instance_proxies"]
    original_report = {
        "schema_version": runner.APPEARANCE_CLEAR_REPORT_SCHEMA_VERSION,
        "capability": runner.APPEARANCE_CLEAR_CAPABILITY,
        "status": "pass",
        "source_path": str(inputs["usd"].resolve()),
        "source_sha256_before": digest,
        "source_sha256_after": digest,
        "source_unchanged": True,
        "cli_response": incomplete_response,
    }
    appearance_clear_path = raw_dir / "appearance_clear_report.json"
    appearance_clear_path.write_text(
        json.dumps(original_report),
        encoding="utf-8",
    )
    (trace_dir / "operation_trace.json").write_text(
        json.dumps(
            {
                "schema_version": "content-agents.trace.v1",
                "workflow": "materials.assign",
                "child_commands": [
                    {
                        "id": "item_9",
                        "type": "command_execution",
                        "status": "completed",
                        "command": (
                            "/bin/bash -lc 'usd-cli-tel --json appearance clear'"
                        ),
                        "exit_code": 0,
                        "output_excerpt": json.dumps(complete_response) + "\n",
                    }
                ],
            }
        ),
        encoding="utf-8",
    )

    normalized = runner._normalize_usd_cli_child_contract_artifacts(run_dir)

    assert appearance_clear_path in normalized
    assert (
        json.loads(appearance_clear_path.read_text(encoding="utf-8"))["cli_response"]
        == complete_response
    )
    assert (
        json.loads(
            (
                raw_dir / "child_appearance_clear_report.pre_normalization.json"
            ).read_text(encoding="utf-8")
        )
        == original_report
    )
    assert runner._appearance_clear_report_errors(config=config, run_dir=run_dir) == []


