def test_appearance_clear_identity_normalization_uses_verified_staged_bytes(
    tmp_path: Path,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    run_dir = config.output_dir
    assert run_dir is not None
    raw_dir = run_dir / "raw"
    staged_source = run_dir / "inputs" / "source" / inputs["usd"].name
    staged_source.parent.mkdir(parents=True)
    staged_source.write_text("mutated", encoding="utf-8")
    raw_dir.mkdir(parents=True)
    digest = runner._file_digest(inputs["usd"])
    (raw_dir / "source_integrity.json").write_text(
        json.dumps(
            {
                "status": "pass",
                "source_unchanged": True,
                "errors": [],
                "initial_sha256": digest,
                "current_sha256": digest,
            }
        ),
        encoding="utf-8",
    )
    (raw_dir / "staged_input_source.json").write_text(
        json.dumps(
            {
                "schema_version": runner.USD_CLI_STAGED_INPUT_SCHEMA_VERSION,
                "source_sha256": digest,
                "staged_usd_path": str(staged_source),
            }
        ),
        encoding="utf-8",
    )
    report_path = raw_dir / "appearance_clear_report.json"
    report_path.write_text(
        json.dumps(
            {
                "schema_version": runner.APPEARANCE_CLEAR_REPORT_SCHEMA_VERSION,
                "capability": runner.APPEARANCE_CLEAR_CAPABILITY,
                "status": "pass",
                "source_usd_path": str(staged_source),
                "source_sha256_before": "null",
                "source_sha256_after": digest,
                "source_unchanged": False,
                "cli_response": {
                    "schema_version": "1",
                    "command": "appearance-clear",
                    "ok": True,
                    "summary": {"clear": True},
                    "data": {
                        "audit": {
                            "clear": True,
                            "overlay_active": True,
                            "counts": {
                                "binding_relationships_with_targets": 0,
                                "effective_material_bindings": 0,
                                "effective_shader_appearances": 0,
                                "direct_shader_outputs": 0,
                                "display_values": 0,
                                "instance_proxies": 0,
                            },
                        }
                    },
                },
            }
        ),
        encoding="utf-8",
    )

    assert (
        runner._normalize_appearance_clear_report_identity(
            config=config,
            run_dir=run_dir,
        )
        is None
    )
    assert (
        json.loads(report_path.read_text(encoding="utf-8"))["source_unchanged"] is False
    )

    staged_source.write_bytes(inputs["usd"].read_bytes())
    normalized = runner._normalize_appearance_clear_report_identity(
        config=config,
        run_dir=run_dir,
    )

    assert normalized == report_path
    canonical = json.loads(report_path.read_text(encoding="utf-8"))
    assert canonical["source_sha256_before"] == digest
    assert canonical["source_sha256_after"] == digest
    assert canonical["source_unchanged"] is True
    assert runner._appearance_clear_report_errors(config=config, run_dir=run_dir) == []
    archived = json.loads(
        (raw_dir / "child_appearance_clear_report.pre_normalization.json").read_text(
            encoding="utf-8"
        )
    )
    assert archived["source_sha256_before"] == "null"


