def test_finalize_physics_pins_the_wrapper_owned_durable_output_path(
    tmp_path: Path,
    monkeypatch: Any,
    physics_packet_writer: Any,
) -> None:
    run_dir = tmp_path / "physics-run"
    (run_dir / "raw").mkdir(parents=True)
    source_usd = tmp_path / "asset.usda"
    inspection_usd = tmp_path / "asset.optimized.usda"
    source_usd.write_text("#usda 1.0\n", encoding="utf-8")
    inspection_usd.write_text(
        '#usda 1.0\ndef Xform "World" {}\n',
        encoding="utf-8",
    )
    runtime_report_path = run_dir / "runtime_validation_report.json"
    runtime_report_path.write_text(
        json.dumps(
            {
                "phase_timings_seconds": {
                    "support_selection": 0.01,
                    "scene_build": 0.02,
                    "simulation": 0.03,
                    "acceptance": 0.04,
                }
            }
        ),
        encoding="utf-8",
    )
    packet = physics_packet_writer(
        run_dir,
        source_usd,
        inspection_usd=inspection_usd,
        source_path_expansions={"/World/Cube": ["/Source/Cube"]},
    )
    inspection_pin = runner._physics_inspection_pin_from_packet(
        PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=source_usd,
            output_dir=run_dir,
        ),
        packet,
    )
    captured: dict[str, Any] = {}

    def fake_run_physics_apply_workflow(params: Any) -> SimpleNamespace:
        captured["params"] = params
        return SimpleNamespace(
            model_dump=lambda **_kwargs: {"success": True},
            validation_evidence_path=str(run_dir / "validation_evidence.json"),
            simulation_report_path=str(runtime_report_path),
            physics_usd_path=str(run_dir / "physics.usdc"),
            apply_report_path=None,
            assignments_path=str(run_dir / "physics_assignments.json"),
            vomp_result_path=None,
            vomp_provenance_path=None,
            validation_status="pass",
            success=True,
            error=None,
        )

    monkeypatch.setattr(
        "content_agent_workflows.physics.run_physics_apply_workflow",
        fake_run_physics_apply_workflow,
    )
    monkeypatch.setattr(
        runner,
        "_render_physics_validation_frames",
        lambda **_kwargs: [],
    )

    support_cache: dict[str, dict[str, Any]] = {}
    runner._finalize_physics_once(
        config=PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=source_usd,
            output_dir=run_dir,
        ),
        run_dir=run_dir,
        inspection_pin=inspection_pin,
        session_id="session-1",
        iteration=0,
        trace_writer=TraceWriter(run_dir),
        usd_cli_session=runner.WorkflowUsdCliSession(
            project_dir=run_dir,
            session_id="physics-test-session",
            route=SimpleNamespace(),
            workflow="physics.apply",
        ),
        ground_clearance_support_cache=support_cache,
        run_state={},
    )

    # The workflow pins its durable in-run output; an operator-requested
    # destination remains separate via output_usd_path.
    assert captured["params"].output_usd_path == run_dir.resolve() / "physics.usda"
    assert captured["params"].usd_path == inspection_usd
    assert captured["params"].source_usd_path == source_usd
    assert captured["params"].source_asset_sha256 == runner._file_digest(source_usd)
    assert captured["params"].inspection_asset_sha256 == runner._file_digest(
        inspection_usd
    )
    assert captured["params"].path_space == "inspection"
    assert captured["params"].source_path_expansions == {
        "/World/Cube": ["/Source/Cube"]
    }
    assert captured["params"].vomp_artifact_namespace == "finalize-0000"
    assert captured["params"].usd_cli_session.session_id == "physics-test-session"
    assert captured["params"].ground_clearance_support_cache is support_cache
    assert not hasattr(captured["params"], "workbench_export_dir")
    finalize_record = json.loads(
        (run_dir / "raw" / "physics_finalize_result_0.json").read_text(encoding="utf-8")
    )
    assert finalize_record["phase_timings_seconds"] == {
        "support_selection": 0.01,
        "scene_build": 0.02,
        "simulation": 0.03,
        "acceptance": 0.04,
    }
    assert finalize_record["rendering_duration_seconds"] >= 0.0


def test_usd_cli_physics_render_writes_attestable_ovrtx_receipt(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from content_agent_workflows.physics import usd_cli_ops

    run_dir = tmp_path / "physics-run"
    raw_dir = run_dir / "raw"
    runtime_dir = run_dir / "runtime"
    raw_dir.mkdir(parents=True)
    runtime_dir.mkdir()
    recording = runtime_dir / "recording.usda"
    scene = runtime_dir / "drop_settle_scene.usda"
    physics_usd = run_dir / "physics.usda"
    for path in (scene, physics_usd):
        path.write_text("#usda 1.0\n", encoding="utf-8")
    from world_understanding.functions.graphics.so_export import portable_sidecar_name

    recording_sidecar = recording.parent / portable_sidecar_name(recording)
    recording_sidecar.mkdir()
    recording_dependency = recording_sidecar / "animated_mesh.usda"
    recording_dependency.write_text("#usda 1.0\n", encoding="utf-8")
    recording.write_text(
        "#usda 1.0\n(\n    subLayers = "
        f"[@{recording_sidecar.name}/animated_mesh.usda@]\n)\n",
        encoding="utf-8",
    )
    simulation_report_path = runtime_dir / "runtime_validation_report.json"
    simulation_report_path.write_text(
        json.dumps(
            {
                "recording_usda": str(recording),
                "scene_usd": str(scene),
                "physics_usd": str(physics_usd),
                "scene_info": {"body_prim_path": "/World/Body"},
                "runtime_asset_provenance": {
                    "published_asset": {
                        "path": str(physics_usd),
                        "asset_sha256": runner._file_digest(physics_usd),
                    }
                },
            }
        ),
        encoding="utf-8",
    )

    def fake_render_physics_frames(
        *,
        recording_usd: Path,
        output_dir: Path,
        raw_dir: Path,
        usd_cli_session: object,
        resolution: str = "640x480",
        focus_prim_path: str | None = None,
        timeout_seconds: float = 300.0,
    ) -> tuple[list[str], dict[str, Any]]:
        assert recording_usd == recording.resolve()
        assert raw_dir == run_dir / "raw"
        assert resolution == "640x480"
        assert focus_prim_path == "/World/Body"
        assert timeout_seconds == 300.0
        output_dir.mkdir(parents=True)
        frame = output_dir / "ovrtx_frame.png"
        Image.new("RGB", (8, 8), color=(64, 96, 128)).save(frame)
        return [str(frame)], {
            "schema_version": "content-agent-workflows.usd-cli-physics-render.v1",
            "scene_backend": "usd-cli",
            "renderer": "ovrtx",
            "resolved_renderer": "remote",
            "transport": "remote",
            "status": "success",
            "session_id": "physics-render-session",
            "recording_usd": str(recording.resolve()),
            "probe": {
                "schema_version": "usd-cli.render-probe.v1",
                "capabilities": ["appearance.clear.v1"],
                "ready": True,
                "engine": "ovrtx",
                "resolved_renderer": "remote",
                "transport": "remote",
                "backends": [
                    {
                        "url": "https://ovrtx.example.test/",
                        "engine": "ovrtx",
                        "protocol_version": 2,
                        "status": "ready",
                    }
                ],
                "render": {
                    "sha256": "probe-digest",
                    "width": 64,
                    "height": 64,
                    "size_bytes": 123,
                    "backend": "remote",
                },
            },
            "render_response": {
                "summary": {
                    "camera": "/World/ValidationCamera",
                    "res": "640x480",
                    "backend": "remote",
                }
            },
            "frame_paths": [str(frame)],
            "frame_renderer_identities": [
                {
                    "endpoint": "https://ovrtx.example.test",
                    "engine": "ovrtx",
                    "protocol_version": 2,
                    "status": "ready",
                }
            ],
        }

    monkeypatch.setattr(
        usd_cli_ops,
        "render_physics_frames",
        fake_render_physics_frames,
    )

    frame_paths = runner._render_physics_validation_frames(
        config=PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=tmp_path / "asset.usda",
            output_dir=run_dir,
        ),
        run_dir=run_dir,
        session_id=None,
        simulation_report_path=simulation_report_path,
        iteration=3,
        trace_writer=TraceWriter(run_dir),
        usd_cli_session=runner.WorkflowUsdCliSession(
            project_dir=run_dir,
            session_id="physics-render-test-session",
            route=SimpleNamespace(),
            workflow="physics.apply",
        ),
    )

    assert len(frame_paths) == 1
    frame_path = Path(frame_paths[0])
    receipt_path = raw_dir / "physics_render_frame_receipt_3.json"
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    assert str(recording_dependency.resolve()) in {
        item["path"] for item in receipt["render_input_bundle"]["files"]
    }
    assert receipt["session_id"] == "physics-render-session"
    assert receipt["render_response"]["scene_backend"] == "usd-cli"
    assert receipt["render_response"]["renderer"] == "ovrtx"
    assert receipt["render_response"]["resolved_renderer"] == "remote"
    assert receipt["render_response"]["transport"] == "remote"
    assert receipt["render_response"]["ovrtx_probe"]["ready"] is True
    assert receipt["frames"][0]["local_frame_path"] == str(frame_path)
    assert receipt["frames"][0]["frame_sha256"] == runner._file_digest(frame_path)
    camera_path = Path(receipt["frames"][0]["local_camera_path"])
    assert receipt["frames"][0]["camera"]["camera_path"] == ("/World/ValidationCamera")
    assert camera_path.is_file()

    validation_path = run_dir / "validation_evidence.json"
    validation_path.write_text('{"sim_ready_status":"pass"}\n', encoding="utf-8")
    attestation = runner._capture_physics_visual_evidence_attestation(
        run_dir=run_dir,
        validation_path=validation_path,
        runtime_report_path=simulation_report_path,
        rendered_frames=frame_paths,
        render_receipt_path=receipt_path,
    )
    receipt["render_response"]["renderer"] = "usdrecord"
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")
    with pytest.raises(RuntimeError, match="does not identify OVRTX"):
        runner._capture_physics_visual_evidence_attestation(
            run_dir=run_dir,
            validation_path=validation_path,
            runtime_report_path=simulation_report_path,
            rendered_frames=frame_paths,
            render_receipt_path=receipt_path,
        )
    receipt["render_response"]["renderer"] = "ovrtx"
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")

    response_path = Path(receipt["response_artifact"]["path"])
    response_payload = json.loads(response_path.read_text(encoding="utf-8"))
    response_payload["frame_renderer_identities"][0]["endpoint"] = (
        "https://unverified.example.test"
    )
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")
    with pytest.raises(RuntimeError, match="frame renderer identity"):
        runner._capture_physics_visual_evidence_attestation(
            run_dir=run_dir,
            validation_path=validation_path,
            runtime_report_path=simulation_report_path,
            rendered_frames=frame_paths,
            render_receipt_path=receipt_path,
        )
    response_payload["frame_renderer_identities"][0]["endpoint"] = (
        "https://ovrtx.example.test"
    )
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")

    response_payload["transport"] = "local"
    receipt["render_response"]["transport"] = "local"
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")
    with pytest.raises(RuntimeError, match="contradicts its OVRTX probe"):
        runner._capture_physics_visual_evidence_attestation(
            run_dir=run_dir,
            validation_path=validation_path,
            runtime_report_path=simulation_report_path,
            rendered_frames=frame_paths,
            render_receipt_path=receipt_path,
        )
    response_payload["transport"] = "remote"
    receipt["render_response"]["transport"] = "remote"

    response_payload["render_response"]["summary"]["backend"] = "usdrecord"
    receipt["render_response"]["usd_cli_render_summary"]["backend"] = "usdrecord"
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")
    with pytest.raises(RuntimeError, match="render summary contradicts"):
        runner._capture_physics_visual_evidence_attestation(
            run_dir=run_dir,
            validation_path=validation_path,
            runtime_report_path=simulation_report_path,
            rendered_frames=frame_paths,
            render_receipt_path=receipt_path,
        )
    response_payload["render_response"]["summary"]["backend"] = "remote"
    receipt["render_response"]["usd_cli_render_summary"]["backend"] = "remote"
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")

    response_payload["schema_version"] = "attacker-controlled-schema.v1"
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")
    with pytest.raises(RuntimeError, match="not bound to a usd-cli render response"):
        runner._capture_physics_visual_evidence_attestation(
            run_dir=run_dir,
            validation_path=validation_path,
            runtime_report_path=simulation_report_path,
            rendered_frames=frame_paths,
            render_receipt_path=receipt_path,
        )
    response_payload["schema_version"] = (
        "content-agent-workflows.usd-cli-physics-render.v1"
    )
    response_path.write_text(json.dumps(response_payload), encoding="utf-8")
    receipt["response_artifact"]["sha256"] = runner._file_digest(response_path)
    receipt_path.write_text(json.dumps(receipt), encoding="utf-8")

    attestation = runner._capture_physics_visual_evidence_attestation(
        run_dir=run_dir,
        validation_path=validation_path,
        runtime_report_path=simulation_report_path,
        rendered_frames=frame_paths,
        render_receipt_path=receipt_path,
    )
    dependency_bytes = recording_dependency.read_bytes()
    recording_dependency.write_bytes(dependency_bytes + b"tampered")
    with pytest.raises(RuntimeError, match="digest does not match"):
        runner._verify_physics_visual_evidence_attestation(
            run_dir=run_dir,
            attestation=attestation,
        )
    recording_dependency.write_bytes(dependency_bytes)
    frame_path.write_bytes(frame_path.read_bytes() + b"tampered")
    with pytest.raises(RuntimeError, match="digest does not match"):
        runner._verify_physics_visual_evidence_attestation(
            run_dir=run_dir,
            attestation=attestation,
        )


def test_physics_inspection_pin_rejects_child_packet_repoint(
    tmp_path: Path,
    physics_packet_writer: Any,
) -> None:
    from world_understanding.functions.physics.physics_topology import sha256_file

    source_usd = tmp_path / "asset.usda"
    inspection_usd = tmp_path / "asset.optimized.usda"
    attacker_usd = tmp_path / "attacker.usda"
    source_usd.write_text("#usda 1.0\n", encoding="utf-8")
    inspection_usd.write_text(
        '#usda 1.0\ndef Xform "World" {}\n',
        encoding="utf-8",
    )
    attacker_usd.write_text('#usda 1.0\ndef Xform "Other" {}\n', encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    packet = physics_packet_writer(
        run_dir,
        source_usd,
        inspection_usd=inspection_usd,
    )
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=source_usd,
    )
    pin = runner._physics_inspection_pin_from_packet(config, packet)
    packet["inspection_usd_path"] = str(attacker_usd)
    packet["inspection_asset_sha256"] = runner._file_digest(attacker_usd)
    packet["inspection_bundle_sha256"] = runner._physics_inspection_bundle_digest(
        attacker_usd
    )
    packet["inspection_source_digest"] = sha256_file(attacker_usd)
    (run_dir / "raw" / "physics_run_packet.json").write_text(
        json.dumps(packet),
        encoding="utf-8",
    )

    with pytest.raises(RuntimeError, match="provenance changed"):
        runner._verify_physics_inspection_pin(
            config=config,
            run_dir=run_dir,
            pin=pin,
        )


def test_physics_inspection_pin_accepts_caller_owned_hardlinked_source(
    tmp_path: Path,
    physics_packet_writer: Any,
) -> None:
    original = tmp_path / "cached.usda"
    source_usd = tmp_path / "asset.usda"
    original.write_text('#usda 1.0\ndef Xform "World" {}\n', encoding="utf-8")
    os.link(original, source_usd)
    run_dir = tmp_path / "physics-run"
    packet = physics_packet_writer(run_dir, source_usd)
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=source_usd,
    )

    pin = runner._physics_inspection_pin_from_packet(config, packet)

    assert pin.path_space == "source"
    assert pin.inspection_usd_path == source_usd.resolve()


def test_physics_inspection_pin_rejects_sidecar_dependency_mutation(
    tmp_path: Path,
    physics_packet_writer: Any,
) -> None:
    from world_understanding.functions.graphics.so_export import portable_sidecar_name

    source_usd = tmp_path / "asset.usda"
    inspection_usd = tmp_path / "asset.optimized.usda"
    source_usd.write_text("#usda 1.0\n", encoding="utf-8")
    inspection_usd.write_text(
        '#usda 1.0\ndef Xform "World" {}\n',
        encoding="utf-8",
    )
    sidecar = inspection_usd.parent / portable_sidecar_name(inspection_usd)
    sidecar.mkdir()
    dependency = sidecar / "texture.png"
    dependency.write_bytes(b"trusted texture")
    run_dir = tmp_path / "physics-run"
    packet = physics_packet_writer(
        run_dir,
        source_usd,
        inspection_usd=inspection_usd,
    )
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=source_usd,
    )
    pin = runner._physics_inspection_pin_from_packet(config, packet)

    dependency.write_bytes(b"child replacement")

    with pytest.raises(RuntimeError, match="inspection bundle changed"):
        runner._verify_physics_inspection_pin(
            config=config,
            run_dir=run_dir,
            pin=pin,
        )


def test_run_child_agent_uses_prefixed_bridge_artifacts(
    tmp_path: Path, monkeypatch: Any
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    child_output = run_dir / "child-output.log"
    child_final = run_dir / "raw" / "post_apply_visual_quality.json"
    prompt_image = run_dir / "final_renders" / "final_oblique.png"
    prompt_image.parent.mkdir()
    Image.new("RGB", (8, 8), "green").save(prompt_image)
    original_prompt_bytes = prompt_image.read_bytes()
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
    )

    staged_paths: dict[str, Path] = {}
    staged_request_paths: list[Path] = []
    staged_prompt_bytes: list[bytes] = []
    parent_token = "scoped-parent-token"
    parent_env = {
        runner.PARENT_USD_CLI_TOKEN_ENV: parent_token,
        runner.PARENT_USD_CLI_SERVER_URL_ENV: "http://127.0.0.1:4567",
        runner.PARENT_USD_CLI_MANAGED_ENV: "1",
        runner.USD_CLI_EXTERNAL_LIFECYCLE_ENV: "1",
        "USD_CLI_NO_DAEMON": "1",
    }
    imported_redaction_values: list[tuple[str, ...]] = []

    monkeypatch.setattr(
        runner,
        "_codex_bridge_env",
        lambda *_args, **_kwargs: parent_env,
    )
    import_staged_bridge_outputs = runner._import_staged_bridge_outputs

    def capture_imported_redaction_values(**kwargs: object) -> None:
        redaction_values = kwargs["redaction_values"]
        assert isinstance(redaction_values, tuple)
        imported_redaction_values.append(redaction_values)
        import_staged_bridge_outputs(**kwargs)

    def fake_subprocess_with_timeout(**kwargs: object) -> int:
        child_env = kwargs["env"]
        assert isinstance(child_env, dict)
        assert runner.PARENT_USD_CLI_TOKEN_ENV not in child_env
        proxy_url = child_env[runner.PARENT_USD_CLI_AUTH_PROXY_ENV]
        assert isinstance(proxy_url, str)
        assert proxy_url.startswith("http://127.0.0.1:")
        command = kwargs["command"]
        assert isinstance(command, list)
        staged_request_path = Path(command[-1])
        staged_request_paths.append(staged_request_path)
        request = json.loads(staged_request_path.read_text(encoding="utf-8"))
        staged_prompt_path = Path(request["prompt_image_inputs"][0]["path"])
        assert staged_prompt_path.parent == staged_request_path.parent
        # Tamper with the live prompt image after staging to prove the parent
        # used its own staged copy. Overwrite in place rather than planting a
        # symlink, which the run-directory guard now rejects outright and which
        # this test does not otherwise exercise.
        prompt_image.write_bytes(b"tampered-after-staging")
        staged_prompt_bytes.append(staged_prompt_path.read_bytes())
        for name, payload in (
            ("child_final_path", "{}"),
            ("items_path", "[]"),
            ("result_path", "{}"),
        ):
            path = Path(request[name])
            staged_paths[name] = path
            path.write_text(payload, encoding="utf-8")
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )
    monkeypatch.setattr(
        runner,
        "_import_staged_bridge_outputs",
        capture_imported_redaction_values,
    )

    returncode = _run_child_agent(
        config=config,
        prompt="Validate final render.",
        run_dir=run_dir,
        child_output_path=child_output,
        child_final_path=child_final,
        prompt_image_inputs=[{"label": "Current render", "path": str(prompt_image)}],
        bridge_artifact_prefix="post apply vqa",
    )

    assert returncode == 0
    assert not (run_dir / "raw" / "codex_request.json").exists()
    sdk_request = json.loads(
        (run_dir / "raw" / "post_apply_vqa_request.json").read_text(encoding="utf-8")
    )
    assert sdk_request["items_path"] == str(
        run_dir / "raw" / "post_apply_vqa_items.json"
    )
    assert sdk_request["result_path"] == str(
        run_dir / "raw" / "post_apply_vqa_result.json"
    )
    assert sdk_request["prompt_image_inputs"] == [
        {"label": "Current render", "path": str(prompt_image)}
    ]
    assert (run_dir / "raw" / "post_apply_vqa_items.json").read_text(
        encoding="utf-8"
    ) == "[]"
    assert (run_dir / "raw" / "post_apply_vqa_result.json").read_text(
        encoding="utf-8"
    ) == "{}"
    assert child_final.read_text(encoding="utf-8") == "{}"
    assert all(not path.parent.exists() for path in staged_paths.values())
    assert all(not path.parent.exists() for path in staged_request_paths)
    assert staged_prompt_bytes == [original_prompt_bytes]
    assert imported_redaction_values == [(parent_token,)]


def test_codex_child_auth_proxy_keeps_parent_token_out_of_child_environment() -> None:
    requests: list[tuple[str, bytes]] = []

    class UpstreamHandler(BaseHTTPRequestHandler):
        def do_POST(self) -> None:  # noqa: N802 - stdlib handler API
            body = self.rfile.read(int(self.headers["Content-Length"]))
            requests.append((self.headers["x-usd-cli-token"], body))
            payload = b'{"ok":true}'
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)

        def log_message(self, *_args: object) -> None:
            return

    upstream = ThreadingHTTPServer(("127.0.0.1", 0), UpstreamHandler)
    upstream_thread = threading.Thread(target=upstream.serve_forever, daemon=True)
    upstream_thread.start()
    upstream_url = f"http://127.0.0.1:{upstream.server_address[1]}"
    parent_env = {
        runner.PARENT_USD_CLI_TOKEN_ENV: "parent-only-token",
        runner.PARENT_USD_CLI_SERVER_URL_ENV: upstream_url,
        runner.PARENT_USD_CLI_MANAGED_ENV: "1",
        runner.USD_CLI_EXTERNAL_LIFECYCLE_ENV: "1",
        "USD_CLI_NO_DAEMON": "1",
    }
    try:
        with runner._codex_child_bridge_environment(parent_env) as child_env:
            assert runner.PARENT_USD_CLI_TOKEN_ENV not in child_env
            proxy = urlsplit(child_env[runner.PARENT_USD_CLI_AUTH_PROXY_ENV])
            connection = http.client.HTTPConnection(proxy.hostname, proxy.port)
            connection.request(
                "POST",
                f"{upstream_url}/cmd",
                body=b'{"command":"snapshot"}',
                headers={
                    "Content-Type": "application/json",
                    "x-usd-cli-token": "child-supplied-token",
                },
            )
            response = connection.getresponse()
            assert response.status == 200
            assert response.read() == b'{"ok":true}'
            connection.close()

            rejected = http.client.HTTPConnection(proxy.hostname, proxy.port)
            rejected.request(
                "POST",
                "http://127.0.0.1:1/cmd",
                body=b"{}",
                headers={"Content-Type": "application/json"},
            )
            rejected_response = rejected.getresponse()
            assert rejected_response.status == 403
            rejected_response.read()
            rejected.close()
    finally:
        upstream.shutdown()
        upstream.server_close()
        upstream_thread.join(timeout=5)

    assert requests == [
        ("parent-only-token", b'{"command":"snapshot"}'),
    ]


