def test_find_claude_cli_binary_verifies_authenticated_status(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    calls: list[tuple[list[str], dict[str, object]]] = []

    monkeypatch.setattr(runner.shutil, "which", lambda _name: "/opt/claude")

    def fake_run(
        command: list[str], **kwargs: object
    ) -> subprocess.CompletedProcess[str]:
        calls.append((command, kwargs))
        return subprocess.CompletedProcess(
            command,
            0,
            stdout=json.dumps({"loggedIn": True, "email": "not-persisted@example.com"}),
            stderr="",
        )

    monkeypatch.setattr(runner.subprocess, "run", fake_run)

    assert runner._find_claude_cli_binary() == "/opt/claude"
    assert calls[0][0] == ["/opt/claude", "auth", "status", "--json"]
    assert calls[0][1]["timeout"] == 10


@pytest.mark.parametrize(
    ("returncode", "stdout", "message"),
    (
        (0, '{"loggedIn": false}', "not authenticated"),
        (1, '{"loggedIn": true}', "not authenticated"),
        (0, "not-json", "invalid authentication status"),
    ),
)
def test_find_claude_cli_binary_fails_closed_on_unusable_auth_status(
    monkeypatch: pytest.MonkeyPatch,
    returncode: int,
    stdout: str,
    message: str,
) -> None:
    monkeypatch.setattr(runner.shutil, "which", lambda _name: "/opt/claude")
    monkeypatch.setattr(
        runner.subprocess,
        "run",
        lambda command, **_kwargs: subprocess.CompletedProcess(
            command,
            returncode,
            stdout=stdout,
            stderr="private provider diagnostic",
        ),
    )

    with pytest.raises(RuntimeError, match=message):
        runner._find_claude_cli_binary()


def test_run_child_agent_claude_cli_execution_mode(
    tmp_path: Path, monkeypatch: Any
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    reference_image = tmp_path / "reference.png"
    reference_image.write_bytes(b"reference-image")
    child_output = run_dir / "child-output.log"
    child_final = run_dir / "child-final.md"
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[reference_image],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        runner="claude",
        claude_execution_mode="cli",
        model="claude-sonnet-5",
        model_reasoning_effort="high",
        claude_permission_mode="bypassPermissions",
        child_timeout_seconds=120,
    )
    monkeypatch.setattr(runner, "_find_claude_cli_binary", lambda: "/usr/bin/claude")

    call: dict[str, object] = {}

    def fake_subprocess_with_timeout(**kwargs: object) -> int:
        call.update(kwargs)
        log_stream = kwargs["log_stream"]
        log_stream.write(
            json.dumps(
                {
                    "type": "result",
                    "result": "ignored structured response",
                    "structured_output": {"status": "pass"},
                    "usage": {"input_tokens": 12, "output_tokens": 34},
                }
            )
            + "\n"
        )
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )

    returncode = _run_child_agent(
        config=config,
        prompt="Inspect the asset.",
        run_dir=run_dir,
        child_output_path=child_output,
        child_final_path=child_final,
        output_schema={"type": "object", "required": ["status"]},
    )

    assert returncode == 0
    command = call["command"]
    assert isinstance(command, list)
    assert command[0] == "/usr/bin/claude"
    assert "--print" in command
    assert command[command.index("--output-format") + 1] == "json"
    assert command[command.index("--permission-mode") + 1] == "bypassPermissions"
    assert "--dangerously-skip-permissions" in command
    assert command[command.index("--model") + 1] == "claude-sonnet-5"
    assert command[command.index("--effort") + 1] == "high"
    assert command[command.index("--input-format") + 1] == "text"
    assert json.loads(command[command.index("--json-schema") + 1]) == {
        "type": "object",
        "required": ["status"],
    }
    assert "workbench_watchdog" not in call
    # The prompt is sent via stdin rather than as a positional argument, so
    # an unbounded --additional-instructions-file can't overflow argv (E2BIG).
    assert "Inspect the asset." not in command
    assert call["stdin_input"].startswith(
        "/content-workflow-trusted:content-workflow-material Inspect the asset."
    )
    staged_reference = run_dir / "raw" / "claude_reference_images" / "reference-000.png"
    assert staged_reference.read_bytes() == b"reference-image"
    assert str(staged_reference) in call["stdin_input"]
    assert str(reference_image) not in call["stdin_input"]
    assert "use the Read tool" in call["stdin_input"]
    # bypassPermissions has no interactive grant boundary, so it restricts the
    # actual surface to read-only tools plus mandatory-sandboxed Bash.
    allowed_tools_value = command[command.index("--allowedTools") + 1]
    tools_value = command[command.index("--tools") + 1]
    allowed_tools = allowed_tools_value.split(",")
    available_tools = tools_value.split(",")
    assert "Bash" in available_tools
    assert "Bash" not in allowed_tools
    assert {"Write", "Edit", "MultiEdit"}.isdisjoint(available_tools)
    assert "Monitor" not in available_tools
    settings = json.loads(command[command.index("--settings") + 1])
    assert settings["sandbox"] == {
        "enabled": True,
        "failIfUnavailable": True,
        "autoAllowBashIfSandboxed": True,
        "allowUnsandboxedCommands": False,
        "network": {"allowedDomains": ["127.0.0.1"]},
    }
    policy_hook = settings["hooks"]["PreToolUse"][0]
    assert policy_hook["matcher"] == "Bash"
    assert "--python-policy-hook" in policy_hook["hooks"][0]["command"]
    assert command[command.index("--setting-sources") + 1] == ""
    assert command[command.index("--plugin-dir") + 1] == str(
        run_dir.resolve() / ".claude"
    )
    assert (
        json.loads(
            (run_dir / ".claude" / ".claude-plugin" / "plugin.json").read_text(
                encoding="utf-8"
            )
        )
        == runner.CLAUDE_CLI_TRUSTED_SKILLS_PLUGIN_MANIFEST
    )

    add_dirs = {
        command[index + 1]
        for index, value in enumerate(command)
        if value == "--add-dir"
    }
    # Claude treats every --add-dir root as writable. Input parents stay out of
    # that list and are read through sandboxed Bash instead.
    assert add_dirs == {str(run_dir.resolve())}
    assert str(config.materials_yaml.parent) not in add_dirs
    assert str(config.materials_usd.parent) not in add_dirs

    assert json.loads(child_final.read_text(encoding="utf-8")) == {"status": "pass"}
    result_payload = json.loads(
        (run_dir / "raw" / "claude_result.json").read_text(encoding="utf-8")
    )
    assert result_payload["usage"]["input_tokens"] == 12


@pytest.mark.parametrize("suffix", [".png", ".bmp", ".tif", ".tiff"])
def test_claude_cli_tool_free_turn_attaches_images_without_read_tool(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    suffix: str,
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    reference_image = tmp_path / f"reference{suffix}"
    Image.new("RGB", (8, 8), "blue").save(reference_image)
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[reference_image],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        runner="claude",
        claude_execution_mode="cli",
    )
    monkeypatch.setattr(runner, "_find_claude_cli_binary", lambda: "/usr/bin/claude")
    call: dict[str, object] = {}

    def fake_subprocess_with_timeout(**kwargs: object) -> int:
        call.update(kwargs)
        kwargs["log_stream"].write(
            json.dumps({"type": "result", "result": "{}"}) + "\n"
        )
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )
    returncode = _run_child_agent(
        config=config,
        prompt="Review only the attached evidence.",
        run_dir=run_dir,
        child_output_path=run_dir / "child-output.log",
        child_final_path=run_dir / "child-final.json",
        bridge_artifact_prefix="tool_free_review",
        tools_disabled=True,
    )

    assert returncode == 0
    command = call["command"]
    assert isinstance(command, list)
    assert command[command.index("--output-format") + 1] == "stream-json"
    assert command[command.index("--input-format") + 1] == "stream-json"
    assert "--verbose" in command
    assert command[command.index("--tools") + 1] == ""
    assert command[command.index("--allowedTools") + 1] == ""
    settings = json.loads(command[command.index("--settings") + 1])
    assert settings["sandbox"]["enabled"] is True
    assert settings["sandbox"]["failIfUnavailable"] is True
    stdin_message = json.loads(str(call["stdin_input"]))
    content = stdin_message["message"]["content"]
    assert content[0]["text"] == (
        "/content-workflow-trusted:content-workflow-material "
        "Review only the attached evidence."
    )
    assert content[2]["type"] == "image"
    assert content[2]["source"]["media_type"] == "image/png"
    assert content[2]["source"]["data"]
    assert Path(content[1]["text"].rsplit(": ", maxsplit=1)[-1]).suffix == ".png"


@pytest.mark.parametrize(
    ("child_runner", "claude_execution_mode"),
    [
        ("codex", "sdk"),
        ("claude", "sdk"),
        ("claude", "cli"),
    ],
)
def test_child_terminal_detection_ignores_stale_scene_state_outside_scene_runs(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    child_runner: str,
    claude_execution_mode: str,
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    (run_dir / "large_scene_run.json").write_text(
        json.dumps(
            {
                "current_phase": None,
                "failed_at": None,
                "phases": {
                    "decomposition": {"status": "completed"},
                    "asset_task_processing": {"status": "completed"},
                    "collection": {"status": "completed"},
                },
            }
        ),
        encoding="utf-8",
    )
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        runner=child_runner,
        claude_execution_mode=claude_execution_mode,
    )
    monkeypatch.setattr(runner, "_find_claude_cli_binary", lambda: "/usr/bin/claude")
    detectors: list[object] = []

    def fake_subprocess_with_timeout(**kwargs: object) -> int:
        detector = kwargs["terminal_success_detector"]
        detectors.append(detector)
        if not callable(detector):
            return 17
        summary = detector(run_dir)
        assert summary is not None
        assert summary.startswith("large-scene run completed")
        return 0

    monkeypatch.setattr(
        runner,
        "_run_subprocess_with_timeout",
        fake_subprocess_with_timeout,
    )
    child_output = run_dir / "child-output.log"
    child_final = run_dir / "child-final.md"

    non_scene_returncode = _run_child_agent(
        config=config,
        prompt="Run a material child turn.",
        run_dir=run_dir,
        child_output_path=child_output,
        child_final_path=child_final,
    )
    scene_returncode = _run_child_agent(
        config=config,
        prompt="Run a scene child turn.",
        run_dir=run_dir,
        child_output_path=child_output,
        child_final_path=child_final,
        bridge_artifact_prefix="scene_run",
    )

    assert non_scene_returncode == 17
    assert detectors[0] is None
    assert scene_returncode == 0
    assert callable(detectors[1])


def test_claude_cli_env_drops_untrusted_runtime_state_and_applies_telemetry_last(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    for key, value in {
        "TRACEPARENT": "ambient-trace",
        "TRACESTATE": "ambient-state",
        "USD_CLI_AGENT": "ambient-agent",
        "USD_CLI_TEL_FILE": "/ambient/telemetry.jsonl",
        "PYTHONHOME": "/ambient/python",
    }.items():
        monkeypatch.setenv(key, value)
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        claude_config={
            "env": {
                **{
                    name: "configured-renderer-secret"
                    for name in runner._USD_CLI_CREDENTIAL_ENV_NAMES
                },
                "SAFE_SETTING": "configured",
                "safe_setting": "configured",
                "TRACEPARENT": "configured-trace",
                "TRACESTATE": "configured-state",
                "USD_CLI_AGENT": "configured-agent",
                "USD_CLI_REMOTE_RENDER_STAGING_ROOT": "/configured/staging",
                "USD_CLI_TEL_FILE": "/configured/telemetry.jsonl",
                "USD_CLI_TEL_DISABLED_EXTRA": "1",
                "CONTENT_WORKFLOW_USD_CLI_SERVER_URL": "http://127.0.0.1:1",
                "CONTENT_WORKFLOW_USD_CLI_SESSION_ID": "configured-session",
                "CONTENT_WORKFLOW_CONTROLLED_ARTIFACT_ROOT": "/configured/root",
                "content_workflow_controlled_artifact_root": "/configured/lower-root",
                "XDG_CACHE_HOME": "/configured/cache",
                "WARP_CACHE_PATH": "/configured/warp",
                "PYTHONHOME": "/configured/python",
                "pythonhome": "/configured/lower-python",
                "PYTHON_FUTURE_HOOK": "configured-python-hook",
                "oVrTx_ApI_kEy": "configured-mixed-case-secret",
            }
        },
    )
    trusted_telemetry = {
        "TRACEPARENT": "wrapper-trace",
        "USD_CLI_TEL_FILE": str(run_dir / "raw" / "telemetry.jsonl"),
    }
    monkeypatch.setattr(
        runner,
        "_child_telemetry_env",
        lambda _config, _run_dir, **_kwargs: dict(trusted_telemetry),
    )

    env = runner._claude_cli_execution_env(config, run_dir)

    assert env["SAFE_SETTING"] == "configured"
    assert env["TRACEPARENT"] == "wrapper-trace"
    assert env["USD_CLI_TEL_FILE"] == trusted_telemetry["USD_CLI_TEL_FILE"]
    assert "TRACESTATE" not in env
    assert "USD_CLI_AGENT" not in env
    assert env[runner.USD_CLI_REMOTE_RENDER_STAGING_ROOT_ENV] == str(
        runner._usd_cli_remote_render_staging_root(run_dir.resolve())
    )
    assert env["XDG_CACHE_HOME"] == str(run_dir.resolve() / ".cache")
    assert env["WARP_CACHE_PATH"] == str(run_dir.resolve() / ".cache" / "warp")
    assert "CONTENT_WORKFLOW_USD_CLI_SERVER_URL" not in env
    assert "CONTENT_WORKFLOW_USD_CLI_SESSION_ID" not in env
    assert "USD_CLI_TEL_DISABLED_EXTRA" not in env
    assert "PYTHONHOME" not in env
    assert "PYTHON_FUTURE_HOOK" not in env
    if os.name == "nt":
        assert "pythonhome" not in env
        assert "oVrTx_ApI_kEy" not in env
        assert "content_workflow_controlled_artifact_root" not in env
        assert sum(key.upper() == "SAFE_SETTING" for key in env) == 1
    else:
        assert env["pythonhome"] == "/configured/lower-python"
        assert env["oVrTx_ApI_kEy"] == "configured-mixed-case-secret"
        assert env["content_workflow_controlled_artifact_root"] == (
            "/configured/lower-root"
        )
    assert all(name not in env for name in runner._USD_CLI_CREDENTIAL_ENV_NAMES)
    assert env["PYTHONPATH"] != "/configured/python"
    assert env["PYTHONNOUSERSITE"] == "1"
    assert env["PYTHONSAFEPATH"] == "1"
    if os.name == "nt":
        assert env[runner.CONTROLLED_ARTIFACT_ROOT_ENV] == str(run_dir.resolve())
    else:
        assert runner.CONTROLLED_ARTIFACT_ROOT_ENV not in env

    sdk_env = runner._claude_sdk_execution_env(config, run_dir)
    assert "SAFE_SETTING" not in sdk_env
    assert sdk_env["TRACEPARENT"] == "wrapper-trace"
    assert sdk_env["USD_CLI_TEL_FILE"] == trusted_telemetry["USD_CLI_TEL_FILE"]
    assert "TRACESTATE" not in sdk_env
    assert "USD_CLI_AGENT" not in sdk_env
    assert sdk_env[runner.USD_CLI_REMOTE_RENDER_STAGING_ROOT_ENV] == str(
        runner._usd_cli_remote_render_staging_root(run_dir.resolve())
    )
    assert "PYTHONHOME" not in sdk_env
    if os.name == "nt":
        assert sdk_env[runner.CONTROLLED_ARTIFACT_ROOT_ENV] == str(run_dir.resolve())
    else:
        assert runner.CONTROLLED_ARTIFACT_ROOT_ENV not in sdk_env
    assert all(name not in sdk_env for name in runner._USD_CLI_CREDENTIAL_ENV_NAMES)


def test_claude_sdk_env_injects_the_bound_parent_usd_cli_session(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True, mode=0o700)
    os.chmod(run_dir, 0o700)
    os.chmod(raw_dir, 0o700)
    identity_path = raw_dir / "parent_usd_cli_session_test.json"
    identity_path.write_text('{"schema_version":"test"}\n', encoding="utf-8")
    os.chmod(identity_path, 0o600)
    identity_sha256 = hashlib.sha256(identity_path.read_bytes()).hexdigest()

    class AssetClaudeConfig(runner.AssetCompositionChildConfig):
        repo_root = tmp_path
        claude_config: dict[str, object] = {"env": {"SAFE_SETTING": "ignored"}}
        parent_usd_cli_session_identity = identity_path
        parent_usd_cli_session_identity_sha256 = identity_sha256

    monkeypatch.setattr(
        runner,
        "_child_telemetry_env",
        lambda *_args, **_kwargs: {},
    )
    monkeypatch.setattr(
        runner.ParentUsdCliSessionIdentity,
        "model_validate_json",
        classmethod(
            lambda _cls, _payload: SimpleNamespace(
                run_dir=str(run_dir.resolve()),
                launch_id="test",
            )
        ),
    )
    monkeypatch.setattr(
        runner,
        "verify_live_parent_usd_cli_daemon",
        lambda _identity: runner.ParentUsdCliConnection(
            server_url="http://127.0.0.1:43210",
            session_id="parent-session",
            authentication_token=SecretStr("parent-token"),
        ),
    )

    env = runner._claude_sdk_execution_env(AssetClaudeConfig(), run_dir)

    assert env["CONTENT_WORKFLOW_PARENT_USD_CLI_SESSION_IDENTITY"] == str(identity_path)
    assert (
        env["CONTENT_WORKFLOW_PARENT_USD_CLI_SESSION_IDENTITY_SHA256"]
        == identity_sha256
    )
    assert env["CONTENT_WORKFLOW_PARENT_USD_CLI_MANAGED"] == "1"
    assert env["USD_CLI_LIFECYCLE_EXTERNALLY_OWNED"] == "1"
    assert env["USD_CLI_NO_DAEMON"] == "1"
    assert env[runner.PARENT_USD_CLI_SERVER_URL_ENV] == "http://127.0.0.1:43210"
    assert env[runner.PARENT_USD_CLI_SESSION_ID_ENV] == "parent-session"
    assert env[runner.USD_CLI_LOCAL_GPU_FORBIDDEN_ENV] == "1"
    assert env[runner.USD_CLI_ATTACHED_PROJECT_DIR_ENV] == str(run_dir.resolve())
    assert "USD_CLI_TOKEN" not in env
    assert "SAFE_SETTING" not in env


def test_parent_usd_cli_identity_uses_one_contained_read(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True, mode=0o700)
    identity_path = raw_dir / "parent_usd_cli_session_test.json"
    identity_path.write_text('{"schema_version":"test"}\n', encoding="utf-8")
    identity_sha256 = hashlib.sha256(identity_path.read_bytes()).hexdigest()

    class AssetConfig(runner.AssetCompositionChildConfig):
        repo_root = tmp_path
        parent_usd_cli_session_identity = identity_path
        parent_usd_cli_session_identity_sha256 = identity_sha256

    original_read = runner.read_contained_artifact
    capture_values: list[bool] = []

    def observe_read(
        root: str | Path,
        candidate: str | Path,
        **kwargs: Any,
    ) -> Any:
        capture_values.append(kwargs.get("capture_bytes") is True)
        return original_read(root, candidate, **kwargs)

    monkeypatch.setattr(runner, "read_contained_artifact", observe_read)
    monkeypatch.setattr(
        runner,
        "file_sha256",
        lambda _path: pytest.fail("identity validation reopened the bound path"),
    )
    monkeypatch.setattr(
        runner.ParentUsdCliSessionIdentity,
        "model_validate_json",
        classmethod(
            lambda _cls, _payload: SimpleNamespace(
                run_dir=str(run_dir.resolve()),
                launch_id="test",
            )
        ),
    )
    monkeypatch.setattr(
        runner,
        "verify_live_parent_usd_cli_daemon",
        lambda _identity: runner.ParentUsdCliConnection(
            server_url="http://127.0.0.1:43210",
            session_id="parent-session",
            authentication_token=SecretStr("parent-token"),
        ),
    )
    env: dict[str, str] = {}

    runner._inject_parent_usd_cli_session_environment(
        AssetConfig(),
        run_dir=run_dir,
        env=env,
    )

    assert capture_values == [True]
    assert env[runner.PARENT_USD_CLI_SESSION_IDENTITY_ENV] == str(identity_path)
    assert env[runner.PARENT_USD_CLI_PROXY_ALLOWED_ENV] == "1"


def test_windows_codex_parent_auth_is_provisioned_after_preflight(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True, mode=0o700)
    identity_path = raw_dir / "parent_usd_cli_session_test.json"
    identity_path.write_text('{"schema_version":"test"}\n', encoding="utf-8")
    identity_sha256 = hashlib.sha256(identity_path.read_bytes()).hexdigest()

    class AssetCodexConfig(runner.AssetCompositionChildConfig):
        repo_root = tmp_path
        runner = runner.RUNNER_CODEX
        parent_usd_cli_session_identity = identity_path
        parent_usd_cli_session_identity_sha256 = identity_sha256
        usd_cli_server_url = "http://127.0.0.1:43210"

    monkeypatch.setattr(
        runner.ParentUsdCliSessionIdentity,
        "model_validate_json",
        classmethod(
            lambda _cls, _payload: SimpleNamespace(
                run_dir=str(run_dir.resolve()),
                launch_id="test",
            )
        ),
    )
    connection = runner.ParentUsdCliConnection(
        server_url="http://127.0.0.1:43210",
        session_id="parent-session",
        authentication_token=SecretStr("scoped-parent-token"),
    )
    monkeypatch.setattr(
        runner,
        "verify_live_parent_usd_cli_daemon",
        lambda _identity: connection,
    )
    monkeypatch.setattr(
        runner,
        "_windows_codex_parent_auth_required",
        lambda _config: True,
    )
    env: dict[str, str] = {}

    runner._inject_parent_usd_cli_session_environment(
        AssetCodexConfig(),
        run_dir=run_dir,
        env=env,
    )

    assert env[runner.PARENT_USD_CLI_TOKEN_ENV] == "scoped-parent-token"
    assert env[runner.PARENT_USD_CLI_SERVER_URL_ENV] == connection.server_url
    assert "scoped-parent-token" not in repr(connection)

    AssetCodexConfig.usd_cli_server_url = "http://127.0.0.1:43211"
    with pytest.raises(RuntimeError, match="configured route disagrees"):
        runner._inject_parent_usd_cli_session_environment(
            AssetCodexConfig(),
            run_dir=run_dir,
            env={},
        )


