def test_prepare_delegated_vision_turn_stages_references_and_appends_observations(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    reference = tmp_path / "reference.png"
    reference.write_bytes(b"reference")
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    initial = run_dir / "initial.png"
    initial.write_bytes(b"render")
    (run_dir / "raw" / "material_run_packet.json").write_text(
        json.dumps(
            {
                "initial_evidence_renders": [
                    {
                        "name": "initial_oblique",
                        "image_path": str(initial),
                        "direction": "+x-y+z",
                        "ovrtx_render_mode": "rt2",
                        "ovrtx_num_sensor_updates": 32,
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[reference],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        output_dir=run_dir,
        vision_backend="test_vision_backend",
        vision_model="openai/openai/gpt-5.6-sol",
    )
    captured: dict[str, object] = {}

    def fake_observe_images(**kwargs: object) -> dict[str, object]:
        captured.update(kwargs)
        output_path = Path(kwargs["output_path"])
        result = {
            "images": kwargs["image_inputs"],
            "parse_status": "parsed",
            "observations": {"summary": "Reference and render differ."},
        }
        output_path.write_text(json.dumps(result), encoding="utf-8")
        return result

    monkeypatch.setattr(runner, "observe_images", fake_observe_images)

    prompt, driver_images = runner._prepare_delegated_vision_turn(
        config=config,
        run_dir=run_dir,
        phase="initial",
        prompt="Assign materials.",
        prompt_image_inputs=[{"label": "Initial render", "path": str(initial)}],
        trace_writer=TraceWriter(run_dir),
    )

    assert driver_images == []
    assert "Reference and render differ." in prompt
    assert "wrapper independently runs the configured VLM" in prompt
    assert "content_workflow_cli.vision_observer" not in prompt
    image_inputs = captured["image_inputs"]
    assert len(image_inputs) == 2
    assert Path(image_inputs[0]["path"]).is_relative_to(run_dir)
    assert image_inputs[1]["path"] == str(initial)
    assert captured["source_usd"] == config.usd_path
    render_metadata = captured["render_metadata"]
    assert render_metadata[str(initial.resolve())]["ovrtx_render_mode"] == "rt2"
    render_metadata_source = captured["render_metadata_source"]
    assert isinstance(render_metadata_source, Path)
    assert render_metadata_source.is_file()


