        history_path=run_dir / "raw" / "vqa_refinement_history.json",
        artifact_index_path=run_dir / "raw" / "vqa_refinement_artifact_index_2.json",
        issue_packet_path=run_dir / "raw" / "vqa_refinement_issue_packet_2.json",
