def test_build_skill_routed_material_assignment_prompt_is_compact(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    prompt = build_skill_routed_material_assignment_prompt(
        repo_root=tmp_path,
        run_dir=run_dir,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        reference_files=[tmp_path / "reference.pdf"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        preflight_packet={
            "initial_evidence_renders": [
                {"name": "initial_oblique", "image_path": str(tmp_path / "view.png")}
            ]
        },
    )
    assert "`usd-cli`" in prompt
    assert "`content-workbench`" not in prompt
    assert "`content-workflow-material`" in prompt
    assert "Do not reread those skill files" in prompt
    assert "or\n`--help` screens in this turn" in prompt
    assert "complete applicable instructions" in prompt
    assert "do not try `apply_patch` for generated JSON" in prompt
    if os.name == "nt":
        assert "through the confined Windows artifact backend" in prompt
        assert "`content-workflow-cli artifact write-json" in prompt
        assert "ConvertTo-Json" not in prompt
        assert "Get-Content -LiteralPath <relative/path.json> -Raw" in prompt
        assert "ConvertFrom-Json | Out-Null" not in prompt
        assert "`jq -nS`" not in prompt
    else:
        assert "`jq -nS`" in prompt
        assert "`jq -e . <path> >/dev/null`" in prompt
    assert '"workflow": "materials.assign"' in prompt
    assert '"asset_path":' in prompt
    assert '"reference_files":' in prompt
    assert "validation_evidence.json" in prompt
    assert "user-data/profile" in prompt
    assert "never create browser profile state" in prompt
    assert "Do not write or patch those wrapper-owned files" in prompt
    assert '"final_renders/final_turntable.gif"' in prompt
    assert '"raw/turntable_assembly_receipt.json"' in prompt
    assert "raw/material_post_apply_review.json" in prompt
    assert "hash-bound review sheets" in prompt
    assert "wrapper deterministically\n  builds hash-bound review sheets" in prompt
    assert "or write `raw/material_post_apply_review.json`" in prompt
    assert "post-apply VQA is pending" in prompt
    assert "inventory history/jobs again" in prompt
    assert (
        '"assignments.json"'
        not in prompt.split('"child_required_artifacts":', maxsplit=1)[1].split(
            '"wrapper_final_artifacts":', maxsplit=1
        )[0]
    )
    assert "Prefer material verification renders at or below 768x768" in prompt
    assert "Do not cancel its client" in prompt
    assert "Never run `snapshot -a` on a mesh-heavy" in prompt
    assert "Never issue parallel\n  shell/tool calls" in prompt
    assert "its PID is not render-progress evidence" in prompt
    assert "Do not invoke\n  `usd-cli-tel render-probe` again" in prompt
    assert "save\n  `output_usd_path` with `--flatten`" in prompt
    assert "including `--orbit 24`" in prompt
    assert "Finish one render job before submitting the\n  next" in prompt
    assert "`usd-cli-tel --json wait <job>`" in prompt
    assert "never set, unset, or override `USD_CLI_SESSION`" in prompt
    assert "never pass `--session`" in prompt
    assert "Never copy or rename checkpoint" in prompt
    assert "Never replace that\n  array with a count" in prompt
    assert 'prose such as "all candidates"' in prompt
    assert "Run a fresh visible-mesh query after the successful clear" in prompt
    assert "never\n  reuse a pre-clear proxy-only query" in prompt
    assert "does not waive their visible families" in prompt
    assert (
        "`candidate_visible_prim_count` must equal `len(candidates)` exactly" in prompt
    )
    assert "`instance_proxies`" in prompt
    assert "material_contract.staged_source.staged_usd_sha256" in prompt
    assert "do not invent a shorter request path" in " ".join(prompt.split())
    assert "every nonzero `usd-cli-tel` exit as a failed operation" in " ".join(
        prompt.split()
    )
    assert "use it as the single execution plan" in prompt
    assert "never recalculate choices" in prompt
    assert "repeat that patch-to-audit comparison" in prompt
    assert "Serialize every `usd-cli-tel` call in this session" in prompt
    assert "never launch overlapping tool calls" in prompt
    assert "`usd-cli-tel open <output_usd_path> --force-reload`" in prompt
    assert '"prim_paths":["/absolute/candidate/path"]' in prompt
    assert "A free-form `coverage` description never substitutes" in prompt
    assert "composed renderable prims" in prompt
    assert "consumer/render paths" in prompt
    assert "Never layer a second target universe" in prompt
    assert "Workbench API quick contract" not in prompt
    assert "POST /sessions/<session_id>/commands" not in prompt


def test_material_prompt_reuses_hash_pinned_preflight_candidates(
    tmp_path: Path,
) -> None:
    run_dir = tmp_path / "run"
    prompt = build_skill_routed_material_assignment_prompt(
        repo_root=tmp_path,
        run_dir=run_dir,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
        preflight_packet={
            "enabled": True,
            "wrapper_executes_decision_patch": True,
            "visible_candidates": str(run_dir / "raw" / "visible_candidate_prims.json"),
            "visible_candidates_sha256": "a" * 64,
            "candidate_visible_prim_count": 117,
            "decision_catalog": [
                {
                    "candidate_id": 0,
                    "runtime_path": "/Asset/Panel",
                    "source_path": "/Asset/Panel",
                }
            ],
            "decision_palette": [
                {
                    "name": "Steel Painted Orange",
                    "material_path": "/World/Looks/Steel_Painted_Orange",
                }
            ],
            "initial_evidence_renders": [],
        },
        usd_cli_optimization={
            "enabled": True,
            "inspection_usd_path": str(tmp_path / "inspection.usd"),
            "correspondence_path": str(tmp_path / "correspondence.json"),
        },
    )

    assert '"preflight": {' in prompt
    assert '"execution_mode": "decision_only_wrapper_execution"' in prompt
    assert "This is a decision-only turn" in prompt
    assert "Do not call tools, read files, write artifacts" in prompt
    assert "wrapper validates,\n  expands, and executes it deterministically" in prompt
    assert "appearance clearing, checkpointing, batch application" in " ".join(
        prompt.split()
    )
    assert '"child_required_artifacts": []' in prompt
    assert "content-agents.material-decision-intent.v1" in prompt
    assert "reviewed_no_override_candidate_ids" in prompt
    assert "raw/material_decision_patch.json" not in prompt
    assert (
        '"output/materialized.usda"'
        not in prompt.split('"child_required_artifacts":', maxsplit=1)[1].split(
            '"wrapper_final_artifacts":', maxsplit=1
        )[0]
    )
    assert "Write `raw/visible_candidate_prims.json` before decisions" not in prompt
    empty_schema = runner._material_decision_intent_output_schema(
        preflight_packet={
            "decision_catalog": [],
            "decision_palette": [],
        },
        clear_materials=False,
    )
    assert empty_schema["properties"]["material_assignments"]["maxItems"] == 0
    assert (
        empty_schema["properties"]["reviewed_no_override_candidate_ids"]["maxItems"]
        == 0
    )


