def test_validate_config_requires_https_for_remote_vision_endpoint(
    tmp_path: Path,
) -> None:
    usd = tmp_path / "asset.usd"
    reference = tmp_path / "reference.png"
    materials_yaml = tmp_path / "materials.yaml"
    materials_usd = tmp_path / "materials.usd"
    for path in [usd, reference, materials_yaml, materials_usd]:
        path.write_text("placeholder", encoding="utf-8")

    with pytest.raises(ValueError, match="requires HTTPS"):
        _validate_config(
            MaterialAssignConfig(
                repo_root=tmp_path,
                usd_path=usd,
                reference_images=[reference],
                materials_yaml=materials_yaml,
                materials_usd=materials_usd,
                vision_backend="test_vision_backend",
                vision_model="test_vision_model",
                vision_api_key_env="TEST_VISION_KEY",
                vision_base_url="http://vision.example.test/v1",
            )
        )

    for unsafe_url in (
        "https://user:secret@vision.example.test/v1",
        "https://vision.example.test/v1?api_key=secret",
        "https://vision.example.test/v1#secret",
    ):
        with pytest.raises(ValueError, match="Invalid --vision-base-url"):
            _validate_config(
                MaterialAssignConfig(
                    repo_root=tmp_path,
                    usd_path=usd,
                    reference_images=[reference],
                    materials_yaml=materials_yaml,
                    materials_usd=materials_usd,
                    vision_backend="test_vision_backend",
                    vision_model="test_vision_model",
                    vision_api_key_env="TEST_VISION_KEY",
                    vision_base_url=unsafe_url,
                )
            )

    _validate_config(
        MaterialAssignConfig(
            repo_root=tmp_path,
            usd_path=usd,
            reference_images=[reference],
            materials_yaml=materials_yaml,
            materials_usd=materials_usd,
            vision_backend="test_vision_backend",
            vision_model="test_vision_model",
            vision_api_key_env="TEST_VISION_KEY",
            vision_base_url="http://localhost:9000/v1",
        )
    )


@pytest.mark.parametrize("use_symlink", [False, True])
def test_validate_config_rejects_output_usd_aliasing_source(
    tmp_path: Path,
    use_symlink: bool,
) -> None:
    usd = tmp_path / "asset.usd"
    reference = tmp_path / "reference.png"
