def test_external_physics_usdc_output_is_transcoded_from_durable_usda(
    tmp_path: Path,
) -> None:
    from pxr import Usd

    run_dir = tmp_path / "run"
    run_dir.mkdir()
    durable = run_dir / "physics.usda"
    durable.write_text(
        '#usda 1.0\n\ndef Xform "World"\n{\n    int answer = 42\n}\n',
        encoding="utf-8",
    )
    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    external = tmp_path / "published" / "physics.usdc"
    external.parent.mkdir()
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=source,
        output_dir=run_dir,
        output_usd_path=external,
    )

    published = runner._publish_external_physics_output(
        config=config,
        run_dir=run_dir,
    )

    assert published == external
    assert durable.read_bytes().startswith(b"#usda 1.0")
    assert external.read_bytes().startswith(b"PXR-USDC")
    stage = Usd.Stage.Open(str(external))
    assert stage is not None
    assert stage.GetPrimAtPath("/World").GetAttribute("answer").Get() == 42


def test_external_physics_output_rejects_symlink_target(tmp_path: Path) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "physics.usda").write_text("#usda 1.0\n", encoding="utf-8")
    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    victim = tmp_path / "victim.usda"
    victim.write_text("unchanged\n", encoding="utf-8")
    external = tmp_path / "published.usda"
    external.symlink_to(victim)
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=source,
        output_dir=run_dir,
        output_usd_path=external,
    )

    with pytest.raises(ValueError, match="must resolve without traversing symlinks"):
        runner._publish_external_physics_output(config=config, run_dir=run_dir)

    assert victim.read_text(encoding="utf-8") == "unchanged\n"


