@pytest.mark.parametrize("tune", [False, True])
def test_physics_runtime_preflight_honors_auto_provision_opt_out(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    tune: bool,
) -> None:
    from content_agent_workflows import physics as physics_workflows
    from usd_core import physics_runtime

    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "run"
    tuning_runtime = tmp_path / "tuning-runtime"
    monkeypatch.setenv("WU_OVPHYSX_AUTO_PROVISION", "0")
    monkeypatch.setenv("WU_OVPHYSX_VENV_DIR", str(tuning_runtime))
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    monkeypatch.setattr(physics_runtime, "ovphysx_platform_supported", lambda: True)
    calls: list[dict[str, object]] = []

    def blocked_preflight(**kwargs: object) -> SimpleNamespace:
        calls.append(kwargs)
        return SimpleNamespace(
            passed=False,
            errors=["local OvPhysX runtime is unavailable"],
        )

    monkeypatch.setattr(
        physics_workflows,
        "preflight_ovphysx_runtime",
        blocked_preflight,
    )

    with pytest.raises(ValueError, match="runtime preflight blocked"):
        runner.run_physics_apply(
            PhysicsApplyConfig(
                repo_root=tmp_path,
                usd_path=source,
                output_dir=run_dir,
                tune=tune,
                behavior_prompt="settle without sliding" if tune else None,
            )
        )

    assert not run_dir.exists()
    expected = {"repo_root": tmp_path, "install_missing": False}
    if tune:
        expected["venv_dir"] = tuning_runtime.resolve()
    assert calls == [expected]


