def test_physics_runner_preflights_configured_remote_executor_before_run_creation(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A remote-only host must not provision an unused local OvPhysX venv."""

    from content_agent_workflows import physics as physics_workflows
    from usd_core import physics_runtime

    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "run"
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    monkeypatch.setattr(physics_runtime, "ovphysx_platform_supported", lambda: False)
    observed_render_configs: list[dict[str, object]] = []

    def resolve_remote(
        render_config: dict[str, object], **_kwargs: object
    ) -> dict[str, object]:
        observed_render_configs.append(render_config)
        return {
            "base_url": "https://ovrtx.example.test",
            "api_key": "remote-credential",
        }

    monkeypatch.setattr(
        physics_runtime, "resolve_remote_physics_backend", resolve_remote
    )
    monkeypatch.setattr(
        physics_workflows,
        "preflight_ovphysx_runtime",
        lambda **_kwargs: pytest.fail(
            "remote execution must not preflight local OvPhysX"
        ),
    )

    class StopBeforeRunCreation(Exception):
        pass

    monkeypatch.setattr(
        runner,
        "_prepare_run_dir",
        lambda _config: (_ for _ in ()).throw(StopBeforeRunCreation()),
    )
    monkeypatch.setattr(
        runner,
        "_effective_usd_cli_render_config",
        lambda root: {
            "remote_url": "https://ovrtx.example.test",
            "remote_api_key": "effective-credential",
            "remote_verify_version": False,
        },
    )

    with pytest.raises(StopBeforeRunCreation):
        runner.run_physics_apply(
            PhysicsApplyConfig(
                repo_root=tmp_path,
                usd_path=source,
                output_dir=run_dir,
            )
        )

    assert observed_render_configs == [
        {
            "remote_url": "https://ovrtx.example.test",
            "remote_api_key": "effective-credential",
            "remote_verify_version": True,
        }
    ]
    assert not run_dir.exists()


def test_physics_remote_preflight_redacts_credential_bearing_failure(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from usd_core import physics_runtime

    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "run"
    credential_url = (
        "https://user:password@ovrtx.example.test/physics/signed-token"
        "?access_token=query-secret#fragment-secret"
    )
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    monkeypatch.setattr(physics_runtime, "ovphysx_platform_supported", lambda: False)
    monkeypatch.setattr(
        runner,
        "_effective_usd_cli_render_config",
        lambda _root: {"remote_url": credential_url},
    )
    monkeypatch.setattr(
        physics_runtime,
        "resolve_remote_physics_backend",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            RuntimeError(f"{credential_url}: readiness failed")
        ),
    )

    with pytest.raises(ValueError) as raised:
        runner.run_physics_apply(
            PhysicsApplyConfig(
                repo_root=tmp_path,
                usd_path=source,
                output_dir=run_dir,
            )
        )

    message = str(raised.value)
    assert "no configured remote OVRTX backend passed physics readiness" in message
    for secret in (
        "user",
        "password",
        "signed-token",
        "query-secret",
        "fragment-secret",
    ):
        assert secret not in message
    assert raised.value.__suppress_context__ is True
    assert not run_dir.exists()


def test_physics_runner_ignores_archived_run_state_for_remote_preflight(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Remote preflight must use the parent config the new daemon will inherit."""

    from usd_core import physics_runtime

    source = tmp_path / "source.usda"
    source.write_text("#usda 1.0\n", encoding="utf-8")
    parent_config = tmp_path / ".usd-cli" / "config.toml"
    parent_config.parent.mkdir()
    parent_config.write_text(
        "[render]\nremote_url = 'https://current.example.test'\n",
        encoding="utf-8",
    )
    run_dir = tmp_path / "run"
    stale_config = run_dir / ".usd-cli" / "config.toml"
    stale_config.parent.mkdir(parents=True)
    stale_config.write_text(
        "[render]\nremote_url = 'https://stale.example.test'\n",
        encoding="utf-8",
    )
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    monkeypatch.setattr(physics_runtime, "ovphysx_platform_supported", lambda: False)
    observed_render_configs: list[dict[str, object]] = []

    def resolve_remote(
        render_config: dict[str, object], **_kwargs: object
    ) -> dict[str, object]:
        observed_render_configs.append(render_config)
        return {"base_url": "https://current.example.test", "api_key": None}

    monkeypatch.setattr(
        physics_runtime, "resolve_remote_physics_backend", resolve_remote
    )

    class StopBeforeRunCreation(Exception):
        pass

    monkeypatch.setattr(
        runner,
        "_prepare_run_dir",
        lambda _config: (_ for _ in ()).throw(StopBeforeRunCreation()),
    )

    with pytest.raises(StopBeforeRunCreation):
        runner.run_physics_apply(
            PhysicsApplyConfig(
                repo_root=tmp_path,
                usd_path=source,
                output_dir=run_dir,
            )
        )

    assert observed_render_configs[0]["remote_url"] == "https://current.example.test"
    assert "stale.example.test" not in json.dumps(observed_render_configs)


