def test_remote_physics_render_config_pins_probed_backend_pool() -> None:
    selected_url = "https://selected.example.test"
    pinned = runner._pinned_remote_physics_render_config(
        {
            "renderer": "remote",
            "remote_url": "https://legacy.example.test",
            "remote_api_key": "legacy-secret",
            "remote_timeout": 17,
            "remote_verify_version": False,
            "backends": [
                {"url": "https://first.example.test", "api_key": "first-secret"},
                {"url": selected_url, "api_key": "selected-secret"},
            ],
        },
        {
            "base_url": selected_url,
            "api_key": "selected-secret",
        },
    )

    assert pinned["backends"] == [{"url": selected_url}]
    assert pinned["remote_url"] == selected_url
    assert "remote_api_key" not in pinned
    assert pinned["remote_timeout"] == 17
    assert pinned["remote_verify_version"] is True
    assert "first.example.test" not in json.dumps(pinned)
    assert "legacy.example.test" not in json.dumps(pinned)
    assert "selected-secret" not in json.dumps(pinned)
    assert "first-secret" not in json.dumps(pinned)
    assert "legacy-secret" not in json.dumps(pinned)


@pytest.mark.parametrize(
    "credential_url",
    [
        "https://user:password@ovrtx.example.test/physics",
        "https://username-only@ovrtx.example.test",
        "https://ovrtx.example.test/invoke/signed-path-secret",
        "https://ovrtx.example.test/physics?access_token=query-secret",
        "https://ovrtx.example.test/physics#fragment-secret",
        "file://ovrtx.example.test",
        "https://ovrtx.example.test:invalid",
    ],
)
def test_remote_physics_render_config_rejects_non_origin_urls(
    credential_url: str,
) -> None:
    with pytest.raises(ValueError) as raised:
        runner._pinned_remote_physics_render_config(
            {"backends": [{"url": credential_url}]},
            {"base_url": credential_url, "api_key": "selected-secret"},
        )

    message = str(raised.value)
    assert "must be HTTP(S) origins" in message
    for secret in (
        "user",
        "password",
        "username-only",
        "signed-path-secret",
        "query-secret",
        "fragment-secret",
        "selected-secret",
    ):
        assert secret not in message


