def test_bridge_import_rejects_child_symlink_at_canonical_output(
    tmp_path: Path, monkeypatch: Any
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    child_final = run_dir / "child-final.md"
    external = tmp_path / "external.txt"
    external.write_text("unchanged", encoding="utf-8")
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
    )
    canonical_request = run_dir / "raw" / "codex_request.json"
    malicious_request = tmp_path / "malicious-request.json"
    malicious_request.write_text(
        json.dumps(
            {
                "child_final_path": str(external),
                "items_path": str(external),
                "result_path": str(external),
            }
        ),
        encoding="utf-8",
    )

    def fake_subprocess_with_timeout(**kwargs: object) -> int:
        canonical_request.unlink()
        canonical_request.symlink_to(malicious_request)
        command = kwargs["command"]
        assert isinstance(command, list)
        assert Path(command[-1]) != canonical_request
        request = json.loads(Path(command[-1]).read_text(encoding="utf-8"))
        Path(request["child_final_path"]).write_text("bridge-owned", encoding="utf-8")
        child_final.symlink_to(external)
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )

    # The run-directory guard now rejects any child-created symlink before the
    # per-path "regular file or absent" check can be reached.
    with pytest.raises(UnsafeRunArtifactError, match="symlinks are not allowed"):
        _run_child_agent(
            config=config,
            prompt="Inspect the asset.",
            run_dir=run_dir,
            child_output_path=run_dir / "child-output.log",
            child_final_path=child_final,
        )

    assert external.read_text(encoding="utf-8") == "unchanged"


def test_bridge_log_open_and_chmod_reject_run_symlinks(
    tmp_path: Path, monkeypatch: Any
) -> None:
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    external = tmp_path / "external.log"
    external.write_text("unchanged", encoding="utf-8")
    external.chmod(0o644)
    external_mode = stat.S_IMODE(external.stat().st_mode)
    child_output = run_dir / "child-output.log"
    child_output.symlink_to(external)
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
    )
    called = False

    def fake_subprocess_with_timeout(**_kwargs: object) -> int:
        nonlocal called
        called = True
        return 0

    monkeypatch.setattr(
        runner, "_run_subprocess_with_timeout", fake_subprocess_with_timeout
    )

    # The pre-launch run-directory scan rejects the planted symlink before the
    # child is ever started, so the child must not run at all.
    with pytest.raises(UnsafeRunArtifactError, match="symlinks are not allowed"):
        _run_child_agent(
            config=config,
            prompt="Inspect the asset.",
            run_dir=run_dir,
            child_output_path=child_output,
            child_final_path=run_dir / "child-final.md",
        )
    assert not called

    runner._chmod_private(child_output, within=run_dir)
    assert stat.S_IMODE(external.stat().st_mode) == external_mode
    assert external.read_text(encoding="utf-8") == "unchanged"


def test_persistent_codex_session_consumes_private_request(
    tmp_path: Path, monkeypatch: Any
) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    (run_dir / "raw").mkdir(parents=True)
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[tmp_path / "reference.png"],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
    )

    class FakeProcess:
        stdin = None
        stdout: list[str] = []
        returncode = 0

        def poll(self) -> int:
            return 0

    # The session now starts under descendant supervision, which handshakes over
    # a real pipe the faked process never writes to. Stub the supervisor the same
    # way the other faked-process tests do.
    _stub_ready_descendant_supervisor(monkeypatch, FakeProcess())
    monkeypatch.setattr(
        runner.CodexThreadSession,
        "_wait_until_ready",
        lambda _self: None,
    )

    session = runner.CodexThreadSession(config=config, run_dir=run_dir)
    private_request = Path(session.command[-1])
    canonical_request = run_dir / "raw" / "codex_thread_session.json"
    try:
        assert private_request.parent != run_dir
        assert private_request.read_text(encoding="utf-8") == (
            canonical_request.read_text(encoding="utf-8")
        )
        malicious = tmp_path / "malicious-session.json"
        malicious.write_text('{"codex_sandbox_mode":"danger-full-access"}\n')
        canonical_request.unlink()
        canonical_request.symlink_to(malicious)
        assert (
            json.loads(private_request.read_text(encoding="utf-8"))[
                "codex_sandbox_mode"
            ]
            == config.codex_sandbox_mode
        )
    finally:
        session.close()

    assert not private_request.parent.exists()


