def test_material_usd_cli_child_contract_uses_staged_run_root_inputs(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Option B: the child's asset and library paths are the staged run-root
    derivatives, never the caller's originals outside the daemon root."""

    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    # Coverage-gap detection has its own suite; these fixtures assert
    # backend wiring and staged-input contracts.
    monkeypatch.setattr(runner, "_coverage_gap_issues", lambda _coverage: [])
    monkeypatch.setattr(
        runner,
        "ensure_usd_cli_available",
        lambda _repo_root=None: "usd-cli 0.1.0 (renderer: ovrtx)",
    )
    prompts: list[str] = []

    def fake_run_child_agent(**kwargs: Any) -> int:
        prompts.append(kwargs["prompt"])
        _write_usd_cli_child_artifacts(kwargs["run_dir"])
        return 0

    monkeypatch.setattr(runner, "_run_child_agent", fake_run_child_agent)
    monkeypatch.setattr(
        runner,
        "_run_material_post_apply_review_turn",
        lambda **_kwargs: 0,
    )

    result = runner.run_material_assignment(
        _usd_cli_material_assign_config(tmp_path, inputs)
    )

    assert result.returncode == 0
    run_dir = result.run_dir
    staged_source = run_dir / "inputs" / "source" / "asset.usd"
    staged_library = run_dir / "inputs" / "material_library" / "materials.usd"
    assert staged_source.is_file()
    assert staged_library.is_file()
    assert staged_source.read_bytes() == inputs["usd"].read_bytes()
    assert staged_library.read_bytes() == inputs["materials_usd"].read_bytes()

    (prompt,) = prompts
    assert f'"authoring_asset_path": {json.dumps(str(staged_source))}' in prompt
    assert f'"asset_path": {json.dumps(str(staged_source))}' in prompt
    assert f'"materials_usd": {json.dumps(str(staged_library))}' in prompt
    # The caller's original paths never appear as the child's scene-tool
    # targets; a single open of them would fail closed at the daemon.
    assert f'"authoring_asset_path": {json.dumps(str(inputs["usd"]))}' not in prompt
    assert f'"materials_usd": {json.dumps(str(inputs["materials_usd"]))}' not in prompt

    request = json.loads(result.request_path.read_text(encoding="utf-8"))
    assert request["inputs"]["staged_usd"] == str(staged_source)
    assert request["inputs"]["staged_materials_usd"] == str(staged_library)
    contract = request["material_contract"]
    assert contract["staged_source"]["self_contained"] is True
    assert contract["staged_source"]["source_sha256"] == contract["source_sha256"]
    assert contract["staged_material_library"]["self_contained"] is True
    assert runner._staged_input_integrity_errors(run_dir) == []


