    assert request["scene_optimize"] is True
    assert request["scene_optimizer"]["status"] == "failed"
    assert "optimizer_fallback" not in request
    error_path = result.run_dir / "raw" / "scene_optimizer" / "error.json"
    assert error_path.is_file()
    events = (result.run_dir / "trace" / "events.jsonl").read_text(encoding="utf-8")
    assert "scene_optimization_failed" in events


