def test_run_physics_apply_leases_usd_cli_daemon_before_setup_and_reaps_failure(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _allow_test_physics_runtime_preflight(monkeypatch)
    usd = tmp_path / "asset.usda"
    usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    route = _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    assert route.target_path is not None
    daemon_lease = runner.UsdCliDaemonLease(
        target_path=route.target_path,
        identity=_fake_usd_cli_daemon_identity(),
        server_state_bytes=_fake_external_usd_cli_server_state(),
        daemon_ledger_bytes=b"123:t1\n",
    )
    setup_order: list[str] = []
    daemon_stops: list[dict[str, Any]] = []
    config = PhysicsApplyConfig(
        repo_root=tmp_path,
        usd_path=usd,
        output_dir=run_dir,
    )

    def fake_start(**kwargs: Any) -> runner.UsdCliDaemonLease:
        assert kwargs == {
            "route": route,
            "run_dir": run_dir,
            "idle_timeout_seconds": runner._usd_cli_daemon_idle_timeout_seconds(
                config.child_timeout_seconds
            ),
            "external_lifecycle": True,
            "allowed_roots": (run_dir.resolve(),),
        }
        setup_order.append("daemon")
        state_dir = run_dir / ".usd-cli"
        state_dir.mkdir(parents=True, exist_ok=True)
        (state_dir / "server.json").write_bytes(daemon_lease.server_state_bytes)
        return daemon_lease

    def fail_physics_packet(*_args: Any, **_kwargs: Any) -> dict[str, Any]:
        setup_order.append("physics_packet")
        raise RuntimeError("physics packet failed")

    monkeypatch.setattr(runner, "_start_usd_cli_run_daemon", fake_start)
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda **kwargs: daemon_stops.append(kwargs),
    )
    monkeypatch.setattr(runner, "_prepare_physics_run_packet", fail_physics_packet)

    with pytest.raises(RuntimeError, match="physics packet failed"):
        runner.run_physics_apply(config)

    assert setup_order == ["daemon", "physics_packet"]
    assert daemon_stops == [{"lease": daemon_lease}]
    events = (run_dir / "trace" / "events.jsonl").read_text(encoding="utf-8")
    assert "usd_cli_daemon_ready" in events
    manifest = json.loads(
        (run_dir / "workflow_run_manifest.json").read_text(encoding="utf-8")
    )
    assert manifest["workflow"] == "physics.apply"
    assert manifest["status"] == "fail"
    failure = manifest["failure"]
    assert failure["code"] == "physics_setup_failed"
    assert failure["error_type"] == "RuntimeError"
    assert failure["error"] == "physics packet failed"
    # The recorder surfaces the incomplete artifact contract on failed runs
    # (the physics failure object is what conditional-exit grading trusts).
    assert failure["integrity"]["missing_required_artifacts"]
    assert (run_dir / "trace" / "operation_trace.json").is_file()


def test_run_physics_apply_keeps_lease_until_persistent_child_session_closes(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _allow_test_physics_runtime_preflight(monkeypatch)
    subprocess.run(["git", "init", "-q"], cwd=tmp_path, check=True)
    subprocess.run(
        ["git", "config", "user.email", "test@example.com"],
        cwd=tmp_path,
        check=True,
    )
    subprocess.run(["git", "config", "user.name", "Test"], cwd=tmp_path, check=True)
    trusted_script = tmp_path / "tools/inspect_asset.py"
    trusted_script.parent.mkdir()
    trusted_script.write_text("print('trusted')\n", encoding="utf-8")
    subprocess.run(
        ["git", "add", str(trusted_script.relative_to(tmp_path))],
        cwd=tmp_path,
        check=True,
    )
    subprocess.run(
        ["git", "commit", "-qm", "add trusted tool"], cwd=tmp_path, check=True
    )
    usd = tmp_path / "asset.usda"
    usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    route = _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    assert route.target_path is not None
    daemon_lease = runner.UsdCliDaemonLease(
        target_path=route.target_path,
        identity=_fake_usd_cli_daemon_identity(),
        server_state_bytes=_fake_external_usd_cli_server_state(),
        daemon_ledger_bytes=b"123:t1\n",
    )
    lifecycle: list[str] = []

    def fake_start(**_kwargs: Any) -> runner.UsdCliDaemonLease:
        lifecycle.append("daemon_start")
        return daemon_lease

    def fake_physics_packet(
        _config: PhysicsApplyConfig,
        packet_run_dir: Path,
        **_kwargs: Any,
    ) -> dict[str, Any]:
        assert lifecycle == ["daemon_start"]
        lifecycle.append("physics_packet")
        raw_dir = packet_run_dir / "raw"
        for name in (
            "physics_run_packet.json",
            "physics_components.json",
            "physics_topology.json",
        ):
            (raw_dir / name).write_text("{}\n", encoding="utf-8")
        staged_usd = packet_run_dir / "inputs" / "source" / "asset.usda"
        staged_usd.parent.mkdir(parents=True, exist_ok=True)
        staged_usd.write_text("#usda 1.0\n", encoding="utf-8")
        return {
            "session_id": None,
            "staged_source": {"staged_usd_path": str(staged_usd)},
        }

    class FakeCodexThreadSession:
        def __init__(self, **_kwargs: Any) -> None:
            lifecycle.append("session_start")

        def close(self) -> None:
            lifecycle.append("session_close")

    def fake_child(**kwargs: Any) -> int:
        assert lifecycle == ["daemon_start", "physics_packet", "session_start"]
        lifecycle.append("child")
        (kwargs["run_dir"] / "raw" / "physics_decision_patch.json").write_text(
            "{}\n",
            encoding="utf-8",
        )
        (kwargs["run_dir"] / "raw" / "codex_items.json").write_text(
            json.dumps([{"command": f"python {trusted_script}", "exit_code": 0}]),
            encoding="utf-8",
        )
        return 0

    def fake_refinement(**kwargs: Any) -> tuple[int, None]:
        assert isinstance(kwargs["codex_session"], FakeCodexThreadSession)
        lifecycle.append("refinement")
        return 0, None

    monkeypatch.setattr(runner, "_start_usd_cli_run_daemon", fake_start)
    monkeypatch.setattr(
        runner,
        "_stop_usd_cli_run_daemon_best_effort",
        lambda **_kwargs: lifecycle.append("daemon_stop"),
    )
    monkeypatch.setattr(runner, "_prepare_physics_run_packet", fake_physics_packet)
    monkeypatch.setattr(runner, "CodexThreadSession", FakeCodexThreadSession)
    monkeypatch.setattr(
        runner,
        "_should_start_codex_thread_session",
        lambda _config: True,
    )
    monkeypatch.setattr(runner, "_run_child_agent", fake_child)
    monkeypatch.setattr(
        runner,
        "_run_physics_visual_refinement_loop",
        fake_refinement,
    )

    result = runner.run_physics_apply(
        PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=usd,
            output_dir=run_dir,
            codex_persistent_refinement=True,
            vqa_refinement_max_iterations=1,
        )
    )

    assert result.returncode != 0
    assert lifecycle == [
        "daemon_start",
        "physics_packet",
        "session_start",
        "child",
        "refinement",
        "session_close",
        "daemon_stop",
    ]


@pytest.mark.skipif(
    os.name == "nt",
    reason="requires POSIX shebang dispatch and executable symlinks",
)
def test_child_telemetry_env_mints_run_trace_for_usd_cli_backend(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    package_bin = tmp_path / "package-bin"
    existing_shim_bin = tmp_path / "existing-shim-bin"
    package_bin.mkdir()
    existing_shim_bin.mkdir()
    real_cli = package_bin / "usd-cli"
    wrapper = package_bin / "usd-cli-tel"
    capture = tmp_path / "wrapper-target.txt"
    real_cli.write_text(
        "#!/bin/sh\nprintf 'real:%s\\n' \"$*\"\n",
        encoding="utf-8",
    )
    wrapper.write_text(
        '#!/bin/sh\nprintf "%s\\n" "$USD_CLI_TEL_TARGET" > "$ROUTE_CAPTURE"\n'
        'exec "$USD_CLI_TEL_TARGET" "$@"\n',
        encoding="utf-8",
    )
    real_cli.chmod(real_cli.stat().st_mode | stat.S_IXUSR)
    wrapper.chmod(wrapper.stat().st_mode | stat.S_IXUSR)
    # Simulate a caller whose ambient PATH shadows usd-cli with usd-cli-tel.
    # The package-owned route must win: TARGET stays the package usd-cli, and
    # the verified scripts directory is placed before the shim.
    (existing_shim_bin / "usd-cli").symlink_to(wrapper)
    monkeypatch.setenv(
        "PATH",
        str(existing_shim_bin),
    )
    monkeypatch.setattr(
        runner,
        "resolve_package_owned_usd_cli_route",
        lambda _repo_root: usd_cli_common.UsdCliPackageRoute(
            wrapper=wrapper,
            target=real_cli,
            source_root=(
                tmp_path / "repo" / usd_cli_common.USD_CLI_SOURCE_PATH / "src"
            ),
            source_revision="a" * 40,
        ),
    )

    env = runner._child_telemetry_env(config, run_dir)
    trace_id, root_span_id = runner._run_trace_context(run_dir)
    assert env["TRACEPARENT"] == f"00-{trace_id}-{root_span_id}-01"
    assert len(trace_id) == 32 and len(root_span_id) == 16
    assert env["USD_CLI_TEL_FILE"] == str(run_dir / "raw" / "usd_cli_telemetry.jsonl")
    assert env["USD_CLI_TEL_BACKENDS"] == "file"
    assert env["USD_CLI_TEL_DISABLED"] == "0"
    assert env["USD_CLI_TEL_FILE_MAX_BYTES"] == str(50 * 1024 * 1024)
    assert env["USD_CLI_TEL_ACTION_LOCK"] == str(
        run_dir / "raw" / "usd_cli_agent_action.lock.json"
    )
    assert env["USD_CLI_TEL_ACTION_LOCK_TIMEOUT"] == str(
        runner._usd_cli_daemon_idle_timeout_seconds(config.child_timeout_seconds)
    )
    assert env["USD_CLI_TEL_ATTRS"] == (
        f"wu.run_id={trace_id},wu.evidence_trust=child_reported"
    )
    assert env["USD_CLI_SERVER_IDLE_TIMEOUT"] == (
        f"{runner._usd_cli_daemon_idle_timeout_seconds(config.child_timeout_seconds)}s"
    )
    assert env["USD_CLI_TEL_TARGET"] == str(real_cli.resolve())
    assert env["PATH"].split(os.pathsep)[0] == str(package_bin.resolve())
    assert str(existing_shim_bin.resolve()) in env["PATH"].split(os.pathsep)
    assert not (run_dir / "raw" / ".usd-cli-tel-bin").exists()

    # Deterministic: refinement turns and resumed processes share the trace.
    assert runner._child_telemetry_env(config, run_dir) == env

    child_env = os.environ.copy()
    child_env.update(env)
    child_env["ROUTE_CAPTURE"] = str(capture)
    completed = subprocess.run(
        ["usd-cli-tel", "snapshot", "scene.usd"],
        check=True,
        capture_output=True,
        text=True,
        env=child_env,
    )
    assert completed.stdout == "real:snapshot scene.usd\n"
    assert capture.read_text(encoding="utf-8").strip() == str(real_cli.resolve())

    optimized_config = _usd_cli_material_assign_config(
        tmp_path,
        inputs,
        prompt_mode=runner.PROMPT_MODE_SKILL_ROUTED,
        optimize=True,
    )
    assert runner._child_telemetry_env(optimized_config, run_dir) == env


def test_parent_usd_cli_preflight_does_not_acquire_child_action_lease(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    config = _usd_cli_material_assign_config(tmp_path, inputs)
    object.__setattr__(config, "usd_cli_server_url", "http://127.0.0.1:43210")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    route = runner.UsdCliTelemetryRoute(
        status="active",
        wrapper_path=tmp_path / "usd-cli-tel",
        target_path=tmp_path / "usd-cli",
    )
    monkeypatch.setattr(
        runner,
        "_workflow_usd_cli_telemetry_route",
        lambda *_args, **_kwargs: pytest.fail(
            "the already-authenticated preflight route must be reused"
        ),
    )
    monkeypatch.setattr(
        runner,
        "_child_telemetry_env",
        lambda *_args, **_kwargs: {
            "TRACEPARENT": "00-" + "a" * 32 + "-" + "b" * 16 + "-01",
            "USD_CLI_TEL_ACTION_LOCK": str(run_dir / "raw" / "action.lock"),
            "USD_CLI_TEL_ACTION_LOCK_TIMEOUT": "1800",
        },
    )
    captured_env: dict[str, str] = {}
    captured_command: list[str] = []

    def fake_run(
        command: list[str],
        **kwargs: Any,
    ) -> subprocess.CompletedProcess[str]:
        captured_command.extend(command)
        captured_env.update(kwargs["env"])
        return subprocess.CompletedProcess(command, 0, '{"ok": true}', "")

    monkeypatch.setattr(runner, "run_bounded_usd_cli_subprocess", fake_run)

    assert runner._run_usd_cli_json_command(
        config=config,
        run_dir=run_dir,
        session_name="parent-preflight",
        arguments=["open", "scene.usd"],
        telemetry_route=route,
    ) == {"ok": True}
    assert "USD_CLI_TEL_ACTION_LOCK" not in captured_env
    assert "USD_CLI_TEL_ACTION_LOCK_TIMEOUT" not in captured_env
    assert "TRACEPARENT" in captured_env
    assert captured_env[runner.PARENT_USD_CLI_MANAGED_ENV] == "1"
    assert captured_env[runner.USD_CLI_EXTERNAL_LIFECYCLE_ENV] == "1"
    assert captured_env["USD_CLI_NO_DAEMON"] == "1"
    assert captured_env["USD_CLI_SERVER_LIFECYCLE_OWNER"] == "external"
    assert captured_command[:6] == [
        str(route.wrapper_path),
        "--json",
        "--server",
        "http://127.0.0.1:43210",
        "--session",
        "parent-preflight",
    ]


