@pytest.mark.parametrize(
    ("max_iterations", "first_patch_changed", "second_turn_outcome"),
    [
        (1, True, "pass"),
        (1, False, "pass"),
        (2, True, "pass"),
        (2, False, "pass"),
        (2, False, "stale"),
        (3, False, "same_unresolved"),
        (3, False, "same_ovrtx_error"),
        (3, False, "same_malformed"),
    ],
)
def test_usd_cli_visual_refinement_iteration_transitions(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    max_iterations: int,
    first_patch_changed: bool,
    second_turn_outcome: str,
) -> None:
    usd = tmp_path / "asset.usda"
    usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    # Confined refinement turns require the staged run-root derivative the
    # initial usd-cli turn produced.
    runner._stage_usd_cli_input_tree(
        label="source",
        source_usd_path=usd,
        run_dir=run_dir,
    )
    patch_path = raw_dir / "physics_decision_patch.json"
    patch_path.write_text('{"revision":1}\n', encoding="utf-8")
    finalize_iterations: list[int] = []
    support_caches: list[dict[str, dict[str, Any]]] = []
    child_iterations = 0

    def fake_finalize_once(**kwargs: Any) -> dict[str, Any]:
        iteration = int(kwargs["iteration"])
        finalize_iterations.append(iteration)
        support_caches.append(kwargs["ground_clearance_support_cache"])
        evidence_path = run_dir / "validation_evidence.json"
        assignments_path = run_dir / "physics_assignments.json"
        physics_path = run_dir / "physics.usda"
        report_path = run_dir / "runtime" / f"report_{iteration}.json"
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text("{}\n", encoding="utf-8")
        evidence = physics_validation_evidence(
            asset=str(usd),
            target_runtime="ovphysx",
            physics_properties_status="pass",
            runtime_loadability_status="pass",
            no_explosions_status="pass",
        )
        evidence_path.write_text(
            json.dumps(evidence.model_dump(mode="json")),
            encoding="utf-8",
        )
        assignments_path.write_text(
            json.dumps({"schema_version": "test", "decisions": []}),
            encoding="utf-8",
        )
        # Mirror the real finalizer: attest the assignments bytes it just
        # wrote so the loop's verify-then-reattest sees an intact file.
        kwargs["run_state"]["assignments_sha256"] = runner._bounded_record_sha256(
            assignments_path
        )
        physics_path.write_text(
            f"#usda 1.0\n# iteration {iteration}\n",
            encoding="utf-8",
        )
        return {
            "success": True,
            "validation_status": "pass",
            "physics_usd_path": str(physics_path),
            "validation_evidence_path": str(evidence_path),
            "assignments_path": str(assignments_path),
            "simulation_report_path": str(report_path),
            "rendered_frames": [],
        }

    def fake_child_agent(**_kwargs: Any) -> int:
        nonlocal child_iterations
        child_iterations += 1
        if second_turn_outcome == "same_malformed":
            (run_dir / "physics_behavior_assessment.json").write_text(
                '{"status":"not-a-valid-status","checked_views":42}\n',
                encoding="utf-8",
            )
            return 0
        if child_iterations == 2 and second_turn_outcome == "stale":
            return 0
        if child_iterations == 1 and first_patch_changed:
            patch_path.write_text('{"revision":2}\n', encoding="utf-8")
            status = "fixed"
            notes = "Updated the patch for another stateless validation pass."
            unresolved_issues: list[str] = []
        elif second_turn_outcome == "same_ovrtx_error":
            status = "pass"
            notes = "The child found no additional visual issue."
            unresolved_issues = []
        elif child_iterations == 1 or second_turn_outcome == "same_unresolved":
            status = "unresolved_issues"
            notes = "The visual issue remains unresolved; review another turn."
            unresolved_issues = ["The visual issue remains unresolved."]
        else:
            status = "pass"
            notes = "The statelessly rebuilt result passed."
            unresolved_issues = []
        (run_dir / "physics_behavior_assessment.json").write_text(
            json.dumps(
                {
                    "schema_version": (
                        "content-agent-workflows.physics-behavior-assessment.v1"
                    ),
                    "status": status,
                    "checked_views": [],
                    "runtime_report": str(
                        run_dir / "runtime" / f"report_{child_iterations}.json"
                    ),
                    "rendered_frames": [],
                    "issues_found": [],
                    "issues_fixed": [],
                    "unresolved_issues": unresolved_issues,
                    "assessment_notes": notes,
                }
            ),
            encoding="utf-8",
        )
        return 0

    monkeypatch.setattr(runner, "_finalize_physics_once", fake_finalize_once)
    monkeypatch.setattr(runner, "_run_child_agent", fake_child_agent)

    def fake_ovrtx_evidence_errors(**kwargs: Any) -> list[str]:
        if second_turn_outcome != "same_ovrtx_error":
            return []
        iteration = int(kwargs["iteration"])
        frame = (
            run_dir
            / "runtime"
            / f"visual_review_frames_{iteration}"
            / "review_frame_0000.png"
        )
        return [f"OVRTX review frame is missing or unsafe: {frame}"]

    monkeypatch.setattr(
        runner,
        "_physics_ovrtx_review_evidence_errors",
        fake_ovrtx_evidence_errors,
    )
    # The fake finalize never touches run_state, so a pre-set runtime-skip
    # flag persists to the stop points: both expected non-evaluable exits
    # (converged and max-iterations) must record the terminal-stop candidate.
    loop_run_state: dict[str, Any] = {
        "runtime_not_evaluated": True,
        "authoring_complete": True,
    }
    returncode, session_id = runner._run_physics_visual_refinement_loop(
        config=PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=usd,
            output_dir=run_dir,
            vqa_refinement_max_iterations=max_iterations,
        ),
        run_dir=run_dir,
        inspection_pin=None,
        session_id=None,
        trace_writer=TraceWriter(run_dir),
        scene_service=None,
        usd_cli_session=runner.WorkflowUsdCliSession(
            project_dir=run_dir,
            session_id="physics-refinement-test-session",
            route=SimpleNamespace(),
            workflow="physics.apply",
        ),
        run_state=loop_run_state,
    )

    expected_returncode = (
        1
        if (max_iterations == 1 and not first_patch_changed)
        or second_turn_outcome
        in {"stale", "same_unresolved", "same_ovrtx_error", "same_malformed"}
        else 0
    )
    assert returncode == expected_returncode
    assert session_id is None
    assert finalize_iterations == (
        [1] if max_iterations == 1 and not first_patch_changed else [1, 2]
    )
    assert child_iterations == (1 if max_iterations == 1 else 2)
    assert len(support_caches) == len(finalize_iterations)
    assert all(cache is support_caches[0] for cache in support_caches)
    events = (run_dir / "trace" / "events.jsonl").read_text(encoding="utf-8")
    assert ("physics_refinement_source_reset" in events) is first_patch_changed
    assert "physics_refinement_session_restarted" not in events
    if expected_returncode == 1:
        history = json.loads(
            (raw_dir / "physics_visual_validation_history.json").read_text(
                encoding="utf-8"
            )
        )
        expected_status = (
            "converged_unresolved"
            if second_turn_outcome
            in {"same_unresolved", "same_ovrtx_error", "same_malformed"}
            else "max_iterations_reached"
        )
        assert history["status"] == expected_status
        assert history["stop_reason"]
        # Both expected non-evaluable exits carry the terminal-stop
        # candidate when the terminal finalize recorded the runtime skip.
        terminal_stop = loop_run_state.get("terminal_stop")
        assert terminal_stop is not None
        assert terminal_stop["kind"] == "conditional_validation_stop"
        assert terminal_stop["history_status"] == expected_status
        assert terminal_stop["runtime_not_evaluated"] is True
        assert terminal_stop["authoring_complete"] is True
    else:
        assert loop_run_state.get("terminal_stop") is None
    if second_turn_outcome == "stale":
        assert (raw_dir / "physics_behavior_assessment_stale_2.json").is_file()
        assert "physics_behavior_assessment_stale" in events
    if second_turn_outcome in {
        "same_unresolved",
        "same_ovrtx_error",
        "same_malformed",
    }:
        assert "physics_visual_review_converged_unresolved" in events
    if second_turn_outcome == "same_malformed":
        assert (raw_dir / "physics_behavior_assessment_invalid_1.json").is_file()
        assert (raw_dir / "physics_behavior_assessment_invalid_2.json").is_file()


def test_usd_cli_physics_visual_refinement_uses_staged_source_and_defers_tuning_goal(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The refinement turn must reopen the staged derivative, never the
    caller's original source outside the daemon's allowed run root."""

    usd = tmp_path / "asset.usda"
    usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    raw_dir = run_dir / "raw"
    raw_dir.mkdir(parents=True)
    staged = runner._stage_usd_cli_input_tree(
        label="source",
        source_usd_path=usd,
        run_dir=run_dir,
    )
    patch_path = raw_dir / "physics_decision_patch.json"
    patch_path.write_text('{"revision":1}\n', encoding="utf-8")
    captured_prompt_kwargs: list[dict[str, Any]] = []
    real_prompt_builder = runner.build_physics_visual_refinement_prompt

    def capture_prompt_builder(**kwargs: Any) -> str:
        captured_prompt_kwargs.append(kwargs)
        return real_prompt_builder(**kwargs)

    def fake_finalize_once(**kwargs: Any) -> dict[str, Any]:
        evidence_path = run_dir / "validation_evidence.json"
        report_path = run_dir / "runtime" / "report.json"
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text("{}\n", encoding="utf-8")
        evidence = physics_validation_evidence(
            asset=str(usd),
            target_runtime="ovphysx",
            physics_properties_status="pass",
            runtime_loadability_status="pass",
            no_explosions_status="pass",
        )
        evidence_path.write_text(
            json.dumps(evidence.model_dump(mode="json")),
            encoding="utf-8",
        )
        return {
            "success": True,
            "validation_status": "pass",
            "physics_usd_path": str(run_dir / "physics.usda"),
            "validation_evidence_path": str(evidence_path),
            "assignments_path": str(run_dir / "physics_assignments.json"),
            "simulation_report_path": str(report_path),
            "rendered_frames": [],
        }

    def fake_child_agent(**_kwargs: Any) -> int:
        (run_dir / "physics_behavior_assessment.json").write_text(
            json.dumps(
                {
                    "schema_version": (
                        "content-agent-workflows.physics-behavior-assessment.v1"
                    ),
                    "status": "pass",
                    "checked_views": [],
                    "runtime_report": str(run_dir / "runtime" / "report.json"),
                    "rendered_frames": [],
                    "issues_found": [],
                    "issues_fixed": [],
                    "unresolved_issues": [],
                    "assessment_notes": "The authored result passed review.",
                }
            ),
            encoding="utf-8",
        )
        return 0

    monkeypatch.setattr(
        runner,
        "build_physics_visual_refinement_prompt",
        capture_prompt_builder,
    )
    monkeypatch.setattr(runner, "_finalize_physics_once", fake_finalize_once)
    monkeypatch.setattr(runner, "_run_child_agent", fake_child_agent)
    monkeypatch.setattr(
        runner,
        "_physics_ovrtx_review_evidence_errors",
        lambda **_kwargs: [],
    )

    returncode, _session_id = runner._run_physics_visual_refinement_loop(
        config=PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=usd,
            output_dir=run_dir,
            vqa_refinement_max_iterations=1,
            tune=True,
        ),
        run_dir=run_dir,
        inspection_pin=None,
        session_id=None,
        trace_writer=TraceWriter(run_dir),
        scene_service=None,
        usd_cli_session=runner.WorkflowUsdCliSession(
            project_dir=run_dir,
            session_id="physics-refinement-test-session",
            route=SimpleNamespace(),
            workflow="physics.apply",
        ),
        run_state={},
    )

    assert returncode == 0
    assert captured_prompt_kwargs
    for prompt_kwargs in captured_prompt_kwargs:
        assert prompt_kwargs["usd_path"] == staged.staged_usd_path
        assert prompt_kwargs["usd_path"] != usd
        assert run_dir.resolve() in Path(prompt_kwargs["usd_path"]).parents
        assert prompt_kwargs["defer_behavior_goal_until_tuning"] is True


