def test_usd_cli_material_refinement_uses_staged_run_root_inputs(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Material refinement keeps the staged source and the staged library the
    child re-binds from with `--library`; the caller's originals sit outside
    the daemon's allowed root."""

    source_usd = tmp_path / "asset.usd"
    source_usd.write_text("#usda 1.0\n", encoding="utf-8")
    materials_usd = tmp_path / "materials.usd"
    materials_usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "run"
    raw_dir = run_dir / "raw"
    (run_dir / "trace").mkdir(parents=True)
    raw_dir.mkdir(parents=True)
    staged_source = runner._stage_usd_cli_input_tree(
        label="source",
        source_usd_path=source_usd,
        run_dir=run_dir,
    )
    staged_library = runner._stage_usd_cli_input_tree(
        label="material_library",
        source_usd_path=materials_usd,
        run_dir=run_dir,
    )

    unresolved_vqa = {
        "status": "unresolved_issues",
        "issues_found": ["Panel is too dark."],
        "issues_fixed": [],
        "unresolved_issues": ["Panel is too dark."],
    }
    fixed_vqa = {
        "status": "fixed",
        "issues_found": ["Panel was too dark."],
        "issues_fixed": ["Panel material was corrected."],
        "unresolved_issues": [],
    }

    def write_assessment(vqa: dict[str, object]) -> None:
        (run_dir / "visual_quality_assessment.json").write_text(
            json.dumps(vqa), encoding="utf-8"
        )
        (run_dir / "assignments.json").write_text(
            json.dumps(
                {
                    "coverage": _complete_material_coverage(1),
                    "assignments": [],
                    "final_review": {"unresolved_issues": vqa["unresolved_issues"]},
                    "visual_quality_assessment": vqa,
                }
            ),
            encoding="utf-8",
        )

    write_assessment(unresolved_vqa)
    captured_prompt_kwargs: list[dict[str, Any]] = []
    real_prompt_builder = runner.build_material_refinement_prompt

    def capture_prompt_builder(**kwargs: Any) -> str:
        captured_prompt_kwargs.append(kwargs)
        return real_prompt_builder(**kwargs)

    def fake_child(**kwargs: Any) -> int:
        Path(kwargs["child_final_path"]).write_text("reviewed", encoding="utf-8")
        write_assessment(fixed_vqa)
        return 0

    monkeypatch.setattr(
        runner,
        "build_material_refinement_prompt",
        capture_prompt_builder,
    )
    monkeypatch.setattr(runner, "_run_child_agent", fake_child)
    monkeypatch.setattr(
        runner,
        "_validate_material_repair_scope",
        lambda **_kwargs: ("applied", ["/World/Panel"]),
    )
    monkeypatch.setattr(
        runner,
        "_run_material_post_apply_review_turn",
        lambda **_kwargs: 0,
    )
    monkeypatch.setattr(
        runner,
        "_materialize_usd_cli_canonical_artifacts",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(
        runner,
        "_finalize_usd_cli_material_decisions",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(
        runner, "_ensure_material_assignment_artifacts", lambda **_kwargs: None
    )
    monkeypatch.setattr(
        runner, "_snapshot_material_step_artifacts", lambda **_kwargs: None
    )

    returncode = runner._run_vqa_refinement_loop(
        config=MaterialAssignConfig(
            repo_root=tmp_path,
            usd_path=source_usd,
            reference_images=[tmp_path / "reference.png"],
            materials_yaml=tmp_path / "materials.yaml",
            materials_usd=materials_usd,
            output_dir=run_dir,
            vqa_refinement_max_iterations=2,
        ),
        run_dir=run_dir,
        request={},
        preflight_packet=None,
        trace_writer=TraceWriter(run_dir),
        initial_child_output_path=run_dir / "child-output.log",
        initial_child_final_path=run_dir / "child-final.md",
        prompt_image_inputs=[],
    )

    assert returncode == 0
    assert captured_prompt_kwargs
    for prompt_kwargs in captured_prompt_kwargs:
        assert prompt_kwargs["usd_path"] == staged_source.staged_usd_path
        assert prompt_kwargs["materials_usd"] == staged_library.staged_usd_path
        assert prompt_kwargs["usd_path"] != source_usd
        assert prompt_kwargs["materials_usd"] != materials_usd
        assert run_dir.resolve() in Path(prompt_kwargs["usd_path"]).parents
        assert run_dir.resolve() in Path(prompt_kwargs["materials_usd"]).parents


