def test_reused_codex_session_uses_supported_turn_signature(tmp_path: Path) -> None:
    _write_trusted_material_skill_catalog(tmp_path)
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    config = MaterialAssignConfig(
        repo_root=tmp_path,
        usd_path=tmp_path / "asset.usd",
        reference_images=[],
        materials_yaml=tmp_path / "materials.yaml",
        materials_usd=tmp_path / "materials.usd",
    )

    class StubSession:
        def run_turn(
            self,
            *,
            prompt: str,
            run_dir: Path,
            child_output_path: Path,
            child_final_path: Path,
            scene_service: object | None = None,
            prompt_image_inputs: list[dict[str, str]] | None = None,
            output_schema: dict[str, object] | None = None,
            bridge_artifact_prefix: str | None = None,
            launch_descriptor: runner.ChildLaunchDescriptor | None = None,
        ) -> int:
            del (
                prompt,
                run_dir,
                child_output_path,
                child_final_path,
                scene_service,
                prompt_image_inputs,
                output_schema,
                bridge_artifact_prefix,
                launch_descriptor,
            )
            return 0

    assert (
        _run_child_agent(
            config=config,
            prompt="test",
            run_dir=run_dir,
            child_output_path=run_dir / "child-output.log",
            child_final_path=run_dir / "child-final.md",
            codex_session=StubSession(),  # type: ignore[arg-type]
        )
        == 0
    )


def test_material_memory_summary_survives_interrupted_run_and_cleanup_failure(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    run_dir = tmp_path / "run"
    original_close = runner.AgentMemoryBroker.close

    def close_then_fail(broker: runner.AgentMemoryBroker) -> None:
        original_close(broker)
        raise RuntimeError("simulated broker cleanup failure")

    monkeypatch.setattr(
        runner,
        "_run_child_agent",
        lambda **_kwargs: (_ for _ in ()).throw(KeyboardInterrupt()),
    )
    monkeypatch.setattr(runner.AgentMemoryBroker, "close", close_then_fail)

    with pytest.raises(KeyboardInterrupt):
        runner.run_material_assignment(
            _usd_cli_material_assign_config(
                tmp_path,
                inputs,
                output_dir=run_dir,
                memory_enabled=True,
                memory_root=tmp_path / "memory",
            )
        )

    memory_summary = json.loads(
        (run_dir / "agent_memory_summary.json").read_text(encoding="utf-8")
    )
    assert memory_summary["enabled"] is True
    assert memory_summary["status"] == "empty"
    events = [
        json.loads(line)
        for line in (run_dir / "trace" / "events.jsonl").read_text().splitlines()
        if line.strip()
    ]
    assert any(
        event["event_type"] == "agent_memory_broker_stopped"
        and "Failed" in event["summary"]
        for event in events
    )


