@pytest.mark.parametrize(
    (
        "max_iterations",
        "final_assessment",
        "expected_returncode",
        "expected_child_calls",
        "status",
        "finalizer_mutates_renders",
    ),
    [
        (2, "satisfied", 0, 1, "satisfied", False),
        (2, "systematic", 2, 1, "systematic_unfixable", False),
        (2, "satisfied", 2, 1, "delegated_post_finalize_review_not_run", True),
        (3, "satisfied", 0, 2, "satisfied", True),
    ],
)
def test_delegated_vqa_reviews_post_finalize_renders_before_success(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    max_iterations: int,
    final_assessment: str,
    expected_returncode: int,
    expected_child_calls: int,
    status: str,
    finalizer_mutates_renders: bool,
) -> None:
    run_dir = tmp_path / "run"
    _stage_material_vqa_policy_inputs(tmp_path, run_dir)
    raw_dir = run_dir / "raw"
    final_dir = run_dir / "final_renders"
    (run_dir / "trace").mkdir(parents=True)
    raw_dir.mkdir(parents=True, exist_ok=True)
    final_dir.mkdir()
    final_render = final_dir / "final_oblique.png"
    final_render.write_bytes(b"before-finalization")
    side_render = final_dir / "final_side_px.png"
    side_render.write_bytes(b"side-before-finalization")

    unresolved_vqa = {
        "status": "unresolved_issues",
        "issues_found": ["Panel is too dark."],
        "issues_fixed": [],
        "unresolved_issues": ["Panel is too dark."],
    }
    child_vqa = (
        {
            "status": "unresolved_issues",
            "issues_found": ["Panel is too dark."],
            "issues_fixed": [],
            "unresolved_issues": [
                "Panel remains unresolved because the material library has no matching finish."
            ],
        }
        if final_assessment == "systematic"
        else {
            "status": "fixed",
            "issues_found": ["Panel was too dark."],
            "issues_fixed": ["Panel material was corrected."],
            "unresolved_issues": [],
        }
    )

    def write_assessment(vqa: dict[str, object]) -> None:
        (run_dir / "visual_quality_assessment.json").write_text(
            json.dumps(vqa), encoding="utf-8"
        )
        (run_dir / "assignments.json").write_text(
            json.dumps(
                {
                    "coverage": _complete_material_coverage(1),
                    "assignments": [],
                    "final_review": {"unresolved_issues": vqa["unresolved_issues"]},
                    "visual_quality_assessment": vqa,
                }
            ),
            encoding="utf-8",
        )

    write_assessment(unresolved_vqa)
    reviewed_pixels: list[list[bytes]] = []
    child_calls = 0

    def fake_prepare_delegated_turn(
        **kwargs: object,
    ) -> tuple[str, list[dict[str, str]]]:
        image_inputs = kwargs["prompt_image_inputs"]
        assert isinstance(image_inputs, list)
        reviewed_pixels.append(
            [Path(item["path"]).read_bytes() for item in image_inputs]
        )
        return str(kwargs["prompt"]), []

    def fake_child(**kwargs: object) -> int:
        nonlocal child_calls
        child_calls += 1
        child_final_path = kwargs["child_final_path"]
        assert isinstance(child_final_path, Path)
        child_final_path.write_text("reviewed", encoding="utf-8")
        write_assessment(child_vqa)
        return 0

    def fake_finalize(**_kwargs: object) -> bool:
        if finalizer_mutates_renders and child_calls == 1:
            side_render.write_bytes(b"side-after-finalization")
        return True

    monkeypatch.setattr(
        runner, "_prepare_delegated_vision_turn", fake_prepare_delegated_turn
    )
    monkeypatch.setattr(runner, "_run_child_agent", fake_child)
    monkeypatch.setattr(
        runner,
        "_validate_material_repair_scope",
        lambda **_kwargs: ("applied", ["/World/Panel"]),
    )
    monkeypatch.setattr(
        runner,
        "_run_material_post_apply_review_turn",
        lambda **_kwargs: 0,
    )
    monkeypatch.setattr(
        runner,
        "_materialize_usd_cli_canonical_artifacts",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(runner, "_finalize_usd_cli_material_decisions", fake_finalize)
    monkeypatch.setattr(
        runner, "_ensure_material_assignment_artifacts", lambda **_kwargs: None
    )
    monkeypatch.setattr(
        runner, "_snapshot_material_step_artifacts", lambda **_kwargs: None
    )

    returncode = runner._run_vqa_refinement_loop(
        config=MaterialAssignConfig(
            repo_root=tmp_path,
            usd_path=tmp_path / "asset.usd",
            reference_images=[tmp_path / "reference.png"],
            materials_yaml=tmp_path / "materials.yaml",
            materials_usd=tmp_path / "materials.usd",
            output_dir=run_dir,
            vqa_refinement_max_iterations=max_iterations,
            vision_backend="test_vision_backend",
            vision_model="test_vision_model",
        ),
        run_dir=run_dir,
        request={},
        preflight_packet={"session_id": "session-1"},
        trace_writer=TraceWriter(run_dir),
        initial_child_output_path=run_dir / "child-output.log",
        initial_child_final_path=run_dir / "child-final.md",
        prompt_image_inputs=[],
    )

    assert returncode == expected_returncode
    assert child_calls == expected_child_calls
    assert reviewed_pixels == [
        [b"before-finalization", b"side-before-finalization"],
        *(
            [[b"before-finalization", b"side-after-finalization"]]
            if finalizer_mutates_renders and max_iterations == 3
            else []
        ),
    ]
    history = json.loads((raw_dir / "vqa_refinement_history.json").read_text())
    assert history["status"] == status
    assert history["iterations"][0]["delegated_review_covers_final_renders"] is (
        not finalizer_mutates_renders
    )
    if finalizer_mutates_renders and max_iterations == 3:
        assert history["iterations"][1]["delegated_review_covers_final_renders"] is True


