def test_run_material_assignment_preserves_child_failure_exit_code_by_default(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)

    def fake_run_child_agent(**kwargs: object) -> int:
        child_final_path = kwargs["child_final_path"]
        assert isinstance(child_final_path, Path)
        child_final_path.write_text("recovered", encoding="utf-8")
        return 7

    monkeypatch.setattr(runner, "_run_child_agent", fake_run_child_agent)
    monkeypatch.setattr(
        runner,
        "_ensure_material_assignment_artifacts",
        lambda **_kwargs: True,
    )
    monkeypatch.delenv(runner.ALLOW_FALLBACK_SUCCESS_ENV, raising=False)
    monkeypatch.delenv(runner.DISABLE_FALLBACK_SUCCESS_ENV, raising=False)

    result = runner.run_material_assignment(
        _usd_cli_material_assign_config(tmp_path, inputs)
    )

    assert result.returncode == 7
    metrics = json.loads(
        (result.run_dir / "run_cost_metrics.json").read_text(encoding="utf-8")
    )
    assert metrics["wall_time_seconds"] >= 0
    assert metrics["repeated_file_reads_total"] is None
    assert metrics["failed_api_calls"] is None
    assert metrics["retried_api_calls"] is None
    assert metrics["context"]["asset"] == str(inputs["usd"])
    events = [
        json.loads(line)
        for line in (result.run_dir / "trace" / "events.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()
    ]
    recovery_events = [
        event
        for event in events
        if event["phase"] == "runner" and event["event_type"] == "warning"
    ]
    assert recovery_events[-1]["data"]["fallback_success_enabled"] is False
    assert recovery_events[-1]["data"]["allow_env"] == runner.ALLOW_FALLBACK_SUCCESS_ENV
    assert recovery_events[-1]["data"]["effective_returncode"] == 7


@pytest.mark.parametrize(
    "failure_mode",
    [
        "coverage",
        "pending_annotation",
        "restore",
        "partial",
        "succeeded_annotation",
    ],
)
def test_run_material_assignment_distinguishes_restore_and_status_failures(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    failure_mode: str,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    output_usd = tmp_path / "materialized.usda"
    run_dir = tmp_path / "run"

    def fake_run_child_agent(**kwargs: object) -> int:
        child_final_path = kwargs["child_final_path"]
        assert isinstance(child_final_path, Path)
        child_final_path.write_text("done", encoding="utf-8")
        return 0

    def fake_ensure_artifacts(**kwargs: object) -> bool:
        artifact_run_dir = kwargs["run_dir"]
        assert isinstance(artifact_run_dir, Path)
        coverage = {
            "candidate_visible_prim_count": 51,
            "material_decision_prim_count": 51,
            "material_assignment_prim_count": 51,
            "preserved_existing_prim_count": 0,
            "ambiguous_unassigned_prim_count": 0,
            "unassigned_visible_prim_count": 0,
            "missing_assignment_prim_count": 0,
            "rejected_assignment_prim_count": 0,
        }
        if failure_mode == "coverage":
            coverage.update(
                {
                    "material_decision_prim_count": 50,
                    "material_assignment_prim_count": 50,
                    "missing_assignment_prim_count": 1,
                }
            )
        (artifact_run_dir / "assignments.json").write_text(
            json.dumps(
                {
                    "coverage": coverage,
                    "assignments": [],
                }
            ),
            encoding="utf-8",
        )
        (artifact_run_dir / "final_summary.md").write_text(
            "# Final Summary\n\nCoverage: 51/51\nTotal uncovered: 0\n",
            encoding="utf-8",
        )
        # The run manifest now records the full required-artifact contract and
        # fails closed when any member is absent. The real implementation writes
        # these alongside the two above, so a fake standing in for it must too.
        (artifact_run_dir / "raw").mkdir(parents=True, exist_ok=True)
        (artifact_run_dir / "raw" / "material_decision_patch.json").write_text(
            json.dumps({"schema_version": "test", "groups": []}), encoding="utf-8"
        )
        (artifact_run_dir / "api_operation_counts.json").write_text(
            json.dumps({"total": 0}), encoding="utf-8"
        )
        (artifact_run_dir / "visual_quality_assessment.json").write_text(
            json.dumps({"status": "pass", "unresolved_issues": []}), encoding="utf-8"
        )
        (artifact_run_dir / "validation_evidence.json").write_text(
            json.dumps({"sim_ready_status": "pass", "failures": [], "checks": []}),
            encoding="utf-8",
        )
        final_renders = artifact_run_dir / "final_renders"
        final_renders.mkdir(parents=True, exist_ok=True)
        Image.new("RGB", (16, 16), "white").save(final_renders / "final_oblique.png")
        return True

    restore_calls = 0

    def fake_restore_materialized_output(
        **_kwargs: object,
    ) -> runner.MaterializedOutputResult:
        nonlocal restore_calls
        restore_calls += 1
        if failure_mode == "restore":
            raise RuntimeError("HTTP 500: Internal server error")
        output_usd.write_text("#usda 1.0\n", encoding="utf-8")
        if failure_mode == "partial":
            return runner.MaterializedOutputResult(
                output_path=output_usd,
                unbound_source_prim_paths=("/World/B",),
                uncovered_assignment_groups=(
                    {
                        "source_prim_paths": ["/World/A", "/World/B"],
                        "runtime_prim_paths": [],
                        "original_source_aliases": {},
                    },
                ),
            )
        return runner.MaterializedOutputResult(output_path=output_usd)

    original_record_status = runner._record_materialized_output_status

    def fake_record_status(
        *,
        run_dir: Path,
        output_usd_path: Path,
        status: str,
        error: Exception | None = None,
        unbound_source_prim_paths: tuple[str, ...] = (),
        uncovered_assignment_groups: tuple[dict[str, object], ...] = (),
        unbound_visible_mesh_paths: tuple[str, ...] = (),
        partially_bound_visible_mesh_paths: tuple[str, ...] = (),
        visible_render_mesh_count: int | None = None,
        final_mesh_binding_coverage_score: float | None = None,
    ) -> None:
        if failure_mode == f"{status}_annotation":
            raise RuntimeError("status artifact is read-only")
        original_record_status(
            run_dir=run_dir,
            output_usd_path=output_usd_path,
            status=status,
            error=error,
            unbound_source_prim_paths=unbound_source_prim_paths,
            uncovered_assignment_groups=uncovered_assignment_groups,
            unbound_visible_mesh_paths=unbound_visible_mesh_paths,
            partially_bound_visible_mesh_paths=partially_bound_visible_mesh_paths,
            visible_render_mesh_count=visible_render_mesh_count,
            final_mesh_binding_coverage_score=final_mesh_binding_coverage_score,
        )

    monkeypatch.setattr(
        runner,
        "_build_material_assignment_child_prompt",
        lambda **_kwargs: "prompt",
    )
    monkeypatch.setattr(runner, "_run_child_agent", fake_run_child_agent)
    monkeypatch.setattr(
        runner,
        "_run_material_post_apply_review_turn",
        lambda **_kwargs: 0,
    )
    monkeypatch.setattr(
        runner,
        "_finalize_usd_cli_material_decisions",
        lambda **_kwargs: True,
    )
    monkeypatch.setattr(
        runner,
        "_ensure_material_assignment_artifacts",
        fake_ensure_artifacts,
    )
    monkeypatch.setattr(
        runner,
        "_snapshot_material_step_artifacts",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(
        runner,
        "_run_vqa_refinement_loop",
        lambda **_kwargs: 0,
    )
    monkeypatch.setattr(
        runner,
        "_restore_materialized_output",
        fake_restore_materialized_output,
    )
    monkeypatch.setattr(
        runner,
        "_record_materialized_output_status",
        fake_record_status,
    )
    result = runner.run_material_assignment(
        _usd_cli_material_assign_config(
            tmp_path,
            inputs,
            output_dir=run_dir,
            output_usd_path=output_usd,
        )
    )

    assignments = json.loads((run_dir / "assignments.json").read_text(encoding="utf-8"))
    assert assignments["coverage"]["material_assignment_prim_count"] == (
        50 if failure_mode == "coverage" else 51
    )
    summary = (run_dir / "final_summary.md").read_text(encoding="utf-8")
    assert "Coverage: 51/51" in summary
    events = [
        json.loads(line)
        for line in (run_dir / "trace" / "events.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()
    ]
    if failure_mode == "coverage":
        assert result.returncode == 2
        assert restore_calls == 0
        assert not output_usd.exists()
        coverage_event = next(
            event
            for event in events
            if event["summary"] == "Material assignment coverage gate failed."
        )
        assert coverage_event["data"]["coverage_gaps"] == [
            "Coverage gap: 1 visible candidate prim(s) have no proposed material assignment."
        ]
    elif failure_mode == "pending_annotation":
        assert result.returncode == 2
        assert restore_calls == 0
        assert not output_usd.exists()
        assert "materialized_usd" not in assignments
        assert "## Materialized USD" not in summary
        pending_event = next(
            event
            for event in events
            if event["summary"]
            == "Failed to record pending materialized USD status before restore."
        )
        assert pending_event["event_type"] == "error"
        assert pending_event["data"] == {
            "error_type": "RuntimeError",
            "error": "status artifact is read-only",
        }
    elif failure_mode == "restore":
        assert result.returncode == 2
        assert restore_calls == 1
        assert assignments["materialized_usd"]["status"] == "failed"
        assert assignments["materialized_usd"]["error"] == (
            "HTTP 500: Internal server error"
        )
        assert "- Status: **FAILED**" in summary
        assert "RuntimeError: HTTP 500: Internal server error" in summary
        restore_event = next(
            event
            for event in events
            if event["summary"]
            == "Failed to restore accepted materials to durable USD."
        )
        assert restore_event["data"] == {
            "error_type": "RuntimeError",
            "error": "HTTP 500: Internal server error",
        }
    elif failure_mode == "partial":
        assert result.returncode == 2
        assert restore_calls == 1
        assert output_usd.is_file()
        assert assignments["materialized_usd"] == {
            "status": "partial",
            "requested_output_path": str(output_usd),
            "output_path": str(output_usd),
            "unbound_source_prim_paths": ["/World/B"],
            "uncovered_assignment_groups": [
                {
                    "source_prim_paths": ["/World/A", "/World/B"],
                    "runtime_prim_paths": [],
                    "original_source_aliases": {},
                }
            ],
        }
        assert "- Status: **PARTIAL**" in summary
        assert '- Unbound source prim paths: `["/World/B"]`' in summary
        coverage_event = next(
            event
            for event in events
            if event["summary"] == "Material assignment delivery coverage gate failed."
        )
        assert coverage_event["event_type"] == "error"
    else:
        assert result.returncode == 2
        assert restore_calls == 1
        assert output_usd.is_file()
        assert assignments["materialized_usd"]["status"] == "pending"
        assert "- Status: **PENDING**" in summary
        assert not any(
            event["summary"] == "Failed to restore accepted materials to durable USD."
            for event in events
        )
        annotation_event = next(
            event
            for event in events
            if event["summary"]
            == (
                "Restored durable USD but failed to record its final "
                "materialization status."
            )
        )
        assert annotation_event["data"] == {
            "error_type": "RuntimeError",
            "error": "status artifact is read-only",
        }
        assert annotation_event["event_type"] == "error"


def test_delegated_evidence_gate_runs_before_materialized_restore(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    inputs = _write_usd_cli_material_inputs(tmp_path)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)
    output_usd = tmp_path / "materialized.usda"
    run_dir = tmp_path / "run"
    call_order: list[str] = []

    def fake_run_child_agent(**kwargs: object) -> int:
        child_final_path = kwargs["child_final_path"]
        assert isinstance(child_final_path, Path)
        child_final_path.write_text("done", encoding="utf-8")
        return 0

    def reject_evidence(**_kwargs: object) -> Path:
        call_order.append("verify")
        raise UnsafeRunArtifactError("final evidence mismatch")

    def reject_restore(**_kwargs: object) -> runner.MaterializedOutputResult:
        call_order.append("restore")
        raise AssertionError("restore must not run before evidence verification")

    monkeypatch.setattr(
        runner,
        "_build_material_assignment_child_prompt",
        lambda **_kwargs: "prompt",
    )
    monkeypatch.setattr(
        runner,
        "_prepare_delegated_vision_turn",
        lambda **kwargs: (str(kwargs["prompt"]), []),
    )
    monkeypatch.setattr(runner, "_run_child_agent", fake_run_child_agent)
    monkeypatch.setattr(
        runner,
        "_run_material_post_apply_review_turn",
        lambda **_kwargs: 0,
    )
    monkeypatch.setattr(
        runner,
        "_finalize_usd_cli_material_decisions",
        lambda **_kwargs: True,
    )
    monkeypatch.setattr(
        runner,
        "_ensure_material_assignment_artifacts",
        lambda **_kwargs: True,
    )
    monkeypatch.setattr(
        runner,
        "_snapshot_material_step_artifacts",
        lambda **_kwargs: None,
    )
    monkeypatch.setattr(runner, "_run_vqa_refinement_loop", lambda **_kwargs: 0)
    monkeypatch.setattr(
        runner,
        "_write_delegated_vision_evidence_verification",
        reject_evidence,
    )
    monkeypatch.setattr(runner, "_restore_materialized_output", reject_restore)
    with pytest.raises(UnsafeRunArtifactError, match="final evidence mismatch"):
        runner.run_material_assignment(
            _usd_cli_material_assign_config(
                tmp_path,
                inputs,
                output_dir=run_dir,
                output_usd_path=output_usd,
                vision_backend="test_vision_backend",
                vision_model="test_vision_model",
            )
        )

    assert call_order == ["verify"]
    assert not output_usd.exists()
    assert not (run_dir / "raw" / "materialized_output_status.json").exists()


