def test_physics_outer_manifest_seals_final_multi_iteration_artifacts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    physics_packet_writer: Any,
) -> None:
    usd = tmp_path / "asset.usda"
    usd.write_text("#usda 1.0\n", encoding="utf-8")
    run_dir = tmp_path / "physics-run"
    finalize_iterations: list[int] = []
    monkeypatch.setattr(runner, "usd_cli_source_distributed", lambda _root: True)
    _use_active_usd_cli_telemetry_route(monkeypatch, tmp_path)

    monkeypatch.setattr(
        runner,
        "_prepare_physics_run_packet",
        lambda _config, packet_run_dir, **_kwargs: _write_staged_physics_packet(
            physics_packet_writer,
            run_dir=packet_run_dir,
            source_usd=usd,
        ),
    )

    patch_path = run_dir / "raw" / "physics_decision_patch.json"

    def fake_child_agent(**kwargs: Any) -> int:
        child_output_path = Path(kwargs["child_output_path"])
        child_output_path.write_text("ok\n", encoding="utf-8")
        Path(kwargs["child_final_path"]).write_text("done\n", encoding="utf-8")
        if child_output_path.name == "child-output.log":
            patch_path.write_text(
                json.dumps({"schema_version": "test", "revision": 1}),
                encoding="utf-8",
            )
        elif "physics_visual_review_1_" in child_output_path.name:
            patch_path.write_text(
                json.dumps({"schema_version": "test", "revision": 2}),
                encoding="utf-8",
            )
        else:
            (run_dir / "physics_behavior_assessment.json").write_text(
                json.dumps(
                    {
                        "schema_version": (
                            "content-agent-workflows.physics-behavior-assessment.v1"
                        ),
                        "status": "pass",
                        "checked_views": [str(run_dir / "runtime" / "frame_0000.png")],
                        "runtime_report": str(
                            run_dir / "runtime" / "runtime_validation_report.json"
                        ),
                        "rendered_frames": [
                            str(run_dir / "runtime" / "frame_0000.png")
                        ],
                        "issues_found": [],
                        "issues_fixed": [],
                        "unresolved_issues": [],
                        "assessment_notes": "Second iteration passed.",
                    }
                ),
                encoding="utf-8",
            )
        return 0

    def fake_finalize_once(**kwargs: Any) -> dict[str, Any]:
        iteration = int(kwargs["iteration"])
        finalize_iterations.append(iteration)
        evidence_path = run_dir / "validation_evidence.json"
        assignments_path = run_dir / "physics_assignments.json"
        output_path = run_dir / "physics.usda"
        report_path, frame_path = _write_physics_ovrtx_review_evidence(
            run_dir,
            iteration=iteration,
        )
        receipt_path = _write_test_physics_render_receipt(
            run_dir=run_dir,
            runtime_report_path=report_path,
            frame_path=frame_path,
            iteration=iteration,
        )
        output_path.write_text(
            f"#usda 1.0\n# iteration {iteration}\n",
            encoding="utf-8",
        )
        evidence = physics_validation_evidence(
            asset=str(usd),
            target_runtime="fake",
            physics_properties_status="pass",
            runtime_loadability_status="pass",
            no_explosions_status="pass",
        )
        evidence_path.write_text(
            json.dumps(evidence.model_dump(mode="json"), indent=2),
            encoding="utf-8",
        )
        assignments_path.write_text(
            json.dumps(
                {
                    "schema_version": "test",
                    "iteration": iteration,
                    "decisions": [],
                }
            ),
            encoding="utf-8",
        )
        nested_manifest = (
            run_dir
            / "raw"
            / "physics_workflow"
            / f"iteration-{iteration:04d}"
            / "workflow_run_manifest.json"
        )
        nested_manifest.parent.mkdir(parents=True, exist_ok=True)
        nested_manifest.write_text(
            json.dumps({"iteration": iteration}),
            encoding="utf-8",
        )
        return {
            "success": True,
            "validation_status": "pass",
            "physics_usd_path": str(output_path),
            "validation_evidence_path": str(evidence_path),
            "assignments_path": str(assignments_path),
            "simulation_report_path": str(report_path),
            "workflow_run_manifest_path": str(nested_manifest),
            "rendered_frames": [str(frame_path.resolve())],
            "render_frame_receipt_path": str(receipt_path.resolve()),
        }

    monkeypatch.setattr(runner, "_run_child_agent", fake_child_agent)
    monkeypatch.setattr(runner, "_finalize_physics_once", fake_finalize_once)
    result = run_physics_apply(
        PhysicsApplyConfig(
            repo_root=tmp_path,
            usd_path=usd,
            output_dir=run_dir,
            simulation_engine="fake",
            vqa_refinement_max_iterations=2,
        )
    )

    assert result.returncode == 0
    assert finalize_iterations == [1, 2]
    manifest = json.loads(result.workflow_run_manifest_path.read_text(encoding="utf-8"))
    records = {record["logical_name"]: record for record in manifest["artifacts"]}
    assert manifest["status"] == "pass"
    assert records["validation_evidence"]["sha256"] == runner._file_digest(
        run_dir / "validation_evidence.json"
    )
    assert records["assignments"]["sha256"] == runner._file_digest(
        run_dir / "physics_assignments.json"
    )
    assert records["physics_usd"]["sha256"] == runner._file_digest(
        run_dir / "physics.usda"
    )
    assert records["physics_iteration_manifest_1"]["required"] is False
    assert records["physics_iteration_manifest_2"]["required"] is False


